package main

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"
	"time"
)

type ApiError struct {
	Status  int
	Code    string
	Message string
}

func (e *ApiError) Error() string { return e.Message }

func apiErr(status int, code, msg string) *ApiError {
	return &ApiError{Status: status, Code: code, Message: msg}
}

type opCtx struct {
	svc  *Service
	r    *http.Request
	user *User
	sess *Session
	body J
	raw  []byte
}

type opHandler func(c *opCtx) (int, interface{}, *ApiError)

func writeJSON(w http.ResponseWriter, status int, v interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	enc := json.NewEncoder(w)
	_ = enc.Encode(v)
}

func writeErr(w http.ResponseWriter, e *ApiError) {
	writeJSON(w, e.Status, J{
		"error": J{"code": e.Code, "message": e.Message},
	})
}

func decodeBody(r *http.Request) (J, []byte, *ApiError) {
	raw, err := io.ReadAll(io.LimitReader(r.Body, 1<<20))
	if err != nil || len(raw) == 0 {
		return nil, nil, apiErr(400, "invalid_json", "request body must be a JSON object")
	}
	var body J
	if err := json.Unmarshal(raw, &body); err != nil {
		return nil, nil, apiErr(400, "invalid_json", "request body is not valid JSON")
	}
	if body == nil {
		return nil, nil, apiErr(400, "invalid_json", "request body must be a JSON object")
	}
	return body, raw, nil
}

func checkFields(body J, allowed ...string) *ApiError {
	set := map[string]bool{}
	for _, a := range allowed {
		set[a] = true
	}
	for k := range body {
		if !set[k] {
			return apiErr(400, "invalid_json", fmt.Sprintf("unknown field %q", k))
		}
	}
	return nil
}

func reqStr(body J, key string) (string, *ApiError) {
	v, ok := body[key]
	if !ok || v == nil {
		return "", apiErr(400, "invalid_json", fmt.Sprintf("missing required field %q", key))
	}
	s, ok := v.(string)
	if !ok || s == "" {
		return "", apiErr(400, "invalid_json", fmt.Sprintf("field %q must be a non-empty string", key))
	}
	return s, nil
}

func optStr(body J, key string) (string, *ApiError) {
	v, ok := body[key]
	if !ok || v == nil {
		return "", nil
	}
	s, ok := v.(string)
	if !ok {
		return "", apiErr(400, "invalid_json", fmt.Sprintf("field %q must be a string", key))
	}
	return s, nil
}

func reqBool(body J, key string) (bool, *ApiError) {
	v, ok := body[key]
	if !ok || v == nil {
		return false, apiErr(400, "invalid_json", fmt.Sprintf("missing required field %q", key))
	}
	b, ok := v.(bool)
	if !ok {
		return false, apiErr(400, "invalid_json", fmt.Sprintf("field %q must be a boolean", key))
	}
	return b, nil
}

func optBool(body J, key string, def bool) (bool, *ApiError) {
	v, ok := body[key]
	if !ok || v == nil {
		return def, nil
	}
	b, ok := v.(bool)
	if !ok {
		return false, apiErr(400, "invalid_json", fmt.Sprintf("field %q must be a boolean", key))
	}
	return b, nil
}

func reqNum(body J, key string) (float64, *ApiError) {
	v, ok := body[key]
	if !ok || v == nil {
		return 0, apiErr(400, "invalid_json", fmt.Sprintf("missing required field %q", key))
	}
	n, ok := v.(float64)
	if !ok {
		return 0, apiErr(400, "invalid_json", fmt.Sprintf("field %q must be a number", key))
	}
	return n, nil
}

func optNum(body J, key string, def float64) (float64, *ApiError) {
	v, ok := body[key]
	if !ok || v == nil {
		return def, nil
	}
	n, ok := v.(float64)
	if !ok {
		return 0, apiErr(400, "invalid_json", fmt.Sprintf("field %q must be a number", key))
	}
	return n, nil
}

func reqInt(body J, key string) (int, *ApiError) {
	n, err := reqNum(body, key)
	if err != nil {
		return 0, err
	}
	if n != float64(int(n)) {
		return 0, apiErr(400, "invalid_json", fmt.Sprintf("field %q must be an integer", key))
	}
	return int(n), nil
}

func optStrList(body J, key string) ([]string, *ApiError) {
	v, ok := body[key]
	if !ok || v == nil {
		return nil, nil
	}
	arr, ok := v.([]interface{})
	if !ok {
		return nil, apiErr(400, "invalid_json", fmt.Sprintf("field %q must be an array of strings", key))
	}
	out := []string{}
	for _, item := range arr {
		s, ok := item.(string)
		if !ok {
			return nil, apiErr(400, "invalid_json", fmt.Sprintf("field %q must be an array of strings", key))
		}
		out = append(out, s)
	}
	return out, nil
}

func reqCoord(body J, key string, errCode string) (Coordinate, *ApiError) {
	v, ok := body[key]
	if !ok || v == nil {
		return Coordinate{}, apiErr(400, "invalid_json", fmt.Sprintf("missing required field %q", key))
	}
	m, ok := v.(map[string]interface{})
	if !ok {
		return Coordinate{}, apiErr(400, errCode, fmt.Sprintf("field %q must be a coordinate object", key))
	}
	lat, ok1 := m["latitude"].(float64)
	lng, ok2 := m["longitude"].(float64)
	if !ok1 || !ok2 {
		return Coordinate{}, apiErr(400, errCode, "coordinate requires numeric latitude and longitude")
	}
	c := Coordinate{Latitude: lat, Longitude: lng}
	if !validCoordinate(c) {
		return Coordinate{}, apiErr(400, errCode, "coordinate out of range")
	}
	return c, nil
}

func reqTimeField(body J, key string) (time.Time, *ApiError) {
	s, err := reqStr(body, key)
	if err != nil {
		return time.Time{}, err
	}
	t, perr := parseTime(s)
	if perr != nil {
		return time.Time{}, apiErr(400, "invalid_time", fmt.Sprintf("field %q is not a valid RFC3339 time", key))
	}
	return t, nil
}

func optTimeField(body J, key string) (*time.Time, *ApiError) {
	s, err := optStr(body, key)
	if err != nil {
		return nil, err
	}
	if s == "" {
		return nil, nil
	}
	t, perr := parseTime(s)
	if perr != nil {
		return nil, apiErr(400, "invalid_time", fmt.Sprintf("field %q is not a valid RFC3339 time", key))
	}
	return &t, nil
}

// ---------- auth ----------

func (s *Service) authenticate(r *http.Request) (*User, *Session, *ApiError) {
	h := r.Header.Get("Authorization")
	if h == "" || !strings.HasPrefix(h, "Bearer ") {
		return nil, nil, apiErr(401, "unauthorized", "missing bearer [REDACTED]")
	}
	token := strings.TrimSpace(strings.TrimPrefix(h, "Bearer "))
	sess := s.state.Sessions[token]
	if sess == nil {
		return nil, nil, apiErr(401, "unauthorized", "invalid or expired token")
	}
	user := s.state.Users[sess.UserID]
	if user == nil || !user.Active {
		return nil, nil, apiErr(401, "unauthorized", "user is not active")
	}
	return user, sess, nil
}

func (c *opCtx) requireRole(roles ...string) *ApiError {
	if c.sess.ActiveRole == "" {
		return apiErr(409, "role_not_selected", "select an active role before performing this action")
	}
	for _, r := range roles {
		if c.sess.ActiveRole == r {
			return nil
		}
	}
	return apiErr(403, "forbidden", fmt.Sprintf("role %q is not permitted to perform this action", c.sess.ActiveRole))
}

func (c *opCtx) audit(action, entityType, entityID, sampleID string, success bool, details map[string]interface{}) {
	actorID, role := "", ""
	if c.user != nil {
		actorID = c.user.ID
	}
	if c.sess != nil {
		role = c.sess.ActiveRole
	}
	c.svc.audit(actorID, role, action, entityType, entityID, sampleID, success, details)
}

// ---------- idempotency ----------

func payloadHash(raw []byte) string {
	h := sha256.Sum256(raw)
	return hex.EncodeToString(h[:])
}

// runIdempotent wraps a mutating operation with idempotency-key handling.
func (s *Service) runIdempotent(c *opCtx, op string, required bool, fn func() (int, interface{}, *ApiError)) (int, interface{}, *ApiError) {
	key, _ := optStr(c.body, "idempotencyKey")
	if key == "" {
		if required {
			return 0, nil, apiErr(400, "idempotency_required", "idempotencyKey is required for this operation")
		}
		return fn()
	}
	fullKey := op + ":" + c.user.ID + ":" + key
	if rec := s.state.Idempotency[fullKey]; rec != nil {
		if rec.PayloadHash != payloadHash(c.raw) {
			return 0, nil, apiErr(409, "idempotency_conflict", "idempotency key was already used with a different payload")
		}
		var stored interface{}
		if err := json.Unmarshal(rec.Response, &stored); err != nil {
			return 0, nil, apiErr(500, "internal_error", "failed to replay stored response")
		}
		return rec.StatusCode, stored, nil
	}
	status, resp, aerr := fn()
	if aerr != nil {
		return 0, nil, aerr
	}
	raw, err := json.Marshal(resp)
	if err != nil {
		return 0, nil, apiErr(500, "internal_error", "failed to encode response")
	}
	s.state.Idempotency[fullKey] = &IdemRecord{
		Key: key, Op: op, UserID: c.user.ID, PayloadHash: payloadHash(c.raw),
		StatusCode: status, Response: raw, CreatedAt: time.Now().UTC(),
	}
	return status, resp, nil
}

// ---------- routing ----------

type route struct {
	method  string
	path    string
	handler opHandler
	auth    bool // requires authentication
}

func (s *Service) routes() []route {
	return []route{
		{"POST", "/api/authenticate-user", s.hAuthenticate, false},
		{"POST", "/api/select-active-role", s.hSelectActiveRole, true},
		{"GET", "/api/ui/bootstrap", s.hBootstrap, true},
		{"GET", "/api/events", s.hEvents, true},
		{"POST", "/api/check-serviceability", s.hCheckServiceability, true},
		{"POST", "/api/create-collection-request", s.hCreateCollectionRequest, true},
		{"POST", "/api/ingest-presealed-sample", s.hIngestPresealed, true},
		{"POST", "/api/list-role-work", s.hListRoleWork, true},
		{"GET", "/api/read-sample-state", s.hReadSampleState, true},
		{"GET", "/api/read-sample-lifecycle", s.hReadSampleLifecycle, true},
		{"GET", "/api/read-journey-plan", s.hReadJourneyPlan, true},
		{"GET", "/api/read-operations-state", s.hReadOperationsState, true},
		{"GET", "/api/read-serviceability-snapshot", s.hReadServiceabilitySnapshot, true},
		{"POST", "/api/create-user", s.hCreateUser, true},
		{"POST", "/api/update-user-access", s.hUpdateUserAccess, true},
		{"GET", "/api/read-user", s.hReadUser, true},
		{"POST", "/api/create-location", s.hCreateLocation, true},
		{"POST", "/api/update-location", s.hUpdateLocation, true},
		{"POST", "/api/set-location-status", s.hSetLocationStatus, true},
		{"POST", "/api/set-location-function-status", s.hSetLocationFunctionStatus, true},
		{"POST", "/api/create-connection", s.hCreateConnection, true},
		{"POST", "/api/set-connection-status", s.hSetConnectionStatus, true},
		{"POST", "/api/create-sample-type", s.hCreateSampleType, true},
		{"POST", "/api/update-sample-type", s.hUpdateSampleType, true},
		{"POST", "/api/configure-capacity", s.hConfigureCapacity, true},
		{"POST", "/api/configure-laboratory-acceptance", s.hConfigureLabAcceptance, true},
		{"POST", "/api/set-worker-availability", s.hSetWorkerAvailability, true},
		{"POST", "/api/accept-assignment", s.hAcceptAssignment, true},
		{"POST", "/api/decline-assignment", s.hDeclineAssignment, true},
		{"POST", "/api/collect-and-seal-sample", s.hCollectAndSeal, true},
		{"POST", "/api/record-worker-location", s.hRecordWorkerLocation, true},
		{"POST", "/api/update-assignment-progress", s.hUpdateAssignmentProgress, true},
		{"POST", "/api/initiate-handoff", s.hInitiateHandoff, true},
		{"POST", "/api/confirm-handoff", s.hConfirmHandoff, true},
		{"POST", "/api/record-handling-checkpoint", s.hRecordHandlingCheckpoint, true},
		{"POST", "/api/confirm-laboratory-receipt", s.hConfirmLabReceipt, true},
		{"POST", "/api/record-laboratory-exception", s.hRecordLabException, true},
		{"POST", "/api/cancel-journey", s.hCancelJourney, true},
		{"POST", "/api/split-journey", s.hSplitJourney, true},
		{"POST", "/api/merge-journeys", s.hMergeJourneys, true},
		{"POST", "/api/reroute-journey", s.hRerouteJourney, true},
		{"POST", "/api/edit-active-plan", s.hEditActivePlan, true},
		{"POST", "/api/report-disruption", s.hReportDisruption, true},
		{"POST", "/api/search-audit-trail", s.hSearchAuditTrail, true},
	}
}

func (s *Service) ServeAPI(w http.ResponseWriter, r *http.Request) {
	// path params: /api/read-sample-state/{id} style
	path := r.URL.Path
	var pathID string
	for _, prefix := range []string{"/api/read-sample-state/", "/api/read-sample-lifecycle/", "/api/read-journey-plan/", "/api/read-user/"} {
		if strings.HasPrefix(path, prefix) {
			pathID = strings.TrimPrefix(path, prefix)
			path = strings.TrimSuffix(prefix, "/")
			break
		}
	}
	for _, rt := range s.routes() {
		if rt.path == path && rt.method == r.Method {
			s.serveRoute(w, r, rt, pathID)
			return
		}
	}
	// method mismatch on known path?
	for _, rt := range s.routes() {
		if rt.path == path {
			writeErr(w, apiErr(400, "invalid_json", "method not allowed"))
			return
		}
	}
	writeErr(w, apiErr(404, "not_found", "resource not found"))
}

func (s *Service) serveRoute(w http.ResponseWriter, r *http.Request, rt route, pathID string) {
	var user *User
	var sess *Session
	if rt.auth {
		s.mu.Lock()
		u, se, aerr := s.authenticate(r)
		s.mu.Unlock()
		if aerr != nil {
			writeErr(w, aerr)
			return
		}
		user, sess = u, se
	}
	var body J
	var raw []byte
	if r.Method == "POST" {
		var aerr *ApiError
		body, raw, aerr = decodeBody(r)
		if aerr != nil {
			s.mu.Lock()
			s.audit(userIDOf(user), roleOf(sess), opName(rt.path), "", "", "", false, map[string]interface{}{"error": aerr.Code})
			_ = s.persist()
			s.mu.Unlock()
			writeErr(w, aerr)
			return
		}
	}
	c := &opCtx{svc: s, r: r, user: user, sess: sess, body: body, raw: raw}
	if pathID != "" {
		c.body = J{}
		if body != nil {
			c.body = body
		}
		c.body["_pathId"] = pathID
	}
	s.mu.Lock()
	status, resp, aerr := rt.handler(c)
	if aerr == nil {
		if perr := s.persist(); perr != nil {
			s.mu.Unlock()
			writeErr(w, apiErr(500, "internal_error", "failed to persist state"))
			return
		}
	} else {
		// audit the failure, then persist audit only (state mutations from failed
		// ops are discarded by reloading? no — failed ops must not mutate state)
		s.pendingAudits = append(s.pendingAudits, &AuditRow{
			AuditID: newUUID(), ActorID: userIDOf(user), Role: roleOf(sess),
			Action: opName(rt.path), Success: false, OccurredAt: time.Now().UTC(),
			Details: []byte(fmt.Sprintf(`{"error":%q}`, aerr.Code)),
		})
		_ = s.persist()
	}
	s.mu.Unlock()
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	writeJSON(w, status, resp)
}

func userIDOf(u *User) string {
	if u == nil {
		return ""
	}
	return u.ID
}

func roleOf(s *Session) string {
	if s == nil {
		return ""
	}
	return s.ActiveRole
}

func opName(path string) string {
	return strings.TrimPrefix(path, "/api/")
}

