func (s *Service) ServeAPI(w http.ResponseWriter, r *http.Request) {
	// path params: /api/read-sample-state/{id} style
	path := r.URL.Path
	var pathID string
	for _, prefix := range []string{"/api/read-sample-state/", "/api/read-sample-lifecycle/", "/api/read-journey-plan/", "/api/read-user/"} {
		if strings.HasPrefix(path, prefix) {
			pathID = strings.TrimPrefix(path, prefix)
			path = strings.TrimSuffix(prefix, "/")
			break
		}
	}
	for _, rt := range s.routes() {
		if rt.path == path && rt.method == r.Method {
			s.serveRoute(w, r, rt, pathID)
			return
		}
	}
	// method mismatch on known path?
	for _, rt := range s.routes() {
		if rt.path == path {
			writeErr(w, apiErr(400, "invalid_json", "method not allowed"))
			return
		}
	}
	writeErr(w, apiErr(404, "not_found", "resource not found"))
}

func (s *Service) serveRoute(w http.ResponseWriter, r *http.Request, rt route, pathID string) {
	var user *User
	var sess *Session
	if rt.auth {
		s.mu.Lock()
		u, se, aerr := s.authenticate(r)
		s.mu.Unlock()
		if aerr != nil {
			writeErr(w, aerr)
			return
		}
		user, sess = u, se
	}
	var body J
	var raw []byte
	if r.Method == "POST" {
		var aerr *ApiError
		body, raw, aerr = decodeBody(r)
		if aerr != nil {
			s.mu.Lock()
			s.audit(userIDOf(user), roleOf(sess), opName(rt.path), "", "", "", false, map[string]interface{}{"error": aerr.Code})
			_ = s.persist()
			s.mu.Unlock()
			writeErr(w, aerr)
			return
		}
	}
	c := &opCtx{svc: s, r: r, user: user, sess: sess, body: body, raw: raw}
	if pathID != "" {
		c.body = J{}
		if body != nil {
			c.body = body
		}
		c.body["_pathId"] = pathID
	}
	s.mu.Lock()
	status, resp, aerr := rt.handler(c)
	if aerr == nil {
		if perr := s.persist(); perr != nil {
			s.mu.Unlock()
			writeErr(w, apiErr(500, "internal_error", "failed to persist state"))
			return
		}
	} else {
		// audit the failure, then persist audit only (state mutations from failed
		// ops are discarded by reloading? no — failed ops must not mutate state)
		s.pendingAudits = append(s.pendingAudits, &AuditRow{
			AuditID: newUUID(), ActorID: userIDOf(user), Role: roleOf(sess),
			Action: opName(rt.path), Success: false, OccurredAt: time.Now().UTC(),
			Details: []byte(fmt.Sprintf(`{"error":%q}`, aerr.Code)),
		})
		_ = s.persist()
	}
	s.mu.Unlock()
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	writeJSON(w, status, resp)
}

func userIDOf(u *User) string {
	if u == nil {
		return ""
	}
	return u.ID
}

func roleOf(s *Session) string {
	if s == nil {
		return ""
	}
	return s.ActiveRole
}

func opName(path string) string {
	return strings.TrimPrefix(path, "/api/")
}
