// ---------- capacity ----------

func (s *Service) hConfigureCapacity(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleAdministrator, RoleNodeHandler, RoleLaboratoryTeam); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "resourceId", "capacityUnits", "cooledCapacityUnits", "idempotencyKey"); err != nil {
		return 0, nil, err
	}
	return s.runIdempotent(c, "configure_capacity", true, func() (int, interface{}, *ApiError) {
		resourceID, err := reqStr(c.body, "resourceId")
		if err != nil {
			return 0, nil, err
		}
		units, err := reqInt(c.body, "capacityUnits")
		if err != nil {
			return 0, nil, err
		}
		if units < 0 {
			return 0, nil, apiErr(400, "invalid_capacity", "capacityUnits must be >= 0")
		}
		cooled, err := optNum(c.body, "cooledCapacityUnits", 0)
		if err != nil {
			return 0, nil, err
		}
		if cooled < 0 {
			return 0, nil, apiErr(400, "invalid_capacity", "cooledCapacityUnits must be >= 0")
		}
		var pool *CapacityPool
		resourceType := ""
		if loc := s.state.Locations[resourceID]; loc != nil && !loc.Implicit {
			pool = &loc.Capacity
			resourceType = "location"
			if c.sess.ActiveRole == RoleNodeHandler || c.sess.ActiveRole == RoleLaboratoryTeam {
				if c.user.AssignedLocationID != loc.ID {
					return 0, nil, apiErr(403, "forbidden", "can only configure capacity at your assigned location")
				}
			}
		} else if conn := s.state.Connections[resourceID]; conn != nil {
			pool = &conn.Capacity
			resourceType = "connection"
			if c.sess.ActiveRole != RoleAdministrator {
				return 0, nil, apiErr(403, "forbidden", "only administrators can configure connection capacity")
			}
		} else {
			return 0, nil, apiErr(404, "not_found", "capacity resource not found")
		}
		if units < pool.ReservedUnits || int(cooled) < pool.CooledReservedUnits {
			return 0, nil, apiErr(409, "capacity_reserved", "cannot set capacity below currently reserved units")
		}
		pool.CapacityUnits = units
		pool.CooledCapacityUnits = int(cooled)
		s.networkChanged()
		c.audit("configure_capacity", resourceType, resourceID, "", true, map[string]interface{}{
			"capacityUnits": units, "cooledCapacityUnits": int(cooled),
		})
		s.emit("capacity.updated", resourceType, jID(resourceID), capacityView(*pool))
		return 200, J{
			"resourceId": resourceID, "capacityUnits": pool.CapacityUnits,
			"reservedUnits": pool.ReservedUnits, "availableUnits": pool.CapacityUnits - pool.ReservedUnits,
			"cooledCapacityUnits": pool.CooledCapacityUnits, "cooledReservedUnits": pool.CooledReservedUnits,
			"cooledAvailableUnits": pool.CooledCapacityUnits - pool.CooledReservedUnits,
		}, nil
	})
}

