func (s *Service) hCreateConnection(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleAdministrator); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "fromLocationId", "toLocationId", "travelMinutes", "costUnits", "cooled", "active", "idempotencyKey"); err != nil {
		return 0, nil, err
	}
	return s.runIdempotent(c, "create_connection", true, func() (int, interface{}, *ApiError) {
		fromID, err := reqStr(c.body, "fromLocationId")
		if err != nil {
			return 0, nil, err
		}
		toID, err := reqStr(c.body, "toLocationId")
		if err != nil {
			return 0, nil, err
		}
		travel, err := reqInt(c.body, "travelMinutes")
		if err != nil {
			return 0, nil, err
		}
		if travel < 1 {
			return 0, nil, apiErr(400, "invalid_travel_minutes", "travelMinutes must be >= 1")
		}
		cost, err := reqNum(c.body, "costUnits")
		if err != nil {
			return 0, nil, err
		}
		if cost < 0 {
			return 0, nil, apiErr(400, "invalid_cost", "costUnits must be >= 0")
		}
		cooled, err := optBool(c.body, "cooled", false)
		if err != nil {
			return 0, nil, err
		}
		active, err := reqBool(c.body, "active")
		if err != nil {
			return 0, nil, err
		}
		from := s.state.Locations[fromID]
		to := s.state.Locations[toID]
		if from == nil || from.Implicit || to == nil || to.Implicit {
			return 0, nil, apiErr(404, "not_found", "connection endpoint location not found")
		}
		if fromID == toID {
			return 0, nil, apiErr(400, "invalid_json", "fromLocationId and toLocationId must differ")
		}
		conn := &Connection{
			ID: newUUID(), FromLocationID: fromID, ToLocationID: toID,
			TravelMinutes: travel, CostUnits: cost, Cooled: cooled, Active: active,
			CreatedAt: time.Now().UTC(),
		}
		s.state.Connections[conn.ID] = conn
		s.networkChanged()
		c.audit("create_connection", "connection", conn.ID, "", true, map[string]interface{}{
			"fromLocationId": fromID, "toLocationId": toID, "travelMinutes": travel,
		})
		s.emit("connection.created", "connection", conn.ID, connectionView(conn))
		return 201, connectionView(conn), nil
	})
}

