   286		}
   287		fullKey := op + ":" + c.user.ID + ":" + key
   288		if rec := s.state.Idempotency[fullKey]; rec != nil {
   289			if rec.PayloadHash != payloadHash(c.raw) {
   290				return 0, nil, apiErr(409, "idempotency_conflict", "idempotency key was already used with a different payload")
   291			}
   292			var stored interface{}
   293			if err := json.Unmarshal(rec.Response, &stored); err != nil {
   294				return 0, nil, apiErr(500, "internal_error", "failed to replay stored response")
   295			}
   296			return rec.StatusCode, stored, nil
   297		}
   298		status, resp, aerr := fn()
   299		if aerr != nil {
   300			return 0, nil, aerr
   301		}
   302		raw, err := json.Marshal(resp)
   303		if err != nil {
   304			return 0, nil, apiErr(500, "internal_error", "failed to encode response")
   305		}
   306		s.state.Idempotency[fullKey] = &IdemRecord{
   307			Key: key, Op: op, UserID: c.user.ID, PayloadHash: payloadHash(c.raw),
   308			StatusCode: status, Response: raw, CreatedAt: time.Now().UTC(),
   309		}
   310		return status, resp, nil
   311	}
