package main

import (
	"encoding/json"
	"log"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"time"
)

func seedSampleTypes(state *State) {
	if len(state.SampleTypes) > 0 {
		return
	}
	seed := []SampleType{
		{
			Name: "Amber", QualifiedCollectorRequired: true, RequiredQualification: "amber_collector",
			ContainerType: "standard", TemperatureMinC: 2, TemperatureMaxC: 25,
			IncompatibleSampleTypes: []string{}, RequiresCooledRoute: false, BatchingAllowed: true,
		},
		{
			Name: "Indigo", QualifiedCollectorRequired: true, RequiredQualification: "indigo_collector",
			ContainerType: "standard", TemperatureMinC: 2, TemperatureMaxC: 25,
			IncompatibleSampleTypes: []string{}, RequiresCooledRoute: false, BatchingAllowed: true,
		},
		{
			Name: "Frost", QualifiedCollectorRequired: true, RequiredQualification: "frost_collector",
			ContainerType: "cooled", TemperatureMinC: -20, TemperatureMaxC: 4,
			IncompatibleSampleTypes: []string{}, RequiresCooledRoute: true, BatchingAllowed: true,
		},
		{
			Name: "Pulse", QualifiedCollectorRequired: true, RequiredQualification: "pulse_collector",
			ContainerType: "standard", TemperatureMinC: 2, TemperatureMaxC: 25,
			IncompatibleSampleTypes: []string{}, RequiresCooledRoute: false, BatchingAllowed: false,
		},
	}
	for i := range seed {
		t := seed[i]
		t.ID = newUUID()
		state.SampleTypes[t.ID] = &t
	}
	// Indigo must not share a container with Amber
	var amberID, indigoID string
	for _, t := range state.SampleTypes {
		if t.Name == "Amber" {
			amberID = t.ID
		}
		if t.Name == "Indigo" {
			indigoID = t.ID
		}
	}
	if amberID != "" && indigoID != "" {
		state.SampleTypes[indigoID].IncompatibleSampleTypes = []string{amberID}
		state.SampleTypes[amberID].IncompatibleSampleTypes = []string{indigoID}
	}
}

func ensureAdmin(state *State) {
	for _, u := range state.Users {
		if u.HasRole(RoleAdministrator) {
			return
		}
	}
	username := os.Getenv("ADMIN_USERNAME")
	password := os.Getenv("ADMIN_PASSWORD")
	if username == "" {
		username = "admin"
	}
	if password == "" {
		password = "admin"
	}
	u := &User{
		ID: newUUID(), Username: username, Email: username + "@lab.local",
		FullName: "Administrator", Phone: "", Roles: []string{RoleAdministrator},
		Qualifications: []string{}, Certifications: []Certification{},
		Active: true, Available: true, CapacityUnits: 10, CreatedAt: time.Now().UTC(),
	}
	u.PasswordHash = hashPassword(password, u.ID[:8])
	state.Users[u.ID] = u
}

func main() {
	databaseURL := os.Getenv("DATABASE_URL")
	if databaseURL == "" {
		databaseURL = "postgres://postgres:postgres@127.0.0.1:5432/lab?sslmode=disable"
	}
	var store *Store
	var err error
	for i := 0; i < 30; i++ {
		store, err = OpenStore(databaseURL)
		if err == nil {
			break
		}
		log.Printf("waiting for database: %v", err)
		time.Sleep(time.Second)
	}
	if err != nil {
		log.Fatalf("database unavailable: %v", err)
	}
	state, err := store.LoadState()
	if err != nil {
		log.Fatalf("load state: %v", err)
	}
	if state == nil {
		state = NewState()
	}
	seedSampleTypes(state)
	ensureAdmin(state)
	svc := NewService(store, state)
	if state.Snapshot.Version < 1 || state.Snapshot.Status == "" {
		svc.networkChanged()
	}
	if err := svc.persist(); err != nil {
		log.Fatalf("initial persist: %v", err)
	}
	go func() {
		ticker := time.NewTicker(2 * time.Second)
		defer ticker.Stop()
		for range ticker.C {
			svc.mu.Lock()
			svc.Sweep()
			_ = svc.persist()
			svc.mu.Unlock()
		}
	}()

	frontendDir := os.Getenv("FRONTEND_DIR")
	if frontendDir == "" {
		frontendDir = "/workspace/frontend/dist"
	}
	mux := http.NewServeMux()
	mux.HandleFunc("/ready", func(w http.ResponseWriter, r *http.Request) {
		if err := store.Ping(); err != nil {
			w.WriteHeader(http.StatusServiceUnavailable)
			_ = json.NewEncoder(w).Encode(J{"status": "unavailable"})
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(J{"status": "ready"})
	})
	mux.HandleFunc("/api/", svc.ServeAPI)
	mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		p := filepath.Clean(r.URL.Path)
		if strings.Contains(p, "..") {
			http.NotFound(w, r)
			return
		}
		full := filepath.Join(frontendDir, p)
		if p == "/" || p == "." {
			full = filepath.Join(frontendDir, "index.html")
		}
		if st, err := os.Stat(full); err == nil && !st.IsDir() {
			http.ServeFile(w, r, full)
			return
		}
		// SPA fallback
		http.ServeFile(w, r, filepath.Join(frontendDir, "index.html"))
	})
	addr := os.Getenv("LISTEN_ADDR")
	if addr == "" {
		addr = "127.0.0.1:8080"
	}
	log.Printf("listening on %s", addr)
	if err := http.ListenAndServe(addr, mux); err != nil {
		log.Fatal(err)
	}
}

