		t := seed[i]
		t.ID = newUUID()
		state.SampleTypes[t.ID] = &t
	}
	// Indigo must not share a container with Amber
	var amberID, indigoID string
	for _, t := range state.SampleTypes {
		if t.Name == "Amber" {
			amberID = t.ID
		}
		if t.Name == "Indigo" {
			indigoID = t.ID
		}
	}
	if amberID != "" && indigoID != "" {
		state.SampleTypes[indigoID].IncompatibleSampleTypes = []string{amberID}
		state.SampleTypes[amberID].IncompatibleSampleTypes = []string{indigoID}
	}
}

func ensureAdmin(state *State) {
	for _, u := range state.Users {
		if u.HasRole(RoleAdministrator) {
			return
		}
	}
	username := os.Getenv("ADMIN_USERNAME")
	password := os.Getenv("ADMIN_PASSWORD")
	if username == "" {
		username = "admin"
	}
	if password == "" {
		password = "admin"
	}
	u := &User{
		ID: newUUID(), Username: username, Email: username + "@lab.local",
		FullName: "Administrator", Phone: "", Roles: []string{RoleAdministrator},
		Qualifications: []string{}, Certifications: []Certification{},
		Active: true, Available: true, CapacityUnits: 10, CreatedAt: time.Now().UTC(),
	}
	u.PasswordHash = hashPassword(password, u.ID[:8])
