    if not isinstance(s, dict): return str(s)
    if '$ref' in s: return 'ref:'+s['$ref'].split('/')[-1]
    t = s.get('type')
    if t == 'object':
        req = s.get('required', [])
        out = []
        for k, v in s.get('properties', {}).items():
            mark = '*' if k in req else ''
            out.append(f"{pad}{k}{mark}: {schema_str(v, indent+1)}")
        if s.get('additionalProperties') is False:
