        return '{\n' + '\n'.join(out) + '\n' + pad + '}'
    if t == 'array':
        return '[' + schema_str(s.get('items', {}), indent) + ']'
    if 'enum' in s:
        return f"{t}|{'|'.join(map(str,s['enum']))}"
    f = s.get('format','')
    return f"{t}:{f}" if f else str(t)

for p, ops in sorted(c['paths'].items()):
    for m, op in ops.items():
