import json
c = json.load(open('/workspace/contracts/openapi.contract.json'))

def schema_str(s, indent=0):
    pad = '  '*indent
    if not isinstance(s, dict): return str(s)
    if '$ref' in s: return 'ref:'+s['$ref'].split('/')[-1]
    t = s.get('type')
    if t == 'object':
        req = s.get('required', [])
        out = []
        for k, v in s.get('properties', {}).items():
            mark = '*' if k in req else ''
            out.append(f"{pad}{k}{mark}: {schema_str(v, indent+1)}")
        if s.get('additionalProperties') is False:
            out.append(pad+'[no-extra-props]')
        return '{\n' + '\n'.join(out) + '\n' + pad + '}'
    if t == 'array':
        return '[' + schema_str(s.get('items', {}), indent) + ']'
    if 'enum' in s:
        return f"{t}|{'|'.join(map(str,s['enum']))}"
    f = s.get('format','')
    return f"{t}:{f}" if f else str(t)

for p, ops in sorted(c['paths'].items()):
    for m, op in ops.items():
        print('='*70)
        print(m.upper(), p, '->', op.get('operationId'))
        rb = op.get('requestBody',{}).get('content',{}).get('application/json',{}).get('schema')
        if rb:
            print(' REQUEST:')
            print(' ', schema_str(rb, 1).replace('\n','\n  '))
        params = op.get('parameters', [])
        for prm in params:
            print(f" PARAM {prm.get('name')} in={prm.get('in')} req={prm.get('required')} {schema_str(prm.get('schema',{}))}")
        for code, resp in sorted(op.get('responses',{}).items()):
            sch = resp.get('content',{}).get('application/json',{}).get('schema',{})
            print(f" RESP {code}:")
            print('  ', schema_str(sch, 1).replace('\n','\n   '))

print('='*70)
print('COMPONENT SCHEMAS')
for name, s in c.get('components',{}).get('schemas',{}).items():
    print(f"--- {name}: {schema_str(s)}")

