   371	func (s *Service) ServeAPI(w http.ResponseWriter, r *http.Request) {
   372		// path params: /api/read-sample-state/{id} style
   373		path := r.URL.Path
   374		var pathID string
   375		for _, prefix := range []string{"/api/read-sample-state/", "/api/read-sample-lifecycle/", "/api/read-journey-plan/", "/api/read-user/"} {
   376			if strings.HasPrefix(path, prefix) {
   377				pathID = strings.TrimPrefix(path, prefix)
   378				path = strings.TrimSuffix(prefix, "/")
   379				break
   380			}
   381		}
   382		for _, rt := range s.routes() {
   383			if rt.path == path && rt.method == r.Method {
   384				s.serveRoute(w, r, rt, pathID)
   385				return
   386			}
   387		}
   388		// method mismatch on known path?
   389		for _, rt := range s.routes() {
   390			if rt.path == path {
   391				writeErr(w, apiErr(400, "invalid_json", "method not allowed"))
   392				return
   393			}
   394		}
   395		writeErr(w, apiErr(404, "not_found", "resource not found"))
   396	}
   397	
   398	func (s *Service) serveRoute(w http.ResponseWriter, r *http.Request, rt route, pathID string) {
   399		// WebSocket upgrades are handled outside the service lock
   400		if strings.ToLower(r.Header.Get("Upgrade")) == "websocket" {
   401			if r.URL.Path == "/api/events" {
   402				token := strings.TrimSpace(strings.TrimPrefix(r.Header.Get("Authorization"), "Bearer "))
   403				if token == "" {
   404					token = r.URL.Query().Get("token")
   405				}
   406				s.mu.Lock()
   407				sess := s.state.Sessions[token]
   408				s.mu.Unlock()
   409				if sess == nil {
   410					writeErr(w, apiErr(401, "unauthorized", "invalid token"))
   411					return
   412				}
   413				s.hub.ServeWS(w, r)
   414			} else {
   415				writeErr(w, apiErr(400, "invalid_json", "websocket not supported here"))
   416			}
   417			return
   418		}
   419		var user *User
   420		var sess *Session
   421		if rt.auth {
   422			s.mu.Lock()
   423			u, se, aerr := s.authenticate(r)
   424			s.mu.Unlock()
   425			if aerr != nil {
   426				writeErr(w, aerr)
   427				return
   428			}
   429			user, sess = u, se
   430		}
   431		var body J
   432		var raw []byte
   433		if r.Method == "POST" {
   434			var aerr *ApiError
   435			body, raw, aerr = decodeBody(r)
   436			if aerr != nil {
   437				s.mu.Lock()
   438				s.audit(userIDOf(user), roleOf(sess), opName(rt.path), "", "", "", false, map[string]interface{}{"error": aerr.Code})
   439				_ = s.persist()
   440				s.mu.Unlock()
   441				writeErr(w, aerr)
   442				return
   443			}
   444		}
   445		c := &opCtx{svc: s, r: r, user: user, sess: sess, body: body, raw: raw}
   446		if pathID != "" {
   447			c.body = J{}
   448			if body != nil {
   449				c.body = body
   450			}
   451			c.body["_pathId"] = pathID
   452		}
   453		s.mu.Lock()
   454		status, resp, aerr := rt.handler(c)
   455		if aerr == nil {
   456			if perr := s.persist(); perr != nil {
   457				s.mu.Unlock()
   458				writeErr(w, apiErr(500, "internal_error", "failed to persist state"))
   459				return
   460			}
   461		} else {
   462			// audit the failure, then persist audit only (state mutations from failed
   463			// ops are discarded by reloading? no — failed ops must not mutate state)
   464			s.pendingAudits = append(s.pendingAudits, &AuditRow{
   465				AuditID: newUUID(), ActorID: userIDOf(user), Role: roleOf(sess),
   466				Action: opName(rt.path), Success: false, OccurredAt: time.Now().UTC(),
   467				Details: []byte(fmt.Sprintf(`{"error":%q}`, aerr.Code)),
   468			})
   469			_ = s.persist()
   470		}
   471		s.mu.Unlock()
   472		if aerr != nil {
   473			writeErr(w, aerr)
   474			return
   475		}
   476		writeJSON(w, status, resp)
   477	}
