   289	func (s *Service) hConfigureCapacity(c *opCtx) (int, interface{}, *ApiError) {
   290		if err := c.requireRole(RoleAdministrator, RoleNodeHandler, RoleLaboratoryTeam); err != nil {
   291			return 0, nil, err
