   296		return s.runIdempotent(c, "configure_capacity", true, func() (int, interface{}, *ApiError) {
   297			resourceID, err := reqStr(c.body, "resourceId")
   298			if err != nil {
   299				return 0, nil, err
   300			}
   301			units, err := reqInt(c.body, "capacityUnits")
   302			if err != nil {
   303				return 0, nil, err
   304			}
   305			if units < 0 {
   306				return 0, nil, apiErr(400, "invalid_capacity", "capacityUnits must be >= 0")
   307			}
   308			cooled, err := optNum(c.body, "cooledCapacityUnits", 0)
   309			if err != nil {
   310				return 0, nil, err
   311			}
   312			if cooled < 0 {
   313				return 0, nil, apiErr(400, "invalid_capacity", "cooledCapacityUnits must be >= 0")
   314			}
   315			var pool *CapacityPool
   316			resourceType := ""
   317			if loc := s.state.Locations[resourceID]; loc != nil && !loc.Implicit {
   318				pool = &loc.Capacity
   319				resourceType = "location"
   320				if c.sess.ActiveRole == RoleNodeHandler || c.sess.ActiveRole == RoleLaboratoryTeam {
   321					if c.user.AssignedLocationID != loc.ID {
   322						return 0, nil, apiErr(403, "forbidden", "can only configure capacity at your assigned location")
   323					}
   324				}
