   330				}
   331			} else {
   332				return 0, nil, apiErr(404, "not_found", "capacity resource not found")
   333			}
   334			if units < pool.ReservedUnits || int(cooled) < pool.CooledReservedUnits {
   335				return 0, nil, apiErr(409, "capacity_reserved", "cannot set capacity below currently reserved units")
   336			}
   337			pool.CapacityUnits = units
   338			pool.CooledCapacityUnits = int(cooled)
   339			s.networkChanged()
   340			c.audit("configure_capacity", resourceType, resourceID, "", true, map[string]interface{}{
   341				"capacityUnits": units, "cooledCapacityUnits": int(cooled),
   342			})
