   344			return 200, J{
   345				"resourceId": resourceID, "capacityUnits": pool.CapacityUnits,
   346				"reservedUnits": pool.ReservedUnits, "availableUnits": pool.CapacityUnits - pool.ReservedUnits,
   347				"cooledCapacityUnits": pool.CooledCapacityUnits, "cooledReservedUnits": pool.CooledReservedUnits,
   348				"cooledAvailableUnits": pool.CooledCapacityUnits - pool.CooledReservedUnits,
