   476					sample := s.state.Samples[sid]
   477					if sample == nil {
   478						continue
   479					}
   480					if sample.Status == SampleReceived {
   481						return 0, nil, apiErr(409, "completed_work_immutable", "completed samples cannot be merged")
   482					}
   483					if len(sample.CompletedLegIDs) > 0 {
   484						return 0, nil, apiErr(409, "partial_journey_merge", "journeys with completed legs cannot be merged")
   485					}
   486					allSamples = append(allSamples, sample)
   487				}
   488			}
   489			if code, ok := samplesCompatible(s, allSamples); !ok {
   490				return 0, nil, apiErr(409, code, "samples are not allowed to travel together")
   491			}
   492			// routes must share the same target laboratory and entry node
   493			targetLab := ""
   494			targetEntry := ""
   495			if len(target.Stops) > 0 {
   496				targetLab = target.Stops[len(target.Stops)-1].LocationID
   497				for _, st := range target.Stops {
   498					if st.StopType == "handoff" {
   499						targetEntry = st.LocationID
   500						break
   501					}
   502				}
   503				if targetEntry == "" {
   504					targetEntry = target.Stops[0].LocationID
   505				}
   506			}
   507			for _, sj := range sources {
   508				if len(sj.Stops) == 0 {
   509					return 0, nil, apiErr(409, "invalid_merge", "source journey has no route")
   510				}
   511				lab := sj.Stops[len(sj.Stops)-1].LocationID
   512				if lab != targetLab {
   513					return 0, nil, apiErr(409, "invalid_merge", "journeys target different laboratories")
   514				}
   515				entry := ""
   516				for _, st := range sj.Stops {
   517					if st.StopType == "handoff" {
   518						entry = st.LocationID
   519						break
   520					}
   521				}
   522				if entry == "" {
   523					entry = sj.Stops[0].LocationID
   524				}
   525				if entry != targetEntry {
   526					return 0, nil, apiErr(409, "invalid_merge", "journeys follow different routes")
   527				}
   528			}
   529			// capacity check: every added sample reserves along the target route
   530			type reserveTarget struct {
   531				pool   *CapacityPool
   532				cooled bool
   533			}
   534			toReserve := []reserveTarget{}
   535			for _, sj := range sources {
   536				for _, sid := range sj.SampleIDs {
   537					sample := s.state.Samples[sid]
   538					cooled := sampleRequiresCooled(s, sample)
   539					for _, legID := range target.LegIDs {
   540						if a := s.state.Assignments[legID]; a != nil && a.ConnectionID != "" {
   541							if conn := s.state.Connections[a.ConnectionID]; conn != nil {
   542								toReserve = append(toReserve, reserveTarget{&conn.Capacity, cooled})
   543							}
   544						}
   545					}
   546					for _, id := range target.NodeAssignmentIDs {
   547						if a := s.state.Assignments[id]; a != nil {
   548							if loc := s.state.Locations[a.NodeID]; loc != nil {
   549								toReserve = append(toReserve, reserveTarget{&loc.Capacity, cooled})
   550							}
   551						}
   552					}
   553					for _, id := range target.LaboratoryAssignmentIDs {
   554						if a := s.state.Assignments[id]; a != nil {
   555							if loc := s.state.Locations[a.LaboratoryID]; loc != nil {
   556								toReserve = append(toReserve, reserveTarget{&loc.Capacity, cooled})
   557							}
   558						}
   559					}
   560				}
   561			}
   562			for _, rt := range toReserve {
   563				if rt.pool.Available(rt.cooled) < 1 {
   564					code := "capacity_exhausted"
   565					if rt.cooled {
   566						code = "cooled_capacity_exhausted"
   567					}
   568					return 0, nil, apiErr(409, code, "not enough capacity on the shared route")
   569				}
   570			}
   571			// deadline check: arrival must still meet every sample deadline
   572			for _, sj := range sources {
   573				for _, sid := range sj.SampleIDs {
   574					if sample := s.state.Samples[sid]; sample != nil && target.EstimatedDeliveryAt.After(sample.DeliveryDeadline) {
   575						return 0, nil, apiErr(409, "deadline_exceeded", "merged journey cannot meet every sample deadline")
   576					}
   577				}
   578			}
   579			for _, rt := range toReserve {
   580				rt.pool.Reserve(rt.cooled)
   581			}
   582			// move samples & collection assignments into target
   583			for _, sj := range sources {
   584				for _, sid := range sj.SampleIDs {
   585					sample := s.state.Samples[sid]
   586					target.SampleIDs = append(target.SampleIDs, sid)
   587					if sample != nil {
   588						sample.ActiveJourneyID = target.ID
   589						sample.TargetLaboratoryID = targetLab
   590					}
   591				}
   592				for _, id := range sj.CollectionAssignmentIDs {
   593					if a := s.state.Assignments[id]; a != nil && a.Status != AsgCancelled {
   594						a.JourneyID = target.ID
   595						target.CollectionAssignmentIDs = append(target.CollectionAssignmentIDs, id)
   596					}
   597				}
   598				// release source-only reservations and cancel source assignments
   599				s.cancelUnfinishedAssignments(sj, "merged")
   600				sj.Status = JourneyMerged
   601				sj.ReplanStatus = ReplanReplaced
   602				c.audit("merge_journeys", "journey", sj.ID, "", true, map[string]interface{}{"targetJourneyId": target.ID})
   603			}
   604			if len(target.SampleIDs) > 1 {
   605				target.RouteMode = "batched"
   606			}
   607			target.PlanVersion++
   608			c.audit("merge_journeys", "journey", target.ID, "", true, map[string]interface{}{
   609				"sourceJourneyIds": sourceIDs,
   610			})
   611			s.emit("journey.merged", "journey", target.ID, map[string]interface{}{
   612				"journeyId": target.ID, "sourceJourneyIds": sourceIDs,
   613			})
   614			return 201, s.journeyPlanView(target, 2), nil
   615		})
   616	}
