   754	func (s *Service) editReplaceWorker(c *opCtx, j *Journey, changes map[string]interface{}) *ApiError {
   755		asgID, _ := changes["assignmentId"].(string)
   756		workerID, _ := changes["workerId"].(string)
   757		if asgID == "" || workerID == "" {
   758			return apiErr(400, "invalid_json", "changes.assignmentId and changes.workerId are required")
   759		}
   760		a := s.state.Assignments[asgID]
   761		if a == nil || a.JourneyID != j.ID {
   762			return apiErr(404, "not_found", "assignment not found in this journey")
   763		}
   764		if a.Status == AsgCompleted || a.Status == AsgCancelled {
   765			return apiErr(409, "completed_work_immutable", "cannot change a completed assignment")
   766		}
   767		worker := s.state.Users[workerID]
   768		if worker == nil {
   769			return apiErr(400, "invalid_worker", "worker not found")
   770		}
   771		if !worker.Active || !worker.HasRole(kindRole(a.Kind)) {
   772			return apiErr(400, "invalid_worker", "worker cannot perform this assignment")
   773		}
   774		eligible := false
   775		for _, u := range s.eligibleWorkers(a, false) {
   776			if u.ID == workerID {
   777				eligible = true
   778			}
   779		}
   780		if !eligible {
   781			return apiErr(409, "ineligible_worker", "worker is not eligible for this assignment")
   782		}
   783		now := time.Now().UTC()
   784		a.Status = AsgOffered
   785		a.OfferedToWorkerID = workerID
   786		a.AcceptedWorkerID = ""
   787		a.OfferedAt = &now
   788		exp := now.Add(offerTimeoutSeconds * time.Second)
   789		a.OfferExpiresAt = &exp
   790		j.PlanVersion++
   791		s.audit(c.user.ID, c.sess.ActiveRole, "assignment.offered", "assignment", a.ID, a.SampleID, true, map[string]interface{}{
   792			"workerId": workerID, "kind": a.Kind, "reassigned": true,
   793		})
   794		return nil
   795	}
