   797	func (s *Service) editAddStop(c *opCtx, j *Journey, changes map[string]interface{}) *ApiError {
   798		locID, _ := changes["locationId"].(string)
   799		if locID == "" {
   800			return apiErr(400, "invalid_json", "changes.locationId is required")
   801		}
   802		loc := s.state.Locations[locID]
   803		if loc == nil || loc.Implicit {
   804			return apiErr(404, "not_found", "location not found")
   805		}
   806		if !loc.Active {
   807			return apiErr(409, "location_inactive", "location is not active")
   808		}
   809		if len(j.SampleIDs) != 1 {
   810			return apiErr(409, "invalid_transition", "add_stop supports single-sample journeys")
   811		}
   812		sample := s.state.Samples[j.SampleIDs[0]]
   813		// rebuild remaining route through the new stop: find route from current
   814		// position to the new stop, then from the new stop onward
   815		posNodeID := s.samplePositionNode(sample)
   816		posLoc := s.state.Locations[posNodeID]
   817		if posLoc == nil || posLoc.Implicit {
   818			return apiErr(409, "no_valid_route", "cannot determine current sample position")
   819		}
   820		sampleType := s.state.SampleTypes[sample.SampleTypeID]
   821		leg1 := s.findRoute([]string{posLoc.ID}, sampleType, true)
   822		_ = leg1
   823		// route position -> new stop -> lab
   824		dist1, _ := s.dijkstra(posLoc.ID, sampleType.RequiresCooledRoute, true, sampleType.RequiresCooledRoute)
   825		if _, ok := dist1[locID]; !ok {
   826			return apiErr(409, "no_valid_route", "no route from the current position to the new stop")
   827		}
   828		dist2, _ := s.dijkstra(locID, sampleType.RequiresCooledRoute, true, sampleType.RequiresCooledRoute)
   829		labOK := false
   830		for _, loc2 := range s.state.Locations {
   831			if !loc2.Implicit && loc2.Active && loc2.HasFunction(LocLaboratory) && s.labAccepts(loc2, sample.SampleTypeID) {
   832				if _, ok := dist2[loc2.ID]; ok {
   833					labOK = true
   834				}
   835			}
   836		}
   837		if !labOK {
   838			return apiErr(409, "no_valid_route", "no route from the new stop to an accepting laboratory")
   839		}
   840		// materialize: cancel unfinished work and rebuild through the stop
   841		s.cancelUnfinishedAssignments(j, "add_stop")
   842		oldStops := j.Stops
   843		j.Stops = nil
   844		j.LegIDs = nil
   845		j.NodeAssignmentIDs = nil
   846		j.LaboratoryAssignmentIDs = nil
   847		// keep completed stops
   848		maxSeq := 0
   849		for _, st := range oldStops {
   850			if st.CompletedAt != nil {
   851				j.Stops = append(j.Stops, st)
   852				if st.Sequence > maxSeq {
   853					maxSeq = st.Sequence
   854				}
   855			}
   856		}
   857		// simple two-segment rebuild: position -> newStop -> best lab
   858		plan1 := s.findRoute([]string{posLoc.ID}, sampleType, true)
   859		if plan1 == nil {
   860			return apiErr(409, "no_valid_route", "no route from current position")
   861		}
   862		// force route through new stop: build segments manually
   863		seg1 := s.buildSegment(j, sample, posLoc.ID, locID, sampleType)
   864		if seg1 == nil {
   865			return apiErr(409, "no_valid_route", "no route from current position to the new stop")
   866		}
   867		labPlan := s.findRoute([]string{locID}, sampleType, true)
   868		if labPlan == nil {
   869			return apiErr(409, "no_valid_route", "no route from the new stop to a laboratory")
   870		}
   871		now := time.Now().UTC()
   872		t := now
   873		seq := maxSeq
   874		fromID := posLoc.ID
   875		for _, connID := range seg1.ConnPath {
   876			conn := s.state.Connections[connID]
   877			next := conn.ToLocationID
   878			if conn.FromLocationID != fromID {
   879				next = conn.FromLocationID
   880			}
   881			t = t.Add(time.Duration(conn.TravelMinutes) * time.Minute)
   882			seq++
   883			isLast := next == locID
   884			stopType := "handoff"
   885			if isLast {
   886				stopType = "handoff"
   887			}
   888			nextLoc := s.state.Locations[next]
   889			j.Stops = append(j.Stops, &Stop{
   890				ID: newUUID(), LocationID: next, StopType: stopType, Sequence: seq,
   891				EstimatedAt: t, DwellMinutes: nextLoc.HandlingMinutes, Coordinate: nextLoc.Coordinate,
   892			})
   893			leg := s.newTransportAssignment(j, sample, len(j.LegIDs)+1, fromID, next, connID)
   894			j.LegIDs = append(j.LegIDs, leg.ID)
   895			conn.Capacity.Reserve(sampleRequiresCooled(s, sample))
   896			nodeAsg := s.newNodeAssignment(j, sample, next)
   897			j.NodeAssignmentIDs = append(j.NodeAssignmentIDs, nodeAsg.ID)
   898			nextLoc.Capacity.Reserve(sampleRequiresCooled(s, sample))
   899			t = t.Add(time.Duration(nextLoc.HandlingMinutes) * time.Minute)
   900			fromID = next
   901		}
   902		for _, connID := range labPlan.ConnPath {
   903			conn := s.state.Connections[connID]
   904			next := conn.ToLocationID
   905			if conn.FromLocationID != fromID {
   906				next = conn.FromLocationID
   907			}
   908			t = t.Add(time.Duration(conn.TravelMinutes) * time.Minute)
   909			seq++
   910			nextLoc := s.state.Locations[next]
   911			isLab := next == labPlan.LabID
   912			stopType := "handoff"
   913			dwell := nextLoc.HandlingMinutes
   914			if isLab {
   915				stopType = "delivery"
   916				dwell = 0
   917			}
   918			j.Stops = append(j.Stops, &Stop{
   919				ID: newUUID(), LocationID: next, StopType: stopType, Sequence: seq,
   920				EstimatedAt: t, DwellMinutes: dwell, Coordinate: nextLoc.Coordinate,
   921			})
   922			leg := s.newTransportAssignment(j, sample, len(j.LegIDs)+1, fromID, next, connID)
   923			j.LegIDs = append(j.LegIDs, leg.ID)
   924			conn.Capacity.Reserve(sampleRequiresCooled(s, sample))
   925			if !isLab {
   926				nodeAsg := s.newNodeAssignment(j, sample, next)
   927				j.NodeAssignmentIDs = append(j.NodeAssignmentIDs, nodeAsg.ID)
   928				nextLoc.Capacity.Reserve(sampleRequiresCooled(s, sample))
   929				t = t.Add(time.Duration(nextLoc.HandlingMinutes) * time.Minute)
   930			}
   931			fromID = next
   932		}
   933		if labPlan.EntryID == labPlan.LabID && fromID == labPlan.LabID {
   934			seq++
   935			labLoc := s.state.Locations[labPlan.LabID]
   936			j.Stops = append(j.Stops, &Stop{
   937				ID: newUUID(), LocationID: labPlan.LabID, StopType: "delivery", Sequence: seq,
   938				EstimatedAt: t, DwellMinutes: 0, Coordinate: labLoc.Coordinate,
   939			})
   940		}
   941		labAsg := s.newLaboratoryAssignment(j, sample, labPlan.LabID)
   942		j.LaboratoryAssignmentIDs = append(j.LaboratoryAssignmentIDs, labAsg.ID)
   943		lab := s.state.Locations[labPlan.LabID]
   944		lab.Capacity.Reserve(sampleRequiresCooled(s, sample))
   945		if t.After(sample.DeliveryDeadline) {
   946			return apiErr(409, "deadline_exceeded", "the new route cannot meet the sample deadline")
   947		}
   948		j.EstimatedDeliveryAt = t
   949		sample.TargetLaboratoryID = labPlan.LabID
   950		j.PlanVersion++
   951		for _, id := range j.LegIDs {
   952			s.offerAssignment(s.state.Assignments[id])
   953		}
   954		for _, id := range j.NodeAssignmentIDs {
   955			s.offerAssignment(s.state.Assignments[id])
   956		}
   957		for _, id := range j.LaboratoryAssignmentIDs {
   958			s.offerAssignment(s.state.Assignments[id])
   959		}
   960		return nil
   961	}
