   237	// dijkstra computes shortest travel times from entry over active connections.
   238	func (s *Service) dijkstra(entryID string, cooledOnly, checkCapacity bool, cooled bool) (map[string]int, map[string]string) {
   239		dist := map[string]int{entryID: 0}
   240		prev := map[string]string{} // node -> connection id used to reach it
   241		visited := map[string]bool{}
   242		for {
   243			var cur string
   244			best := -1
   245			for n, d := range dist {
   246				if !visited[n] && (best < 0 || d < best) {
   247					cur, best = n, d
   248				}
   249			}
   250			if cur == "" {
   251				break
   252			}
   253			visited[cur] = true
   254			for _, conn := range s.state.Connections {
   255				if !conn.Active {
   256					continue
   257				}
   258				var next string
   259				if conn.FromLocationID == cur {
   260					next = conn.ToLocationID
   261				} else if conn.ToLocationID == cur {
   262					next = conn.FromLocationID
   263				} else {
   264					continue
   265				}
   266				loc := s.state.Locations[next]
   267				if loc == nil || !loc.Active || loc.Implicit {
   268					continue
   269				}
   270				if cooledOnly && !conn.Cooled {
   271					continue
   272				}
   273				if checkCapacity && conn.Capacity.Available(cooled) < 1 {
   274					continue
   275				}
   276				nd := best + conn.TravelMinutes
   277				if d, ok := dist[next]; !ok || nd < d {
   278					dist[next] = nd
   279					prev[next] = conn.ID
   280				}
   281			}
   282		}
   283		return dist, prev
   284	}
