			}
			if cur != entryID {
				continue
			}
			handling := 0
			okPath := true
			for i, n := range nodes {
				if i == 0 || i == len(nodes)-1 {
					continue
				}
				nl := s.state.Locations[n]
				handling += nl.HandlingMinutes
