)

type ApiError struct {
	Status  int
	Code    string
	Message string
}

func (e *ApiError) Error() string { return e.Message }

func apiErr(status int, code, msg string) *ApiError {
	return &ApiError{Status: status, Code: code, Message: msg}
}

type opCtx struct {
	svc  *Service
	r    *http.Request
	user *User
	sess *Session
	body J
	raw  []byte
}

type opHandler func(c *opCtx) (int, interface{}, *ApiError)

func writeJSON(w http.ResponseWriter, status int, v interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	enc := json.NewEncoder(w)
	_ = enc.Encode(v)
}

func writeErr(w http.ResponseWriter, e *ApiError) {
	writeJSON(w, e.Status, J{
		"error": J{"code": e.Code, "message": e.Message},
	})
}

func decodeBody(r *http.Request) (J, []byte, *ApiError) {
	raw, err := io.ReadAll(io.LimitReader(r.Body, 1<<20))
	if err != nil || len(raw) == 0 {
		return nil, nil, apiErr(400, "invalid_json", "request body must be a JSON object")
	}
	var body J
	if err := json.Unmarshal(raw, &body); err != nil {
		return nil, nil, apiErr(400, "invalid_json", "request body is not valid JSON")
	}
	if body == nil {
		return nil, nil, apiErr(400, "invalid_json", "request body must be a JSON object")
	}
	return body, raw, nil
}

func checkFields(body J, allowed ...string) *ApiError {
	set := map[string]bool{}
	for _, a := range allowed {
		set[a] = true
	}
	for k := range body {
		if !set[k] {
			return apiErr(400, "invalid_json", fmt.Sprintf("unknown field %q", k))
		}
	}
	return nil
}

func reqStr(body J, key string) (string, *ApiError) {
	v, ok := body[key]
	if !ok || v == nil {
		return "", apiErr(400, "invalid_json", fmt.Sprintf("missing required field %q", key))
	}
	s, ok := v.(string)
	if !ok || s == "" {
		return "", apiErr(400, "invalid_json", fmt.Sprintf("field %q must be a non-empty string", key))
	}
	return s, nil
}

func optStr(body J, key string) (string, *ApiError) {
	v, ok := body[key]
	if !ok || v == nil {
		return "", nil
	}
	s, ok := v.(string)
	if !ok {
		return "", apiErr(400, "invalid_json", fmt.Sprintf("field %q must be a string", key))
	}
	return s, nil
}

func reqBool(body J, key string) (bool, *ApiError) {
	v, ok := body[key]
	if !ok || v == nil {
		return false, apiErr(400, "invalid_json", fmt.Sprintf("missing required field %q", key))
	}
	b, ok := v.(bool)
	if !ok {
		return false, apiErr(400, "invalid_json", fmt.Sprintf("field %q must be a boolean", key))
	}
	return b, nil
}

func optBool(body J, key string, def bool) (bool, *ApiError) {
	v, ok := body[key]
	if !ok || v == nil {
		return def, nil
	}
	b, ok := v.(bool)
	if !ok {
		return false, apiErr(400, "invalid_json", fmt.Sprintf("field %q must be a boolean", key))
	}
	return b, nil
}

func reqNum(body J, key string) (float64, *ApiError) {
	v, ok := body[key]
	if !ok || v == nil {
		return 0, apiErr(400, "invalid_json", fmt.Sprintf("missing required field %q", key))
	}
	n, ok := v.(float64)
	if !ok {
		return 0, apiErr(400, "invalid_json", fmt.Sprintf("field %q must be a number", key))
	}
	return n, nil
}

func optNum(body J, key string, def float64) (float64, *ApiError) {
	v, ok := body[key]
	if !ok || v == nil {
		return def, nil
	}
	n, ok := v.(float64)
	if !ok {
		return 0, apiErr(400, "invalid_json", fmt.Sprintf("field %q must be a number", key))
	}
	return n, nil
}

func reqInt(body J, key string) (int, *ApiError) {
	n, err := reqNum(body, key)
	if err != nil {
		return 0, err
	}
	if n != float64(int(n)) {
		return 0, apiErr(400, "invalid_json", fmt.Sprintf("field %q must be an integer", key))
	}
	return int(n), nil
}

func optStrList(body J, key string) ([]string, *ApiError) {
	v, ok := body[key]
	if !ok || v == nil {
		return nil, nil
	}
	arr, ok := v.([]interface{})
	if !ok {
		return nil, apiErr(400, "invalid_json", fmt.Sprintf("field %q must be an array of strings", key))
	}
	out := []string{}
	for _, item := range arr {
		s, ok := item.(string)
		if !ok {
			return nil, apiErr(400, "invalid_json", fmt.Sprintf("field %q must be an array of strings", key))
		}
		out = append(out, s)
	}
	return out, nil
}

func reqCoord(body J, key string, errCode string) (Coordinate, *ApiError) {
	v, ok := body[key]
	if !ok || v == nil {
		return Coordinate{}, apiErr(400, "invalid_json", fmt.Sprintf("missing required field %q", key))
	}
	m, ok := v.(map[string]interface{})
	if !ok {
		return Coordinate{}, apiErr(400, errCode, fmt.Sprintf("field %q must be a coordinate object", key))
	}
	lat, ok1 := m["latitude"].(float64)
	lng, ok2 := m["longitude"].(float64)
	if !ok1 || !ok2 {
		return Coordinate{}, apiErr(400, errCode, "coordinate requires numeric latitude and longitude")
	}
	c := Coordinate{Latitude: lat, Longitude: lng}
	if !validCoordinate(c) {
		return Coordinate{}, apiErr(400, errCode, "coordinate out of range")
	}
	return c, nil
