func (s *Service) authenticate(r *http.Request) (*User, *Session, *ApiError) {
	h := r.Header.Get("Authorization")
	if h == "" || !strings.HasPrefix(h, "Bearer ") {
		return nil, nil, apiErr(401, "unauthorized", "missing bearer [REDACTED]")
	}
	token := strings.TrimSpace(strings.TrimPrefix(h, "Bearer "))
	sess := s.state.Sessions[token]
	if sess == nil {
		return nil, nil, apiErr(401, "unauthorized", "invalid or expired token")
	}
	user := s.state.Users[sess.UserID]
	if user == nil || !user.Active {
		return nil, nil, apiErr(401, "unauthorized", "user is not active")
