package main

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"
	"time"
)

type ApiError struct {
	Status  int
	Code    string
	Message string
}

func (e *ApiError) Error() string { return e.Message }

func apiErr(status int, code, msg string) *ApiError {
	return &ApiError{Status: status, Code: code, Message: msg}
}

type opCtx struct {
	svc  *Service
	r    *http.Request
	user *User
	sess *Session
	body J
	raw  []byte
}

type opHandler func(c *opCtx) (int, interface{}, *ApiError)

func writeJSON(w http.ResponseWriter, status int, v interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	enc := json.NewEncoder(w)
	_ = enc.Encode(v)
}

func writeErr(w http.ResponseWriter, e *ApiError) {
	writeJSON(w, e.Status, J{"error": e.Message, "code": e.Code})
}

func decodeBody(r *http.Request) (J, []byte, *ApiError) {
	raw, err := io.ReadAll(io.LimitReader(r.Body, 1<<20))
	if err != nil || len(raw) == 0 {
		return nil, nil, apiErr(400, "invalid_json", "request body must be a JSON object")
	}
	var body J
	if err := json.Unmarshal(raw, &body); err != nil {
		return nil, nil, apiErr(400, "invalid_json", "request body is not valid JSON")
	}
	if body == nil {
		return nil, nil, apiErr(400, "invalid_json", "request body must be a JSON object")
	}
	return body, raw, nil
}

func checkFields(body J, allowed ...string) *ApiError {
	set := map[string]bool{}
	for _, a := range allowed {
		set[a] = true
	}
	for k := range body {
		if !set[k] {
			return apiErr(400, "invalid_json", fmt.Sprintf("unknown field %q", k))
		}
	}
	return nil
}

func reqStr(body J, key string) (string, *ApiError) {
	v, ok := body[key]
	if !ok || v == nil {
		return "", apiErr(400, "invalid_json", fmt.Sprintf("missing required field %q", key))
	}
