package main

import (
	"encoding/json"
	"time"
)

type J = map[string]interface{}

func coordView(c Coordinate) J {
	return J{"latitude": c.Latitude, "longitude": c.Longitude}
}

func coordViewPtr(c *Coordinate) interface{} {
	if c == nil {
		return nil
	}
	return coordView(*c)
}

func functionsView(l *Location) J {
	f := J{
		LocCollectionPoint: false,
		LocTransferPoint:   false,
		LocHub:             false,
		LocLaboratory:      false,
	}
	for k, v := range l.Functions {
		if v {
			f[k] = true
		}
	}
	return f
}

func capacityView(c CapacityPool) J {
	return J{
		"capacityUnits":       c.CapacityUnits,
		"reservedUnits":       c.ReservedUnits,
		"availableUnits":      c.CapacityUnits - c.ReservedUnits,
		"cooledCapacityUnits": c.CooledCapacityUnits,
		"cooledReservedUnits": c.CooledReservedUnits,
		"cooledAvailableUnits": c.CooledCapacityUnits - c.CooledReservedUnits,
	}
}

func locationView(l *Location) J {
	return J{
		"locationId":      l.ID,
		"name":            l.Name,
		"coordinate":      coordView(l.Coordinate),
		"coverageKm":      l.CoverageKm,
		"handlingMinutes": l.HandlingMinutes,
		"active":          l.Active,
		"functions":       functionsView(l),
	}
}

func operationsLocationView(l *Location) J {
	v := locationView(l)
	v["id"] = l.ID
	v["capacity"] = capacityView(l.Capacity)
	accepted := l.AcceptedSampleTypeIDs
	if accepted == nil {
		accepted = []string{}
	}
	v["acceptedSampleTypeIds"] = accepted
	return v
}

// connectionView is the OperationsConnection shape used in operations state.
func connectionView(c *Connection) J {
	return J{
		"id":             c.ID,
		"connectionId":   c.ID,
		"fromLocationId": c.FromLocationID,
		"toLocationId":   c.ToLocationID,
		"travelMinutes":  c.TravelMinutes,
		"costUnits":      c.CostUnits,
		"cooled":         c.Cooled,
		"active":         c.Active,
		"capacity":       capacityView(c.Capacity),
	}
}

// connectionSummaryView is the create_connection response shape.
func connectionSummaryView(c *Connection) J {
	return J{
		"connectionId":   c.ID,
		"fromLocationId": c.FromLocationID,
		"toLocationId":   c.ToLocationID,
		"travelMinutes":  c.TravelMinutes,
		"costUnits":      c.CostUnits,
		"cooled":         c.Cooled,
		"active":         c.Active,
	}
}

func sampleTypeView(t *SampleType) J {
	incompat := t.IncompatibleSampleTypes
	if incompat == nil {
		incompat = []string{}
	}
	return J{
		"sampleTypeId":               t.ID,
		"name":                       t.Name,
		"qualifiedCollectorRequired": t.QualifiedCollectorRequired,
		"requiredQualification":      t.RequiredQualification,
		"containerType":              t.ContainerType,
		"temperatureMinC":            t.TemperatureMinC,
		"temperatureMaxC":            t.TemperatureMaxC,
		"incompatibleSampleTypes":    incompat,
		"requiresCooledRoute":        t.RequiresCooledRoute,
		"batchingAllowed":            t.BatchingAllowed,
	}
}

func userView(u *User) J {
	roles := u.Roles
	if roles == nil {
		roles = []string{}
	}
	quals := u.Qualifications
	if quals == nil {
		quals = []string{}
	}
	certs := []J{}
	for _, c := range u.Certifications {
		certs = append(certs, J{"code": c.Code, "active": c.Active, "expiresAt": fmtTimePtr(c.ExpiresAt)})
	}
	return J{
		"userId":         u.ID,
		"username":       u.Username,
		"email":          u.Email,
		"fullName":       u.FullName,
		"phone":          u.Phone,
		"roles":          roles,
		"qualifications": quals,
		"certifications": certs,
		"active":         u.Active,
	}
}

func auditView(a *AuditRow) J {
	var details interface{}
	if len(a.Details) > 0 {
		_ = json.Unmarshal(a.Details, &details)
	}
	if details == nil {
		details = J{}
	}
	return J{
		"auditId": a.AuditID, "audit_id": a.AuditID,
		"actorId": a.ActorID, "actor_id": a.ActorID,
		"role": a.Role, "actorRole": a.Role,
		"action": a.Action,
		"entityType": a.EntityType, "entity_type": a.EntityType,
		"entityId": a.EntityID, "entity_id": a.EntityID,
		"success": a.Success,
		"occurredAt": fmtTime(a.OccurredAt), "occurred_at": fmtTime(a.OccurredAt),
		"details": details,
	}
}

func timelineView(rows []*AuditRow) []J {
	out := []J{}
	for _, a := range rows {
		var details interface{}
		if len(a.Details) > 0 {
			_ = json.Unmarshal(a.Details, &details)
		}
		if details == nil {
			details = J{}
		}
		out = append(out, J{
			"eventId": a.Seq, "action": a.Action, "actorId": a.ActorID,
			"role": a.Role, "entityType": a.EntityType, "entityId": a.EntityID,
			"success": a.Success, "occurredAt": fmtTime(a.OccurredAt), "details": details,
		})
	}
	return out
}

func stopView(st *Stop) J {
	return J{
		"stopId": st.ID, "locationId": st.LocationID, "location_id": st.LocationID,
		"stopType": st.StopType, "stop_type": st.StopType,
		"sequence": st.Sequence, "estimatedAt": fmtTime(st.EstimatedAt), "estimated_at": fmtTime(st.EstimatedAt),
		"dwellMinutes": st.DwellMinutes, "coordinate": coordView(st.Coordinate),
		"completedAt": fmtTimePtr(st.CompletedAt),
	}
}

func (s *Service) legView(legID string) J {
	a := s.state.Assignments[legID]
	if a == nil {
		return J{"assignmentId": legID, "assignment_id": legID, "sequence": 0, "status": "unknown"}
	}
	v := J{
		"assignmentId": a.ID, "assignment_id": a.ID,
		"sequence": a.Sequence, "status": a.Status,
		"sampleId": a.SampleID,
	}
	if a.FromLocationID != "" {
		v["fromLocationId"] = a.FromLocationID
		v["from_location_id"] = a.FromLocationID
	}
	if a.ToLocationID != "" {
		v["toLocationId"] = a.ToLocationID
		v["to_location_id"] = a.ToLocationID
	}
	worker := a.AcceptedWorkerID
	if worker == "" {
		worker = a.OfferedToWorkerID
	}
	if worker != "" {
		v["workerId"] = worker
		v["worker_id"] = worker
	}
	return v
}

func (s *Service) journeyAssignedWorkers(j *Journey) []string {
	seen := map[string]bool{}
	out := []string{}
	add := func(id string) {
		if a := s.state.Assignments[id]; a != nil {
			w := a.AcceptedWorkerID
			if w == "" {
				w = a.OfferedToWorkerID
			}
			if w != "" && !seen[w] {
				seen[w] = true
				out = append(out, w)
			}
		}
	}
	for _, id := range j.CollectionAssignmentIDs {
		add(id)
	}
	for _, id := range j.LegIDs {
		add(id)
	}
	for _, id := range j.NodeAssignmentIDs {
		add(id)
	}
	for _, id := range j.LaboratoryAssignmentIDs {
		add(id)
	}
	return out
}

func (s *Service) journeyValid(j *Journey) bool {
	if j.Status == JourneyCancelled {
		return false
	}
	for _, id := range j.LegIDs {
		a := s.state.Assignments[id]
		if a == nil || a.Status == AsgCancelled {
			return false
		}
	}
	return true
}

func (s *Service) journeyCapacity(j *Journey) (used int, available int) {
	used = 0
	available = -1
	consider := func(c CapacityPool) {
		used++
		av := c.CapacityUnits - c.ReservedUnits
		if available < 0 || av < available {
			available = av
		}
	}
	for _, id := range j.LegIDs {
		a := s.state.Assignments[id]
		if a != nil && a.ConnectionID != "" && a.Status != AsgCancelled {
			if conn := s.state.Connections[a.ConnectionID]; conn != nil {
				consider(conn.Capacity)
			}
		}
	}
	for _, id := range j.NodeAssignmentIDs {
		a := s.state.Assignments[id]
		if a != nil && a.Status != AsgCancelled {
			if loc := s.state.Locations[a.NodeID]; loc != nil {
				consider(loc.Capacity)
			}
		}
	}
	for _, id := range j.LaboratoryAssignmentIDs {
		a := s.state.Assignments[id]
		if a != nil && a.Status != AsgCancelled {
			if loc := s.state.Locations[a.LaboratoryID]; loc != nil {
				consider(loc.Capacity)
			}
		}
	}
	if available < 0 {
		available = 0
	}
	return used, available
}

func (s *Service) journeyPlanView(j *Journey, depth int) J {
	stops := []J{}
	for _, st := range j.Stops {
		stops = append(stops, stopView(st))
	}
	legs := []J{}
	for _, id := range j.LegIDs {
		legs = append(legs, s.legView(id))
	}
	used, avail := s.journeyCapacity(j)
	sampleIDs := j.SampleIDs
	if sampleIDs == nil {
		sampleIDs = []string{}
	}
	collIDs := j.CollectionAssignmentIDs
	if collIDs == nil {
		collIDs = []string{}
	}
	nodeIDs := j.NodeAssignmentIDs
	if nodeIDs == nil {
		nodeIDs = []string{}
	}
	labIDs := j.LaboratoryAssignmentIDs
	if labIDs == nil {
		labIDs = []string{}
	}
	v := J{
		"journeyId":                 j.ID,
		"planVersion":               j.PlanVersion,
		"routeMode":                 j.RouteMode,
		"status":                    j.Status,
		"estimatedDeliveryAt":       fmtTime(j.EstimatedDeliveryAt),
		"totalCostUnits":            j.TotalCostUnits,
		"capacityUsed":              used,
		"capacityAvailable":         avail,
		"sampleIds":                 sampleIDs,
		"orderedStops":              stops,
		"legs":                      legs,
		"assignedWorkerIds":         s.journeyAssignedWorkers(j),
		"collectionAssignmentIds":   collIDs,
		"nodeAssignmentIds":         nodeIDs,
		"laboratoryAssignmentIds":   labIDs,
		"valid":                     s.journeyValid(j),
	}
	if j.ReplanStatus != "" {
		v["replanStatus"] = j.ReplanStatus
	}
	if len(collIDs) > 0 {
		v["collectionAssignmentId"] = collIDs[0]
	}
	if n := len(j.LegIDs); n > 0 {
		v["firstTransportAssignmentId"] = j.LegIDs[0]
		v["finalTransportAssignmentId"] = j.LegIDs[n-1]
		if n > 2 {
			v["middleTransportAssignmentId"] = j.LegIDs[1]
		}
	}
	if j.ParentJourneyID != "" {
		v["parentJourneyId"] = j.ParentJourneyID
	}
	return v
}

func (s *Service) workerJourneyPlanView(j *Journey, workerID string) J {
	legs := []J{}
	assignmentIDs := []string{}
	mine := func(id string) {
		a := s.state.Assignments[id]
		if a == nil {
			return
		}
		if a.AcceptedWorkerID == workerID || a.OfferedToWorkerID == workerID {
			assignmentIDs = append(assignmentIDs, id)
			if a.Kind == KindTransport {
				legs = append(legs, s.legView(id))
			}
		}
	}
	for _, id := range j.LegIDs {
		mine(id)
	}
	collIDs := []string{}
	for _, id := range j.CollectionAssignmentIDs {
		a := s.state.Assignments[id]
		if a != nil && (a.AcceptedWorkerID == workerID || a.OfferedToWorkerID == workerID) {
			collIDs = append(collIDs, id)
			assignmentIDs = append(assignmentIDs, id)
		}
	}
	nodeIDs := []string{}
	for _, id := range j.NodeAssignmentIDs {
		a := s.state.Assignments[id]
		if a != nil && (a.AcceptedWorkerID == workerID || a.OfferedToWorkerID == workerID) {
			nodeIDs = append(nodeIDs, id)
			assignmentIDs = append(assignmentIDs, id)
		}
	}
	labIDs := []string{}
	for _, id := range j.LaboratoryAssignmentIDs {
		a := s.state.Assignments[id]
		if a != nil && (a.AcceptedWorkerID == workerID || a.OfferedToWorkerID == workerID) {
			labIDs = append(labIDs, id)
			assignmentIDs = append(assignmentIDs, id)
		}
	}
	// stops scoped to worker's legs
	stopIDs := map[string]bool{}
	for _, id := range assignmentIDs {
		a := s.state.Assignments[id]
		if a == nil {
			continue
		}
		stopIDs[a.FromLocationID] = true
		stopIDs[a.ToLocationID] = true
		stopIDs[a.NodeID] = true
		stopIDs[a.LaboratoryID] = true
	}
	stops := []J{}
	for _, st := range j.Stops {
		if stopIDs[st.LocationID] {
			stops = append(stops, stopView(st))
		}
	}
	v := J{
		"journeyId":               j.ID,
		"planVersion":             j.PlanVersion,
		"routeMode":               j.RouteMode,
		"status":                  j.Status,
		"estimatedDeliveryAt":     fmtTime(j.EstimatedDeliveryAt),
		"scope":                   "assigned_legs",
		"assignmentIds":           assignmentIDs,
		"sampleIds":               j.SampleIDs,
		"legs":                    legs,
		"orderedStops":            stops,
		"collectionAssignmentIds": collIDs,
		"nodeAssignmentIds":       nodeIDs,
		"laboratoryAssignmentIds": labIDs,
		"assignedWorkerIds":       []string{workerID},
	}
	if v["sampleIds"] == nil {
		v["sampleIds"] = []string{}
	}
	if j.ParentJourneyID != "" {
		v["parentJourneyId"] = j.ParentJourneyID
	}
	return v
}

func (s *Service) requesterJourneyPlanView(j *Journey) J {
	stops := []J{}
	for _, st := range j.Stops {
		stops = append(stops, stopView(st))
	}
	legs := []J{}
	for _, id := range j.LegIDs {
		legs = append(legs, s.legView(id))
	}
	sampleIDs := j.SampleIDs
	if sampleIDs == nil {
		sampleIDs = []string{}
	}
	v := J{
		"journeyId":           j.ID,
		"planVersion":         j.PlanVersion,
		"routeMode":           j.RouteMode,
		"status":              j.Status,
		"estimatedDeliveryAt": fmtTime(j.EstimatedDeliveryAt),
		"totalCostUnits":      j.TotalCostUnits,
		"sampleIds":           sampleIDs,
		"orderedStops":        stops,
		"legs":                legs,
	}
	if j.ParentJourneyID != "" {
		v["parentJourneyId"] = j.ParentJourneyID
	}
	return v
}

func (s *Service) locationStale(recordedAt *time.Time) bool {
	if recordedAt == nil {
		return true
	}
	return time.Since(*recordedAt) > staleLocationSeconds*time.Second
}

func (s *Service) sampleTimeline(sampleID string) []J {
	rows, err := s.store.TimelineForSample(sampleID, 500)
	if err != nil {
		return []J{}
	}
	return timelineView(rows)
}

func (s *Service) sampleStateView(sample *Sample) J {
	labID := sample.TargetLaboratoryID
	if sample.ReceivedLaboratoryID != "" {
		labID = sample.ReceivedLaboratoryID
	}
	return J{
		"sampleId": sample.ID, "requestId": sample.RequestID, "requesterId": sample.RequesterID,
		"status": sample.Status, "serviceability": sample.Serviceability,
		"requestedAt": fmtTime(sample.RequestedAt), "deliveryDeadline": fmtTime(sample.DeliveryDeadline),
		"earliestCollectionAt": fmtTime(sample.EarliestCollectionAt),
		"latestCollectionAt": fmtTime(sample.LatestCollectionAt),
		"sampleTypeId": sample.SampleTypeID,
		"currentHolderId": strOrNil(sample.CurrentHolderID),
		"journeyId": strOrNil(sample.ActiveJourneyID),
		"laboratoryId": strOrNil(labID),
		"latestLocation": coordViewPtr(sample.LatestLocation),
		"locationRecordedAt": fmtTimePtr(sample.LocationRecordedAt),
		"locationStale": s.locationStale(sample.LocationRecordedAt),
		"timeline": s.sampleTimeline(sample.ID),
	}
}

func strOrNil(s string) interface{} {
	if s == "" {
		return nil
	}
	return s
}

func (s *Service) handoffView(h *Handoff) J {
	return J{
		"handoffId": h.ID, "sampleId": h.SampleID,
		"fromAssignmentId": h.FromAssignmentID, "toAssignmentId": h.ToAssignmentID,
		"senderId": h.SenderID, "receiverId": h.ReceiverID,
		"status": h.Status, "senderConfirmed": h.SenderConfirmed, "receiverConfirmed": h.ReceiverConfirmed,
		"initiatedAt": fmtTime(h.InitiatedAt), "confirmedAt": fmtTimePtr(h.ConfirmedAt),
	}
}

func (s *Service) sampleLifecycleView(sample *Sample) J {
	completed := sample.CompletedLegIDs
	if completed == nil {
		completed = []string{}
	}
	repl := sample.ActiveReplacementPlanIDs
	if repl == nil {
		repl = []string{}
	}
	v := J{
		"sampleId": sample.ID, "status": sample.Status, "sealed": sample.Sealed,
		"completedLegIds": completed, "activeReplacementPlanIds": repl,
		"timeline": s.sampleTimeline(sample.ID),
		"activeJourneyId": strOrNil(sample.ActiveJourneyID),
		"currentHolderId": strOrNil(sample.CurrentHolderID),
		"receivedLaboratoryId": strOrNil(sample.ReceivedLaboratoryID),
		"latestLocation": coordViewPtr(sample.LatestLocation),
		"locationRecordedAt": fmtTimePtr(sample.LocationRecordedAt),
		"locationStale": s.locationStale(sample.LocationRecordedAt),
	}
	if sample.Exception != nil {
		v["exception"] = J{
			"code": sample.Exception.Code, "reason": sample.Exception.Reason,
			"occurredAt": fmtTime(sample.Exception.OccurredAt), "details": sample.Exception.Details,
		}
	} else {
		v["exception"] = nil
	}
	if sample.PendingHandoffID != "" {
		v["pendingHandoffId"] = sample.PendingHandoffID
		if h := s.state.Handoffs[sample.PendingHandoffID]; h != nil {
			v["pendingHandoff"] = s.handoffView(h)
		}
	} else {
		v["pendingHandoffId"] = nil
		v["pendingHandoff"] = nil
	}
	return v
}

func (s *Service) historyFor(entityID, sampleID string) []J {
	rows, err := s.store.HistoryForEntity(entityID, sampleID, 200)
	if err != nil {
		return []J{}
	}
	return timelineView(rows)
}

func (s *Service) sampleWorkItemView(sample *Sample) J {
	journeyID := sample.ActiveJourneyID
	labID := sample.TargetLaboratoryID
	if sample.ReceivedLaboratoryID != "" {
		labID = sample.ReceivedLaboratoryID
	}
	return J{
		"kind": "sample", "sampleId": sample.ID, "sample_id": sample.ID,
		"requestId": sample.RequestID, "status": sample.Status,
		"serviceability": sample.Serviceability,
		"requestedAt": fmtTime(sample.RequestedAt), "deliveryDeadline": fmtTime(sample.DeliveryDeadline),
		"earliestCollectionAt": fmtTime(sample.EarliestCollectionAt),
		"latestCollectionAt": fmtTime(sample.LatestCollectionAt),
		"journeyId": strOrNil(journeyID),
		"laboratoryId": strOrNil(labID), "currentHolderId": strOrNil(sample.CurrentHolderID),
		"history": s.historyFor(sample.ID, sample.ID),
		"locationRecordedAt": fmtTimePtr(sample.LocationRecordedAt),
		"locationStale": s.locationStale(sample.LocationRecordedAt),
	}
}

func (s *Service) journeyWorkItemView(j *Journey) J {
	sampleIDs := j.SampleIDs
	if sampleIDs == nil {
		sampleIDs = []string{}
	}
	count := 0
	for _, id := range j.LegIDs {
		if a := s.state.Assignments[id]; a != nil && a.Status != AsgCancelled {
			count++
		}
	}
	var sampleID string
	if len(j.SampleIDs) > 0 {
		sampleID = j.SampleIDs[0]
	}
	return J{
		"kind": "journey", "journeyId": j.ID, "journey_id": j.ID,
		"status": j.Status, "routeMode": j.RouteMode, "planVersion": j.PlanVersion,
		"sampleIds": sampleIDs,
		"assignmentCount": count,
		"history": s.historyFor(j.ID, sampleID),
	}
}

func (s *Service) assignmentWorkItemView(a *Assignment) J {
	v := J{
		"kind": "assignment", "assignmentId": a.ID, "assignment_id": a.ID,
		"sampleId": a.SampleID, "sample_id": a.SampleID,
		"status": a.Status, "journeyId": a.JourneyID,
		"history": s.historyFor(a.ID, a.SampleID),
	}
	if a.FromLocationID != "" {
		v["fromLocationId"] = a.FromLocationID
	}
	if a.ToLocationID != "" {
		v["toLocationId"] = a.ToLocationID
	}
	if a.OfferExpiresAt != nil && a.Status == AsgOffered {
		v["offerExpiresAt"] = fmtTime(*a.OfferExpiresAt)
	}
	if a.Kind == KindNode {
		v["nodeId"] = a.NodeID
		v["incomingFromLocationId"] = a.FromLocationID
		v["outgoingToLocationId"] = a.ToLocationID
		if loc := s.state.Locations[a.NodeID]; loc != nil {
			v["destinationCapacity"] = capacityView(loc.Capacity)
		}
	}
	if a.Kind == KindLaboratory {
		v["laboratoryId"] = a.LaboratoryID
		v["expectedSampleTypeId"] = a.ExpectedSampleTypeID
		if loc := s.state.Locations[a.LaboratoryID]; loc != nil {
			v["destinationCapacity"] = capacityView(loc.Capacity)
		}
	}
	if a.Kind == KindTransport {
		if loc := s.state.Locations[a.ToLocationID]; loc != nil {
			v["destinationCapacity"] = capacityView(loc.Capacity)
		}
	}
	return v
}

