func (s *Service) hCreateUser(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleAdministrator); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "username", "password", "email", "fullName", "phone", "roles", "qualifications", "certifications", "assignedLocationId", "idempotencyKey"); err != nil {
		return 0, nil, err
	}
	return s.runIdempotent(c, "create_user", true, func() (int, interface{}, *ApiError) {
		username, err := reqStr(c.body, "username")
		if err != nil {
			return 0, nil, err
		}
		password, err := reqStr(c.body, "password")
		if err != nil {
			return 0, nil, err
		}
		email, err := reqStr(c.body, "email")
		if err != nil {
			return 0, nil, err
		}
		fullName, err := reqStr(c.body, "fullName")
		if err != nil {
			return 0, nil, err
		}
		phone, err := reqStr(c.body, "phone")
		if err != nil {
			return 0, nil, err
		}
		roles, err := optStrList(c.body, "roles")
		if err != nil {
			return 0, nil, err
		}
		if len(roles) == 0 {
			return 0, nil, apiErr(400, "invalid_json", "roles must be a non-empty array")
		}
		for _, r := range roles {
			if !validRole(r) {
				return 0, nil, apiErr(400, "invalid_role", "unknown role "+r)
			}
		}
		quals, err := optStrList(c.body, "qualifications")
		if err != nil {
			return 0, nil, err
		}
		certs := []Certification{}
		if v, ok := c.body["certifications"]; ok && v != nil {
			arr, ok := v.([]interface{})
			if !ok {
				return 0, nil, apiErr(400, "invalid_json", "certifications must be an array")
			}
			for _, item := range arr {
				m, ok := item.(map[string]interface{})
				if !ok {
					return 0, nil, apiErr(400, "invalid_json", "certifications must contain objects")
				}
				code, _ := m["code"].(string)
				if code == "" {
					return 0, nil, apiErr(400, "invalid_json", "certification code is required")
				}
				active, _ := m["active"].(bool)
				var exp *time.Time
				if es, ok := m["expiresAt"].(string); ok && es != "" {
					t, perr := parseTime(es)
					if perr != nil {
						return 0, nil, apiErr(400, "invalid_time", "invalid certification expiresAt")
					}
					exp = &t
				}
				certs = append(certs, Certification{Code: code, Active: active, ExpiresAt: exp})
			}
		}
		assignedLoc, err := optStr(c.body, "assignedLocationId")
		if err != nil {
			return 0, nil, err
		}
		for _, u := range s.state.Users {
			if u.Username == username {
				return 0, nil, apiErr(409, "username_conflict", "username already exists")
			}
		}
		if assignedLoc != "" {
			loc := s.state.Locations[assignedLoc]
			if loc == nil || loc.Implicit {
				return 0, nil, apiErr(404, "not_found", "assigned location not found")
			}
		}
		needsLocation := false
		for _, r := range roles {
			if r == RoleNodeHandler || r == RoleLaboratoryTeam {
				needsLocation = true
			}
		}
		if needsLocation && assignedLoc == "" {
			return 0, nil, apiErr(400, "invalid_json", "assignedLocationId is required for node_handler and laboratory_team roles")
		}
		u := &User{
			ID: newUUID(), Username: username, Email: email, FullName: fullName, Phone: phone,
			Roles: roles, Qualifications: quals, Certifications: certs, Active: true,
			AssignedLocationID: assignedLoc, Available: true, CapacityUnits: 10,
			CreatedAt: time.Now().UTC(),
		}
		u.PasswordHash = hashPassword(password, u.ID[:8])
		s.state.Users[u.ID] = u
		c.audit("create_user", "user", u.ID, "", true, map[string]interface{}{"username": username, "roles": roles})
		s.emit("user.created", "user", u.ID, userView(u))
		return 201, userView(u), nil
	})
}

