		}
		if v, ok := c.body["name"]; ok && v != nil {
			name, err := reqStr(c.body, "name")
			if err != nil {
				return 0, nil, err
			}
			loc.Name = name
		}
		if v, ok := c.body["coordinate"]; ok && v != nil {
			coord, err := reqCoord(c.body, "coordinate", "invalid_coordinate")
			if err != nil {
				return 0, nil, err
			}
			loc.Coordinate = coord
		}
		if v, ok := c.body["coverageKm"]; ok && v != nil {
			coverage, err := reqNum(c.body, "coverageKm")
			if err != nil {
				return 0, nil, err
			}
			if coverage <= 0 || coverage > 5 {
				return 0, nil, apiErr(400, "invalid_coverage", "coverageKm must be in (0, 5]")
			}
			loc.CoverageKm = coverage
		}
		if v, ok := c.body["handlingMinutes"]; ok && v != nil {
			handling, err := reqNum(c.body, "handlingMinutes")
			if err != nil {
				return 0, nil, err
			}
			if handling < 0 || handling > 1440 {
				return 0, nil, apiErr(400, "invalid_handling_minutes", "handlingMinutes must be in [0, 1440]")
			}
			loc.HandlingMinutes = int(handling)
		}
		if v, ok := c.body["active"]; ok && v != nil {
			active, ok := v.(bool)
			if !ok {
				return 0, nil, apiErr(400, "invalid_json", "active must be a boolean")
			}
			loc.Active = active
		}
		if v, ok := c.body["functions"]; ok && v != nil {
			fns, err := optStrList(c.body, "functions")
