			return 0, nil, apiErr(400, "invalid_location_function", "unknown location function "+fn)
		}
		active, err := reqBool(c.body, "active")
		if err != nil {
			return 0, nil, err
		}
		loc := s.state.Locations[locID]
		if loc == nil || loc.Implicit {
			return 0, nil, apiErr(404, "not_found", "location not found")
		}
		if loc.Functions == nil {
			loc.Functions = map[string]bool{}
		}
		loc.Functions[fn] = active
		s.networkChanged()
		c.audit("set_location_function_status", "location", loc.ID, "", true, map[string]interface{}{"function": fn, "active": active})
		s.emit("location.updated", "location", loc.ID, locationView(loc))
		return 200, J{"locationId": loc.ID, "function": fn, "active": active}, nil
	})
}

