package main

import (
	"encoding/json"
	"strconv"
	"time"
)

// ---------- auth ----------

func (s *Service) hAuthenticate(c *opCtx) (int, interface{}, *ApiError) {
	if err := checkFields(c.body, "username", "password"); err != nil {
		return 0, nil, err
	}
	username, err := reqStr(c.body, "username")
	if err != nil {
		return 0, nil, err
	}
	password, err := reqStr(c.body, "password")
	if err != nil {
		return 0, nil, err
	}
	var user *User
	for _, u := range s.state.Users {
		if u.Username == username {
			user = u
			break
		}
	}
	if user == nil || !user.Active {
		s.audit("", "", "authenticate_user", "user", "", "", false, map[string]interface{}{"username": username, "error": "invalid_credentials"})
		return 0, nil, apiErr(401, "invalid_credentials", "invalid username or password")
	}
	salt := user.ID[:8]
	if user.PasswordHash != hashPassword(password, salt) {
		s.audit("", "", "authenticate_user", "user", user.ID, "", false, map[string]interface{}{"username": username, "error": "invalid_credentials"})
		return 0, nil, apiErr(401, "invalid_credentials", "invalid username or password")
	}
	sess := &Session{Token: newToken(), UserID: user.ID, CreatedAt: time.Now().UTC()}
	if len(user.Roles) == 1 {
		sess.ActiveRole = user.Roles[0]
	}
	s.state.Sessions[sess.Token] = sess
	s.audit(user.ID, sess.ActiveRole, "authenticate_user", "user", user.ID, "", true, map[string]interface{}{"username": username})
	return 200, J{
		"sessionToken": sess.Token,
		"userId":       user.ID,
		"roles":        user.Roles,
		"activeRole":   sess.ActiveRole,
	}, nil
}

func (s *Service) hSelectActiveRole(c *opCtx) (int, interface{}, *ApiError) {
	if err := checkFields(c.body, "role"); err != nil {
		return 0, nil, err
	}
	role, err := reqStr(c.body, "role")
	if err != nil {
		return 0, nil, err
	}
	if !validRole(role) {
		return 0, nil, apiErr(400, "invalid_role", "unknown role "+role)
	}
	if !c.user.HasRole(role) {
		return 0, nil, apiErr(403, "role_not_held", "user does not hold this role")
	}
	c.sess.ActiveRole = role
	c.audit("select_active_role", "user", c.user.ID, "", true, map[string]interface{}{"role": role})
	return 200, J{
		"activeRole": role, "roles": c.user.Roles,
	}, nil
}

func (s *Service) hBootstrap(c *opCtx) (int, interface{}, *ApiError) {
	role := c.sess.ActiveRole
	data := J{
		"user": J{
			"userId": c.user.ID, "username": c.user.Username, "fullName": c.user.FullName,
			"roles": c.user.Roles, "activeRole": role,
			"roleSelectionRequired": role == "",
		},
		"serverTime": fmtTime(time.Now().UTC()),
	}
	if role == RoleRequester {
		samples := []J{}
		for _, sample := range s.state.Samples {
			if sample.RequesterID == c.user.ID {
				samples = append(samples, s.sampleWorkItemView(sample))
			}
		}
		data["requesterSamples"] = samples
	}
	if role == RoleDispatcher || role == RoleAdministrator || role == RoleNodeHandler || role == RoleLaboratoryTeam {
		data["operations"] = s.operationsStateView("")
	}
	return 200, data, nil
}

func (s *Service) hEvents(c *opCtx) (int, interface{}, *ApiError) {
	since := int64(0)
	if v := c.r.URL.Query().Get("since"); v != "" {
		n, err := strconv.ParseInt(v, 10, 64)
		if err != nil || n < 0 {
			return 0, nil, apiErr(400, "invalid_json", "invalid since parameter")
		}
		since = n
	}
	rows, err := s.store.EventsSince(since, 500)
	if err != nil {
		return 0, nil, apiErr(500, "internal_error", "failed to read events")
	}
	events := []J{}
	cursor := since
	for _, e := range rows {
		var payload interface{}
		_ = json.Unmarshal(e.Payload, &payload)
		events = append(events, J{
			"id": e.ID, "type": e.Type, "entityType": e.EntityType, "entityId": e.EntityID,
			"payload": payload, "createdAt": fmtTime(e.CreatedAt),
		})
		if e.ID > cursor {
			cursor = e.ID
		}
	}
	return 200, J{"events": events, "cursor": cursor}, nil
}

// ---------- users ----------

func (s *Service) hCreateUser(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleAdministrator); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "username", "initialPassword", "email", "fullName", "phone", "roles", "qualifications", "certifications", "active", "assignedLocationId"); err != nil {
		return 0, nil, err
	}
	username, err := reqStr(c.body, "username")
	if err != nil {
		return 0, nil, err
	}
	password, err := reqStr(c.body, "initialPassword")
	if err != nil {
		return 0, nil, err
	}
	email, err := optStr(c.body, "email")
	if err != nil {
		return 0, nil, err
	}
	fullName, err := optStr(c.body, "fullName")
	if err != nil {
		return 0, nil, err
	}
	phone, err := optStr(c.body, "phone")
	if err != nil {
		return 0, nil, err
	}
	roles, err := optStrList(c.body, "roles")
	if err != nil {
		return 0, nil, err
	}
	if len(roles) == 0 {
		return 0, nil, apiErr(400, "invalid_user", "roles must be a non-empty array")
	}
	for _, r := range roles {
		if !validRole(r) {
			return 0, nil, apiErr(400, "invalid_user", "unknown role "+r)
		}
	}
	active, err := reqBool(c.body, "active")
	if err != nil {
		return 0, nil, err
	}
	quals, err := optStrList(c.body, "qualifications")
	if err != nil {
		return 0, nil, err
	}
	certs, aerr := parseCertifications(c.body)
	if aerr != nil {
		return 0, nil, aerr
	}
	assignedLoc, err := optStr(c.body, "assignedLocationId")
	if err != nil {
		return 0, nil, err
	}
	for _, u := range s.state.Users {
		if u.Username == username {
			return 0, nil, apiErr(409, "username_exists", "username already exists")
		}
	}
	if assignedLoc != "" {
		loc := s.state.Locations[assignedLoc]
		if loc == nil || loc.Implicit {
			return 0, nil, apiErr(400, "invalid_user", "assigned location not found")
		}
	}
	needsLocation := false
	for _, r := range roles {
		if r == RoleNodeHandler || r == RoleLaboratoryTeam {
			needsLocation = true
		}
	}
	if needsLocation && assignedLoc == "" {
		return 0, nil, apiErr(400, "invalid_user", "assignedLocationId is required for node_handler and laboratory_team roles")
	}
	u := &User{
		ID: newUUID(), Username: username, Email: email, FullName: fullName, Phone: phone,
		Roles: roles, Qualifications: quals, Certifications: certs, Active: active,
		AssignedLocationID: assignedLoc, Available: true, CapacityUnits: 10,
		CreatedAt: time.Now().UTC(),
	}
	u.PasswordHash = hashPassword(password, u.ID[:8])
	s.state.Users[u.ID] = u
	c.audit("create_user", "user", u.ID, "", true, map[string]interface{}{"username": username, "roles": roles})
	s.emit("user.created", "user", u.ID, userView(u))
	return 201, userView(u), nil
}

func parseCertifications(body J) ([]Certification, *ApiError) {
	certs := []Certification{}
	v, ok := body["certifications"]
	if !ok || v == nil {
		return certs, nil
	}
	arr, ok := v.([]interface{})
	if !ok {
		return nil, apiErr(400, "invalid_certification", "certifications must be an array")
	}
	for _, item := range arr {
		m, ok := item.(map[string]interface{})
		if !ok {
			return nil, apiErr(400, "invalid_certification", "certifications must contain objects")
		}
		code, _ := m["code"].(string)
		if code == "" {
			return nil, apiErr(400, "invalid_certification", "certification code is required")
		}
		active, _ := m["active"].(bool)
		var exp *time.Time
		if es, ok := m["expiresAt"].(string); ok && es != "" {
			t, perr := parseTime(es)
			if perr != nil {
				return nil, apiErr(400, "invalid_certification", "invalid certification expiresAt")
			}
			exp = &t
		}
		certs = append(certs, Certification{Code: code, Active: active, ExpiresAt: exp})
	}
	return certs, nil
}

func (s *Service) hUpdateUserAccess(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleAdministrator); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "userId", "roles", "qualifications", "certifications", "active", "assignedLocationId"); err != nil {
		return 0, nil, err
	}
	userID, err := reqStr(c.body, "userId")
	if err != nil {
		return 0, nil, err
	}
	u := s.state.Users[userID]
	if u == nil {
		return 0, nil, apiErr(404, "not_found", "user not found")
	}
	roles, err := optStrList(c.body, "roles")
	if err != nil {
		return 0, nil, err
	}
	if len(roles) == 0 {
		return 0, nil, apiErr(400, "invalid_json", "roles must be a non-empty array")
	}
	for _, r := range roles {
		if !validRole(r) {
			return 0, nil, apiErr(400, "invalid_json", "unknown role "+r)
		}
	}
	u.Roles = roles
	active, err := reqBool(c.body, "active")
	if err != nil {
		return 0, nil, err
	}
	u.Active = active
	if v, ok := c.body["qualifications"]; ok && v != nil {
		quals, err := optStrList(c.body, "qualifications")
		if err != nil {
			return 0, nil, err
		}
		u.Qualifications = quals
	}
	if _, ok := c.body["certifications"]; ok {
		certs, aerr := parseCertifications(c.body)
		if aerr != nil {
			return 0, nil, aerr
		}
		u.Certifications = certs
	}
	if v, ok := c.body["assignedLocationId"]; ok {
		if v == nil {
			u.AssignedLocationID = ""
		} else {
			locID, ok := v.(string)
			if !ok {
				return 0, nil, apiErr(400, "invalid_json", "assignedLocationId must be a string")
			}
			if locID != "" {
				loc := s.state.Locations[locID]
				if loc == nil || loc.Implicit {
					return 0, nil, apiErr(404, "not_found", "assigned location not found")
				}
			}
			u.AssignedLocationID = locID
		}
	}
	c.audit("update_user_access", "user", u.ID, "", true, map[string]interface{}{
		"roles": u.Roles, "active": u.Active, "assignedLocationId": u.AssignedLocationID,
	})
	s.emit("user.updated", "user", u.ID, userView(u))
	quals := u.Qualifications
	if quals == nil {
		quals = []string{}
	}
	certs := []J{}
	for _, cert := range u.Certifications {
		cv := J{"code": cert.Code, "active": cert.Active}
		if cert.ExpiresAt != nil {
			cv["expiresAt"] = fmtTime(*cert.ExpiresAt)
		}
		certs = append(certs, cv)
	}
	return 201, J{
		"userId": u.ID, "roles": u.Roles, "qualifications": quals,
		"certifications": certs, "active": u.Active,
	}, nil
}

func (s *Service) hReadUser(c *opCtx) (int, interface{}, *ApiError) {
	userID, _ := c.body["_pathId"].(string)
	if userID == "" {
		return 0, nil, apiErr(404, "not_found", "user not found")
	}
	if c.sess.ActiveRole != RoleAdministrator && c.user.ID != userID {
		return 0, nil, apiErr(403, "forbidden", "cannot read another user")
	}
	u := s.state.Users[userID]
	if u == nil {
		return 0, nil, apiErr(404, "not_found", "user not found")
	}
	c.audit("read_user", "user", u.ID, "", true, nil)
	return 200, userView(u), nil
}

// ---------- locations ----------

func validLocationFunction(fn string) bool {
	return fn == LocCollectionPoint || fn == LocTransferPoint || fn == LocHub || fn == LocLaboratory
}

func (s *Service) hCreateLocation(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleAdministrator); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "name", "coordinate", "coverageKm", "handlingMinutes", "active", "functions"); err != nil {
		return 0, nil, err
	}
	name, err := reqStr(c.body, "name")
	if err != nil {
		return 0, nil, err
	}
	coord, err := reqCoord(c.body, "coordinate", "invalid_coordinate")
	if err != nil {
		return 0, nil, err
	}
	coverage, err := optNum(c.body, "coverageKm", 5)
	if err != nil {
		return 0, nil, err
	}
	if coverage <= 0 || coverage > 5 {
		return 0, nil, apiErr(400, "invalid_node_coverage", "coverageKm must be in (0, 5]")
	}
	handling, err := optNum(c.body, "handlingMinutes", 0)
	if err != nil {
		return 0, nil, err
	}
	if handling < 0 || handling > 1440 {
		return 0, nil, apiErr(400, "invalid_handling_time", "handlingMinutes must be in [0, 1440]")
	}
	active, err= reqBool(c.body, "active")
	if err != nil {
		return 0, nil, err
	}
	fns, err := optStrList(c.body, "functions")
	if err != nil {
		return 0, nil, err
	}
	if len(fns) == 0 {
		return 0, nil, apiErr(400, "invalid_location_function", "functions must be a non-empty array")
	}
	fnMap := map[string]bool{}
	for _, fn := range fns {
		if !validLocationFunction(fn) {
			return 0, nil, apiErr(400, "invalid_location_function", "unknown location function "+fn)
		}
		fnMap[fn] = true
	}
	loc := &Location{
		ID: newUUID(), Name: name, Coordinate: coord, CoverageKm: coverage,
		HandlingMinutes: int(handling), Active: active, Functions: fnMap,
		CreatedAt: time.Now().UTC(),
	}
	s.state.Locations[loc.ID] = loc
	s.networkChanged()
	c.audit("create_location", "location", loc.ID, "", true, map[string]interface{}{"name": name, "functions": fns})
	s.emit("location.created", "location", loc.ID, locationView(loc))
	return 201, locationView(loc), nil
}

func (s *Service) hUpdateLocation(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleAdministrator); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "locationId", "name", "coordinate", "coverageKm", "handlingMinutes", "active", "functions", "idempotencyKey"); err != nil {
		return 0, nil, err
	}
	return s.runIdempotent(c, "update_location", true, func() (int, interface{}, *ApiError) {
		locID, err := reqStr(c.body, "locationId")
		if err != nil {
			return 0, nil, err
		}
		loc := s.state.Locations[locID]
		if loc == nil || loc.Implicit {
			return 0, nil, apiErr(404, "not_found", "location not found")
		}
		if v, ok := c.body["name"]; ok && v != nil {
			name, err := reqStr(c.body, "name")
			if err != nil {
				return 0, nil, err
			}
			loc.Name = name
		}
		if v, ok := c.body["coordinate"]; ok && v != nil {
			coord, err := reqCoord(c.body, "coordinate", "invalid_coordinate")
			if err != nil {
				return 0, nil, err
			}
			loc.Coordinate = coord
		}
		if v, ok := c.body["coverageKm"]; ok && v != nil {
			coverage, err := reqNum(c.body, "coverageKm")
			if err != nil {
				return 0, nil, err
			}
			if coverage <= 0 || coverage > 5 {
				return 0, nil, apiErr(400, "invalid_coverage", "coverageKm must be in (0, 5]")
			}
			loc.CoverageKm = coverage
		}
		if v, ok := c.body["handlingMinutes"]; ok && v != nil {
			handling, err := reqNum(c.body, "handlingMinutes")
			if err != nil {
				return 0, nil, err
			}
			if handling < 0 || handling > 1440 {
				return 0, nil, apiErr(400, "invalid_handling_minutes", "handlingMinutes must be in [0, 1440]")
			}
			loc.HandlingMinutes = int(handling)
		}
		if v, ok := c.body["active"]; ok && v != nil {
			active, ok := v.(bool)
			if !ok {
				return 0, nil, apiErr(400, "invalid_json", "active must be a boolean")
			}
			loc.Active = active
		}
		if v, ok := c.body["functions"]; ok && v != nil {
			fns, err := optStrList(c.body, "functions")
			if err != nil {
				return 0, nil, err
			}
			if len(fns) == 0 {
				return 0, nil, apiErr(400, "invalid_json", "functions must be a non-empty array")
			}
			fnMap := map[string]bool{}
			for _, fn := range fns {
				if !validLocationFunction(fn) {
					return 0, nil, apiErr(400, "invalid_location_function", "unknown location function "+fn)
				}
				fnMap[fn] = true
			}
			loc.Functions = fnMap
		}
		s.networkChanged()
		c.audit("update_location", "location", loc.ID, "", true, map[string]interface{}{"name": loc.Name})
		s.emit("location.updated", "location", loc.ID, locationView(loc))
		return 201, locationView(loc), nil
	})
}

