func validLocationFunction(fn string) bool {
	return fn == LocCollectionPoint || fn == LocTransferPoint || fn == LocHub || fn == LocLaboratory
}

func (s *Service) hCreateLocation(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleAdministrator); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "name", "coordinate", "coverageKm", "handlingMinutes", "active", "functions"); err != nil {
		return 0, nil, err
	}
	name, err := reqStr(c.body, "name")
	if err != nil {
		return 0, nil, err
	}
	coord, err := reqCoord(c.body, "coordinate", "invalid_coordinate")
	if err != nil {
		return 0, nil, err
	}
	coverage, err := optNum(c.body, "coverageKm", 5)
	if err != nil {
		return 0, nil, err
	}
	if coverage <= 0 || coverage > 5 {
		return 0, nil, apiErr(400, "invalid_node_coverage", "coverageKm must be in (0, 5]")
	}
	handling, err := optNum(c.body, "handlingMinutes", 0)
	if err != nil {
		return 0, nil, err
	}
	if handling < 0 || handling > 1440 {
		return 0, nil, apiErr(400, "invalid_handling_time", "handlingMinutes must be in [0, 1440]")
	}
	active, err= reqBool(c.body, "active")
	if err != nil {
		return 0, nil, err
	}
	fns, err := optStrList(c.body, "functions")
	if err != nil {
		return 0, nil, err
	}
	if len(fns) == 0 {
		return 0, nil, apiErr(400, "invalid_location_function", "functions must be a non-empty array")
	}
	fnMap := map[string]bool{}
	for _, fn := range fns {
		if !validLocationFunction(fn) {
			return 0, nil, apiErr(400, "invalid_location_function", "unknown location function "+fn)
		}
		fnMap[fn] = true
	}
	loc := &Location{
		ID: newUUID(), Name: name, Coordinate: coord, CoverageKm: coverage,
		HandlingMinutes: int(handling), Active: active, Functions: fnMap,
		CreatedAt: time.Now().UTC(),
	}
	s.state.Locations[loc.ID] = loc
	s.networkChanged()
	c.audit("create_location", "location", loc.ID, "", true, map[string]interface{}{"name": name, "functions": fns})
	s.emit("location.created", "location", loc.ID, locationView(loc))
	return 201, locationView(loc), nil
}

