package main

import (
	"encoding/json"
	"strconv"
	"time"
)

// ---------- auth ----------

func (s *Service) hAuthenticate(c *opCtx) (int, interface{}, *ApiError) {
	if err := checkFields(c.body, "username", "password"); err != nil {
		return 0, nil, err
	}
	username, err := reqStr(c.body, "username")
	if err != nil {
		return 0, nil, err
	}
	password, err := reqStr(c.body, "password")
	if err != nil {
		return 0, nil, err
	}
	var user *User
	for _, u := range s.state.Users {
		if u.Username == username {
			user = u
			break
		}
	}
	if user == nil || !user.Active {
		s.audit("", "", "authenticate_user", "user", "", "", false, map[string]interface{}{"username": username, "error": "invalid_credentials"})
		return 0, nil, apiErr(401, "invalid_credentials", "invalid username or password")
	}
	salt := user.ID[:8]
	if user.PasswordHash != hashPassword(password, salt) {
		s.audit("", "", "authenticate_user", "user", user.ID, "", false, map[string]interface{}{"username": username, "error": "invalid_credentials"})
		return 0, nil, apiErr(401, "invalid_credentials", "invalid username or password")
	}
	sess := &Session{Token: newToken(), UserID: user.ID, CreatedAt: time.Now().UTC()}
	if len(user.Roles) == 1 {
		sess.ActiveRole = user.Roles[0]
	}
	s.state.Sessions[sess.Token] = sess
	s.audit(user.ID, sess.ActiveRole, "authenticate_user", "user", user.ID, "", true, map[string]interface{}{"username": username})
	return 200, J{
		"sessionToken": sess.Token,
		"userId":       user.ID,
		"roles":        user.Roles,
		"activeRole":   sess.ActiveRole,
	}, nil
}

func (s *Service) hSelectActiveRole(c *opCtx) (int, interface{}, *ApiError) {
	if err := checkFields(c.body, "role"); err != nil {
		return 0, nil, err
	}
	role, err := reqStr(c.body, "role")
	if err != nil {
		return 0, nil, err
	}
	if !validRole(role) {
		return 0, nil, apiErr(400, "invalid_role", "unknown role "+role)
	}
	if !c.user.HasRole(role) {
		return 0, nil, apiErr(403, "role_not_held", "user does not hold this role")
	}
	c.sess.ActiveRole = role
	c.audit("select_active_role", "user", c.user.ID, "", true, map[string]interface{}{"role": role})
	return 200, J{
		"activeRole": role, "roles": c.user.Roles,
	}, nil
}

func (s *Service) hBootstrap(c *opCtx) (int, interface{}, *ApiError) {
	role := c.sess.ActiveRole
	data := J{
		"user": J{
			"userId": c.user.ID, "username": c.user.Username, "fullName": c.user.FullName,
			"roles": c.user.Roles, "activeRole": role,
			"roleSelectionRequired": role == "",
		},
		"serverTime": fmtTime(time.Now().UTC()),
	}
	if role == RoleRequester {
		samples := []J{}
		for _, sample := range s.state.Samples {
			if sample.RequesterID == c.user.ID {
				samples = append(samples, s.sampleWorkItemView(sample))
			}
		}
		data["requesterSamples"] = samples
	}
	if role == RoleDispatcher || role == RoleAdministrator || role == RoleNodeHandler || role == RoleLaboratoryTeam {
		data["operations"] = s.operationsStateView("")
	}
	return 200, data, nil
}

func (s *Service) hEvents(c *opCtx) (int, interface{}, *ApiError) {
	since := int64(0)
	if v := c.r.URL.Query().Get("since"); v != "" {
		n, err := strconv.ParseInt(v, 10, 64)
		if err != nil || n < 0 {
			return 0, nil, apiErr(400, "invalid_json", "invalid since parameter")
		}
		since = n
	}
	rows, err := s.store.EventsSince(since, 500)
	if err != nil {
		return 0, nil, apiErr(500, "internal_error", "failed to read events")
	}
	events := []J{}
	cursor := since
	for _, e := range rows {
		var payload interface{}
		_ = json.Unmarshal(e.Payload, &payload)
		events = append(events, J{
			"id": e.ID, "type": e.Type, "entityType": e.EntityType, "entityId": e.EntityID,
			"payload": payload, "createdAt": fmtTime(e.CreatedAt),
		})
		if e.ID > cursor {
			cursor = e.ID
		}
	}
	return 200, J{"events": events, "cursor": cursor}, nil
}

// ---------- users ----------

func (s *Service) hCreateUser(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleAdministrator); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "username", "initialPassword", "email", "fullName", "phone", "roles", "qualifications", "certifications", "active", "assignedLocationId"); err != nil {
		return 0, nil, err
	}
	username, err := reqStr(c.body, "username")
	if err != nil {
		return 0, nil, err
	}
	password, err := reqStr(c.body, "initialPassword")
	if err != nil {
		return 0, nil, err
	}
	email, err := optStr(c.body, "email")
	if err != nil {
		return 0, nil, err
	}
	fullName, err := optStr(c.body, "fullName")
	if err != nil {
		return 0, nil, err
	}
	phone, err := optStr(c.body, "phone")
	if err != nil {
		return 0, nil, err
	}
	roles, err := optStrList(c.body, "roles")
	if err != nil {
		return 0, nil, err
	}
	if len(roles) == 0 {
		return 0, nil, apiErr(400, "invalid_user", "roles must be a non-empty array")
	}
	for _, r := range roles {
		if !validRole(r) {
			return 0, nil, apiErr(400, "invalid_user", "unknown role "+r)
		}
	}
	active, err := reqBool(c.body, "active")
	if err != nil {
		return 0, nil, err
	}
	quals, err := optStrList(c.body, "qualifications")
	if err != nil {
		return 0, nil, err
	}
	certs, aerr := parseCertifications(c.body)
	if aerr != nil {
		return 0, nil, aerr
	}
	assignedLoc, err := optStr(c.body, "assignedLocationId")
	if err != nil {
		return 0, nil, err
	}
	for _, u := range s.state.Users {
		if u.Username == username {
			return 0, nil, apiErr(409, "username_exists", "username already exists")
		}
	}
	if assignedLoc != "" {
		loc := s.state.Locations[assignedLoc]
		if loc == nil || loc.Implicit {
			return 0, nil, apiErr(400, "invalid_user", "assigned location not found")
		}
	}
	needsLocation := false
	for _, r := range roles {
		if r == RoleNodeHandler || r == RoleLaboratoryTeam {
			needsLocation = true
		}
	}
	if needsLocation && assignedLoc == "" {
		return 0, nil, apiErr(400, "invalid_user", "assignedLocationId is required for node_handler and laboratory_team roles")
	}
	u := &User{
		ID: newUUID(), Username: username, Email: email, FullName: fullName, Phone: phone,
		Roles: roles, Qualifications: quals, Certifications: certs, Active: active,
		AssignedLocationID: assignedLoc, Available: true, CapacityUnits: 10,
		CreatedAt: time.Now().UTC(),
	}
	u.PasswordHash = hashPassword(password, u.ID[:8])
	s.state.Users[u.ID] = u
	c.audit("create_user", "user", u.ID, "", true, map[string]interface{}{"username": username, "roles": roles})
	s.emit("user.created", "user", u.ID, userView(u))
	return 201, userView(u), nil
}

func parseCertifications(body J) ([]Certification, *ApiError) {
	certs := []Certification{}
	v, ok := body["certifications"]
	if !ok || v == nil {
		return certs, nil
	}
	arr, ok := v.([]interface{})
	if !ok {
		return nil, apiErr(400, "invalid_certification", "certifications must be an array")
	}
	for _, item := range arr {
		m, ok := item.(map[string]interface{})
		if !ok {
			return nil, apiErr(400, "invalid_certification", "certifications must contain objects")
		}
		code, _ := m["code"].(string)
		if code == "" {
			return nil, apiErr(400, "invalid_certification", "certification code is required")
		}
		active, _ := m["active"].(bool)
		var exp *time.Time
		if es, ok := m["expiresAt"].(string); ok && es != "" {
			t, perr := parseTime(es)
			if perr != nil {
				return nil, apiErr(400, "invalid_certification", "invalid certification expiresAt")
			}
			exp = &t
		}
		certs = append(certs, Certification{Code: code, Active: active, ExpiresAt: exp})
	}
	return certs, nil
}

func (s *Service) hUpdateUserAccess(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleAdministrator); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "userId", "roles", "qualifications", "certifications", "active", "assignedLocationId"); err != nil {
		return 0, nil, err
	}
	userID, err := reqStr(c.body, "userId")
	if err != nil {
		return 0, nil, err
	}
	u := s.state.Users[userID]
	if u == nil {
		return 0, nil, apiErr(404, "not_found", "user not found")
	}
	roles, err := optStrList(c.body, "roles")
	if err != nil {
		return 0, nil, err
	}
	if len(roles) == 0 {
		return 0, nil, apiErr(400, "invalid_json", "roles must be a non-empty array")
	}
	for _, r := range roles {
		if !validRole(r) {
			return 0, nil, apiErr(400, "invalid_json", "unknown role "+r)
		}
	}
	u.Roles = roles
	active, err := reqBool(c.body, "active")
	if err != nil {
		return 0, nil, err
	}
	u.Active = active
	if v, ok := c.body["qualifications"]; ok && v != nil {
		quals, err := optStrList(c.body, "qualifications")
		if err != nil {
			return 0, nil, err
		}
		u.Qualifications = quals
	}
	if _, ok := c.body["certifications"]; ok {
		certs, aerr := parseCertifications(c.body)
		if aerr != nil {
			return 0, nil, aerr
		}
		u.Certifications = certs
	}
	if v, ok := c.body["assignedLocationId"]; ok {
		if v == nil {
			u.AssignedLocationID = ""
		} else {
			locID, ok := v.(string)
			if !ok {
				return 0, nil, apiErr(400, "invalid_json", "assignedLocationId must be a string")
			}
			if locID != "" {
				loc := s.state.Locations[locID]
				if loc == nil || loc.Implicit {
					return 0, nil, apiErr(404, "not_found", "assigned location not found")
				}
			}
			u.AssignedLocationID = locID
		}
	}
	c.audit("update_user_access", "user", u.ID, "", true, map[string]interface{}{
		"roles": u.Roles, "active": u.Active, "assignedLocationId": u.AssignedLocationID,
	})
	s.emit("user.updated", "user", u.ID, userView(u))
	quals := u.Qualifications
	if quals == nil {
		quals = []string{}
	}
	certs := []J{}
	for _, cert := range u.Certifications {
		cv := J{"code": cert.Code, "active": cert.Active}
		if cert.ExpiresAt != nil {
			cv["expiresAt"] = fmtTime(*cert.ExpiresAt)
		}
		certs = append(certs, cv)
	}
	return 201, J{
		"userId": u.ID, "roles": u.Roles, "qualifications": quals,
		"certifications": certs, "active": u.Active,
	}, nil
}

func (s *Service) hReadUser(c *opCtx) (int, interface{}, *ApiError) {
	userID, _ := c.body["_pathId"].(string)
	if userID == "" {
		return 0, nil, apiErr(404, "not_found", "user not found")
	}
	if c.sess.ActiveRole != RoleAdministrator && c.user.ID != userID {
		return 0, nil, apiErr(403, "forbidden", "cannot read another user")
	}
	u := s.state.Users[userID]
	if u == nil {
		return 0, nil, apiErr(404, "not_found", "user not found")
	}
	c.audit("read_user", "user", u.ID, "", true, nil)
	return 200, userView(u), nil
}

// ---------- locations ----------

func validLocationFunction(fn string) bool {
	return fn == LocCollectionPoint || fn == LocTransferPoint || fn == LocHub || fn == LocLaboratory
}

func (s *Service) hCreateLocation(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleAdministrator); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "name", "coordinate", "coverageKm", "handlingMinutes", "active", "functions"); err != nil {
		return 0, nil, err
	}
	name, err := reqStr(c.body, "name")
	if err != nil {
		return 0, nil, err
	}
	coord, err := reqCoord(c.body, "coordinate", "invalid_coordinate")
	if err != nil {
		return 0, nil, err
	}
	coverage, err := optNum(c.body, "coverageKm", 5)
	if err != nil {
		return 0, nil, err
	}
	if coverage <= 0 || coverage > 5 {
		return 0, nil, apiErr(400, "invalid_node_coverage", "coverageKm must be in (0, 5]")
	}
	handling, err := optNum(c.body, "handlingMinutes", 0)
	if err != nil {
		return 0, nil, err
	}
	if handling < 0 || handling > 1440 {
		return 0, nil, apiErr(400, "invalid_handling_time", "handlingMinutes must be in [0, 1440]")
	}
	active, err= reqBool(c.body, "active")
	if err != nil {
		return 0, nil, err
	}
	fns, err := optStrList(c.body, "functions")
	if err != nil {
		return 0, nil, err
	}
	if len(fns) == 0 {
		return 0, nil, apiErr(400, "invalid_location_function", "functions must be a non-empty array")
	}
	fnMap := map[string]bool{}
	for _, fn := range fns {
		if !validLocationFunction(fn) {
			return 0, nil, apiErr(400, "invalid_location_function", "unknown location function "+fn)
		}
		fnMap[fn] = true
	}
	loc := &Location{
		ID: newUUID(), Name: name, Coordinate: coord, CoverageKm: coverage,
		HandlingMinutes: int(handling), Active: active, Functions: fnMap,
		CreatedAt: time.Now().UTC(),
	}
	s.state.Locations[loc.ID] = loc
	s.networkChanged()
	c.audit("create_location", "location", loc.ID, "", true, map[string]interface{}{"name": name, "functions": fns})
	s.emit("location.created", "location", loc.ID, locationView(loc))
	return 201, locationView(loc), nil
}

func (s *Service) hUpdateLocation(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleAdministrator); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "locationId", "name", "coordinate", "coverageKm", "handlingMinutes", "functions"); err != nil {
		return 0, nil, err
	}
	locID, err := reqStr(c.body, "locationId")
	if err != nil {
		return 0, nil, err
	}
	loc := s.state.Locations[locID]
	if loc == nil || loc.Implicit {
		return 0, nil, apiErr(404, "not_found", "location not found")
	}
	name, err := reqStr(c.body, "name")
	if err != nil {
		return 0, nil, err
	}
	loc.Name = name
	coord, err := reqCoord(c.body, "coordinate", "invalid_coordinate")
	if err != nil {
		return 0, nil, err
	}
	loc.Coordinate = coord
	if v, ok := c.body["coverageKm"]; ok && v != nil {
		coverage, err := reqNum(c.body, "coverageKm")
		if err != nil {
			return 0, nil, err
		}
		if coverage <= 0 || coverage > 5 {
			return 0, nil, apiErr(400, "invalid_node_coverage", "coverageKm must be in (0, 5]")
		}
		loc.CoverageKm = coverage
	}
	if v, ok := c.body["handlingMinutes"]; ok && v != nil {
		handling, err := reqNum(c.body, "handlingMinutes")
		if err != nil {
			return 0, nil, err
		}
		if handling < 0 || handling > 1440 {
			return 0, nil, apiErr(400, "invalid_handling_time", "handlingMinutes must be in [0, 1440]")
		}
		loc.HandlingMinutes = int(handling)
	}
	if v, ok := c.body["functions"]; ok && v != nil {
		fns, err := optStrList(c.body, "functions")
		if err != nil {
			return 0, nil, err
		}
		if len(fns) == 0 {
			return 0, nil, apiErr(400, "invalid_location_function", "functions must be a non-empty array")
		}
		fnMap := map[string]bool{}
		for _, fn := range fns {
			if !validLocationFunction(fn) {
				return 0, nil, apiErr(400, "invalid_location_function", "unknown location function "+fn)
			}
			fnMap[fn] = true
		}
		loc.Functions = fnMap
	}
	s.networkChanged()
	c.audit("update_location", "location", loc.ID, "", true, map[string]interface{}{"name": loc.Name})
	s.emit("location.updated", "location", loc.ID, locationView(loc))
	return 201, locationView(loc), nil
}

func (s *Service) hSetLocationStatus(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleAdministrator); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "locationId", "active"); err != nil {
		return 0, nil, err
	}
	locID, err := reqStr(c.body, "locationId")
	if err != nil {
		return 0, nil, err
	}
	active, err := reqBool(c.body, "active")
	if err != nil {
		return 0, nil, err
	}
	loc := s.state.Locations[locID]
	if loc == nil || loc.Implicit {
		return 0, nil, apiErr(404, "not_found", "location not found")
	}
	loc.Active = active
	s.networkChanged()
	c.audit("set_location_status", "location", loc.ID, "", true, map[string]interface{}{"active": active})
	s.emit("location.updated", "location", loc.ID, locationView(loc))
	return 200, J{"locationId": loc.ID, "active": loc.Active}, nil
}

func (s *Service) hSetLocationFunctionStatus(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleAdministrator); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "locationId", "function", "active"); err != nil {
		return 0, nil, err
	}
	locID, err := reqStr(c.body, "locationId")
	if err != nil {
		return 0, nil, err
	}
	fn, err := reqStr(c.body, "function")
	if err != nil {
		return 0, nil, err
	}
	if !validLocationFunction(fn) {
		return 0, nil, apiErr(400, "invalid_location_function", "unknown location function "+fn)
	}
	active, err := reqBool(c.body, "active")
	if err != nil {
		return 0, nil, err
	}
	loc := s.state.Locations[locID]
	if loc == nil || loc.Implicit {
		return 0, nil, apiErr(404, "not_found", "location not found")
	}
	if loc.Functions == nil {
		loc.Functions = map[string]bool{}
	}
	loc.Functions[fn] = active
	s.networkChanged()
	c.audit("set_location_function_status", "location", loc.ID, "", true, map[string]interface{}{"function": fn, "active": active})
	s.emit("location.updated", "location", loc.ID, locationView(loc))
	return 200, J{
		"locationId": loc.ID, "function": fn, "active": active,
		"functions": J{
			"collection_point": loc.Functions[LocCollectionPoint],
			"transfer_point":   loc.Functions[LocTransferPoint],
			"hub":              loc.Functions[LocHub],
			"laboratory":       loc.Functions[LocLaboratory],
		},
	}, nil
}

// ---------- connections ----------

func (s *Service) hCreateConnection(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleAdministrator); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "fromLocationId", "toLocationId", "travelMinutes", "costUnits", "cooled", "active"); err != nil {
		return 0, nil, err
	}
	fromID, err := reqStr(c.body, "fromLocationId")
	if err != nil {
		return 0, nil, err
	}
	toID, err := reqStr(c.body, "toLocationId")
	if err != nil {
		return 0, nil, err
	}
	travel, err := reqInt(c.body, "travelMinutes")
	if err != nil {
		return 0, nil, err
	}
	if travel < 1 {
		return 0, nil, apiErr(400, "invalid_connection", "travelMinutes must be >= 1")
	}
	cost, err := reqNum(c.body, "costUnits")
	if err != nil {
		return 0, nil, err
	}
	if cost < 0 {
		return 0, nil, apiErr(400, "invalid_connection", "costUnits must be >= 0")
	}
	cooled, err := optBool(c.body, "cooled", false)
	if err != nil {
		return 0, nil, err
	}
	active, err := reqBool(c.body, "active")
	if err != nil {
		return 0, nil, err
	}
	from := s.state.Locations[fromID]
	to := s.state.Locations[toID]
	if from == nil || from.Implicit || to == nil || to.Implicit {
		return 0, nil, apiErr(400, "invalid_connection", "connection endpoint location not found")
	}
	if fromID == toID {
		return 0, nil, apiErr(400, "invalid_connection", "fromLocationId and toLocationId must differ")
	}
	conn := &Connection{
		ID: newUUID(), FromLocationID: fromID, ToLocationID: toID,
		TravelMinutes: travel, CostUnits: cost, Cooled: cooled, Active: active,
		CreatedAt: time.Now().UTC(),
	}
	s.state.Connections[conn.ID] = conn
	s.networkChanged()
	c.audit("create_connection", "connection", conn.ID, "", true, map[string]interface{}{
		"fromLocationId": fromID, "toLocationId": toID, "travelMinutes": travel,
	})
	s.emit("connection.created", "connection", conn.ID, connectionView(conn))
	return 201, connectionView(conn), nil
}

func (s *Service) hSetConnectionStatus(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleAdministrator); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "connectionId", "active"); err != nil {
		return 0, nil, err
	}
	connID, err := reqStr(c.body, "connectionId")
	if err != nil {
		return 0, nil, err
	}
	active, err := reqBool(c.body, "active")
	if err != nil {
		return 0, nil, err
	}
	conn := s.state.Connections[connID]
	if conn == nil {
		return 0, nil, apiErr(404, "not_found", "connection not found")
	}
	conn.Active = active
	s.networkChanged()
	c.audit("set_connection_status", "connection", conn.ID, "", true, map[string]interface{}{"active": active})
	s.emit("connection.updated", "connection", conn.ID, connectionView(conn))
	return 200, J{"connectionId": conn.ID, "active": conn.Active}, nil
}

// ---------- sample types ----------

func (s *Service) sampleTypeFromBody(body J, existing *SampleType) (*SampleType, *ApiError) {
	t := &SampleType{}
	if existing != nil {
		cp := *existing
		t = &cp
	}
	if v, ok := body["name"]; ok && v != nil {
		name, err := reqStr(body, "name")
		if err != nil {
			return nil, err
		}
		t.Name = name
	} else if existing == nil {
		return nil, apiErr(400, "invalid_json", "missing required field \"name\"")
	}
	if v, ok := body["qualifiedCollectorRequired"]; ok && v != nil {
		b, err := reqBool(body, "qualifiedCollectorRequired")
		if err != nil {
			return nil, err
		}
		t.QualifiedCollectorRequired = b
	}
	if v, ok := body["requiredQualification"]; ok && v != nil {
		q, err := optStr(body, "requiredQualification")
		if err != nil {
			return nil, err
		}
		t.RequiredQualification = q
	}
	if v, ok := body["containerType"]; ok && v != nil {
		ct, err := reqStr(body, "containerType")
		if err != nil {
			return nil, err
		}
		t.ContainerType = ct
	} else if existing == nil {
		return nil, apiErr(400, "invalid_json", "missing required field \"containerType\"")
	}
	if v, ok := body["temperatureMinC"]; ok && v != nil {
		n, err := reqNum(body, "temperatureMinC")
		if err != nil {
			return nil, err
		}
		t.TemperatureMinC = n
	} else if existing == nil {
		return nil, apiErr(400, "invalid_json", "missing required field \"temperatureMinC\"")
	}
	if v, ok := body["temperatureMaxC"]; ok && v != nil {
		n, err := reqNum(body, "temperatureMaxC")
		if err != nil {
			return nil, err
		}
		t.TemperatureMaxC = n
	} else if existing == nil {
		return nil, apiErr(400, "invalid_json", "missing required field \"temperatureMaxC\"")
	}
	if t.TemperatureMinC > t.TemperatureMaxC {
		return nil, apiErr(400, "invalid_handling_rule", "temperatureMinC must be <= temperatureMaxC")
	}
	if v, ok := body["incompatibleSampleTypes"]; ok && v != nil {
		list, err := optStrList(body, "incompatibleSampleTypes")
		if err != nil {
			return nil, err
		}
		t.IncompatibleSampleTypes = list
	}
	if v, ok := body["requiresCooledRoute"]; ok && v != nil {
		b, err := reqBool(body, "requiresCooledRoute")
		if err != nil {
			return nil, err
		}
		t.RequiresCooledRoute = b
	}
	if v, ok := body["batchingAllowed"]; ok && v != nil {
		b, err := reqBool(body, "batchingAllowed")
		if err != nil {
			return nil, err
		}
		t.BatchingAllowed = b
	}
	return t, nil
}

func (s *Service) hCreateSampleType(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleAdministrator); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "name", "qualifiedCollectorRequired", "requiredQualification", "containerType", "temperatureMinC", "temperatureMaxC", "incompatibleSampleTypes", "requiresCooledRoute", "batchingAllowed"); err != nil {
		return 0, nil, err
	}
	t, aerr := s.sampleTypeFromBody(c.body, nil)
	if aerr != nil {
		return 0, nil, aerr
	}
	for _, other := range s.state.SampleTypes {
		if other.Name == t.Name {
			return 0, nil, apiErr(400, "invalid_handling_rule", "a sample type with this name already exists")
		}
	}
	t.ID = newUUID()
	s.state.SampleTypes[t.ID] = t
	s.networkChanged()
	c.audit("create_sample_type", "sample_type", t.ID, "", true, map[string]interface{}{"name": t.Name})
	s.emit("sample_type.created", "sample_type", t.ID, sampleTypeView(t))
	return 201, sampleTypeView(t), nil
}

func (s *Service) hUpdateSampleType(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleAdministrator); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "sampleTypeId", "qualifiedCollectorRequired", "requiredQualification", "containerType", "temperatureMinC", "temperatureMaxC", "incompatibleSampleTypes", "requiresCooledRoute", "batchingAllowed"); err != nil {
		return 0, nil, err
	}
	typeID, err := reqStr(c.body, "sampleTypeId")
	if err != nil {
		return 0, nil, err
	}
	existing := s.state.SampleTypes[typeID]
	if existing == nil {
		return 0, nil, apiErr(404, "not_found", "sample type not found")
	}
	t, aerr := s.sampleTypeFromBody(c.body, existing)
	if aerr != nil {
		return 0, nil, aerr
	}
	for _, other := range s.state.SampleTypes {
		if other.ID != typeID && other.Name == t.Name {
			return 0, nil, apiErr(400, "invalid_handling_rule", "a sample type with this name already exists")
		}
	}
	t.ID = typeID
	s.state.SampleTypes[typeID] = t
	s.networkChanged()
	c.audit("update_sample_type", "sample_type", t.ID, "", true, map[string]interface{}{"name": t.Name})
	s.emit("sample_type.updated", "sample_type", t.ID, sampleTypeView(t))
	return 201, sampleTypeView(t), nil
}

// ---------- capacity ----------

func (s *Service) hConfigureCapacity(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleAdministrator, RoleNodeHandler, RoleLaboratoryTeam); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "resourceId", "capacityUnits", "cooledCapacityUnits", "idempotencyKey"); err != nil {
		return 0, nil, err
	}
	return s.runIdempotent(c, "configure_capacity", true, func() (int, interface{}, *ApiError) {
		resourceID, err := reqStr(c.body, "resourceId")
		if err != nil {
			return 0, nil, err
		}
		units, err := reqInt(c.body, "capacityUnits")
		if err != nil {
			return 0, nil, err
		}
		if units < 0 {
			return 0, nil, apiErr(400, "invalid_capacity", "capacityUnits must be >= 0")
		}
		cooled, err := optNum(c.body, "cooledCapacityUnits", 0)
		if err != nil {
			return 0, nil, err
		}
		if cooled < 0 {
			return 0, nil, apiErr(400, "invalid_capacity", "cooledCapacityUnits must be >= 0")
		}
		var pool *CapacityPool
		resourceType := ""
		if loc := s.state.Locations[resourceID]; loc != nil && !loc.Implicit {
			pool = &loc.Capacity
			resourceType = "location"
			if c.sess.ActiveRole == RoleNodeHandler || c.sess.ActiveRole == RoleLaboratoryTeam {
				if c.user.AssignedLocationID != loc.ID {
					return 0, nil, apiErr(403, "forbidden", "can only configure capacity at your assigned location")
				}
			}
		} else if conn := s.state.Connections[resourceID]; conn != nil {
			pool = &conn.Capacity
			resourceType = "connection"
			if c.sess.ActiveRole != RoleAdministrator {
				return 0, nil, apiErr(403, "forbidden", "only administrators can configure connection capacity")
			}
		} else {
			return 0, nil, apiErr(404, "not_found", "capacity resource not found")
		}
		if units < pool.ReservedUnits || int(cooled) < pool.CooledReservedUnits {
			return 0, nil, apiErr(409, "capacity_reserved", "cannot set capacity below currently reserved units")
		}
		pool.CapacityUnits = units
		pool.CooledCapacityUnits = int(cooled)
		s.networkChanged()
		c.audit("configure_capacity", resourceType, resourceID, "", true, map[string]interface{}{
			"capacityUnits": units, "cooledCapacityUnits": int(cooled),
		})
		s.emit("capacity.updated", resourceType, jID(resourceID), capacityView(*pool))
		return 200, J{
			"resourceId": resourceID, "capacityUnits": pool.CapacityUnits,
			"reservedUnits": pool.ReservedUnits, "availableUnits": pool.CapacityUnits - pool.ReservedUnits,
			"cooledCapacityUnits": pool.CooledCapacityUnits, "cooledReservedUnits": pool.CooledReservedUnits,
			"cooledAvailableUnits": pool.CooledCapacityUnits - pool.CooledReservedUnits,
		}, nil
	})
}

func jID(s string) string { return s }

func (s *Service) hConfigureLabAcceptance(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleAdministrator, RoleLaboratoryTeam); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "laboratoryId", "acceptedSampleTypeIds", "idempotencyKey"); err != nil {
		return 0, nil, err
	}
	return s.runIdempotent(c, "configure_laboratory_acceptance", true, func() (int, interface{}, *ApiError) {
		labID, err := reqStr(c.body, "laboratoryId")
		if err != nil {
			return 0, nil, err
		}
		ids, err := optStrList(c.body, "acceptedSampleTypeIds")
		if err != nil {
			return 0, nil, err
		}
		if ids == nil {
			return 0, nil, apiErr(400, "invalid_json", "missing required field \"acceptedSampleTypeIds\"")
		}
		lab := s.state.Locations[labID]
		if lab == nil || lab.Implicit || !lab.HasFunction(LocLaboratory) {
			return 0, nil, apiErr(404, "not_found", "laboratory not found")
		}
		if c.sess.ActiveRole == RoleLaboratoryTeam && c.user.AssignedLocationID != lab.ID {
			return 0, nil, apiErr(403, "forbidden", "can only configure your assigned laboratory")
		}
		for _, id := range ids {
			if s.state.SampleTypes[id] == nil {
				return 0, nil, apiErr(404, "not_found", "sample type not found: "+id)
			}
		}
		lab.AcceptedSampleTypeIDs = ids
		s.networkChanged()
		c.audit("configure_laboratory_acceptance", "location", lab.ID, "", true, map[string]interface{}{
			"acceptedSampleTypeIds": ids,
		})
		s.emit("location.updated", "location", lab.ID, operationsLocationView(lab))
		return 200, J{"laboratoryId": lab.ID, "acceptedSampleTypeIds": ids}, nil
	})
}

// ---------- worker availability ----------

func (s *Service) hSetWorkerAvailability(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleCollectionPro, RoleDeliveryPartner, RoleNodeHandler, RoleLaboratoryTeam, RoleDispatcher, RoleAdministrator); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "workerId", "available", "capacityUnits", "idempotencyKey"); err != nil {
		return 0, nil, err
	}
	return s.runIdempotent(c, "set_worker_availability", true, func() (int, interface{}, *ApiError) {
		workerID, err := reqStr(c.body, "workerId")
		if err != nil {
			return 0, nil, err
		}
		available, err := reqBool(c.body, "available")
		if err != nil {
			return 0, nil, err
		}
		units, err := reqInt(c.body, "capacityUnits")
		if err != nil {
			return 0, nil, err
		}
		if units < 0 {
			return 0, nil, apiErr(400, "invalid_capacity", "capacityUnits must be >= 0")
		}
		worker := s.state.Users[workerID]
		if worker == nil {
			return 0, nil, apiErr(404, "not_found", "worker not found")
		}
		isWorkerRole := false
		for _, r := range worker.Roles {
			if r == RoleCollectionPro || r == RoleDeliveryPartner || r == RoleNodeHandler || r == RoleLaboratoryTeam {
				isWorkerRole = true
			}
		}
		if !isWorkerRole {
			return 0, nil, apiErr(403, "forbidden", "target user is not a worker")
		}
		if c.user.ID != workerID && c.sess.ActiveRole != RoleDispatcher && c.sess.ActiveRole != RoleAdministrator {
			return 0, nil, apiErr(403, "forbidden", "cannot set availability for another worker")
		}
		worker.Available = available
		worker.CapacityUnits = units
		c.audit("set_worker_availability", "user", worker.ID, "", true, map[string]interface{}{
			"available": available, "capacityUnits": units,
		})
		s.emit("worker.availability", "user", worker.ID, map[string]interface{}{
			"workerId": worker.ID, "available": available, "capacityUnits": units,
		})
		return 200, J{"workerId": worker.ID, "available": worker.Available, "capacityUnits": worker.CapacityUnits}, nil
	})
}

