	if !res.EstimatedArrival.IsZero() {
		resp["estimatedArrivalAt"] = fmtTime(res.EstimatedArrival)
	}
	return 200, resp, nil
}

func (s *Service) createRequestCommon(c *opCtx, op string, presealed bool) (int, interface{}, *ApiError) {
	spec, aerr := parseOriginSpec(c.body, true)
	if aerr != nil {
		return 0, nil, aerr
	}
	sampleTypeID, aerr := reqStr(c.body, "sampleTypeId")
	if aerr != nil {
		return 0, nil, aerr
	}
	containerType, aerr := reqStr(c.body, "containerType")
	if aerr != nil {
		return 0, nil, aerr
	}
	tempMin, aerr := reqNum(c.body, "temperatureMinC")
	if aerr != nil {
		return 0, nil, aerr
	}
	tempMax, aerr := reqNum(c.body, "temperatureMaxC")
	if aerr != nil {
		return 0, nil, aerr
	}
	if tempMin > tempMax {
		return 0, nil, apiErr(400, "handling_mismatch", "temperatureMinC must be <= temperatureMaxC")
	}
	incompat, aerr := optStrList(c.body, "incompatibleSampleTypes")
	if aerr != nil {
		return 0, nil, aerr
	}
	requesterID, aerr := optStr(c.body, "requesterId")
	if aerr != nil {
		return 0, nil, aerr
	}
	sampleType := s.state.SampleTypes[sampleTypeID]
	if sampleType == nil {
		return 0, nil, apiErr(404, "not_found", "sample type not found")
	}
	if !presealed {
		if requesterID != "" && requesterID != c.user.ID {
			return 0, nil, apiErr(403, "forbidden", "cannot create a request for another requester")
		}
		requesterID = c.user.ID
	} else {
		if requesterID == "" {
			requesterID = c.user.ID
		}
		if spec.OriginType == "home" {
			return 0, nil, apiErr(400, "invalid_origin_type", "pre-sealed samples must originate from a clinic or node")
		}
	}
	// handling attributes must match the sample type
	if containerType != sampleType.ContainerType ||
		tempMin < sampleType.TemperatureMinC || tempMax > sampleType.TemperatureMaxC {
		return 0, nil, apiErr(400, "handling_mismatch", "container and temperature requirements do not match the sample type")
	}
	if spec.OriginType == "node" {
		loc := s.state.Locations[spec.OriginNodeID]
		if loc == nil || loc.Implicit {
			return 0, nil, apiErr(400, "invalid_origin", "origin node not found")
		}
		if !loc.Active || !loc.HasFunction(LocCollectionPoint) {
			return 0, nil, apiErr(400, "invalid_origin_state", "origin node is not an active collection point")
		}
	}
	now := time.Now().UTC()
	req := &Request{
		ID: newUUID(), RequesterID: requesterID,
		Origin: spec.Origin, OriginType: spec.OriginType, OriginNodeID: spec.OriginNodeID,
		RequestedAt: spec.RequestedAt, DeliveryDeadline: spec.Deadline,
		EarliestCollectionAt: spec.Earliest, LatestCollectionAt: spec.Latest,
		SampleTypeID: sampleTypeID, ContainerType: containerType,
		TemperatureMinC: tempMin, TemperatureMaxC: tempMax,
		IncompatibleSampleTypes: incompat, AlreadySealed: presealed, CreatedAt: now,
	}
	sample := &Sample{
		ID: newUUID(), RequestID: req.ID, RequesterID: requesterID,
		Origin: spec.Origin, OriginType: spec.OriginType,
		RequestedAt: spec.RequestedAt, DeliveryDeadline: spec.Deadline,
		EarliestCollectionAt: spec.Earliest, LatestCollectionAt: spec.Latest,
		SampleTypeID: sampleTypeID, ContainerType: containerType,
		TemperatureMinC: tempMin, TemperatureMaxC: tempMax,
		IncompatibleSampleTypes: incompat,
		Status: SampleRequested, CreatedAt: now,
	}
	res := s.checkServiceability(spec.Origin, spec.OriginType, spec.OriginNodeID, sampleType, spec.RequestedAt, spec.Deadline, spec.Earliest)
	if !res.Serviceable {
		req.Serviceability = "unserviceable"
		req.ServiceabilityReason = res.Reason
		sample.Serviceability = "unserviceable"
		s.state.Requests[req.ID] = req
		s.state.Samples[sample.ID] = sample
		c.audit(op, "request", req.ID, sample.ID, true, map[string]interface{}{
			"serviceability": "unserviceable", "reason": res.Reason,
		})
		s.emit("request.created", "request", req.ID, map[string]interface{}{
			"requestId": req.ID, "sampleId": sample.ID, "serviceability": "unserviceable",
		})
		return 201, J{
			"requestId": req.ID, "sampleId": sample.ID, "journeyId": nil,
			"serviceability": "unserviceable", "serviceabilityReason": res.Reason,
			"activeAssignmentIds": []string{}, "alreadySealed": presealed,
			"earliestCollectionAt": fmtTime(spec.Earliest), "latestCollectionAt": fmtTime(spec.Latest),
			"originType": spec.OriginType,
		}, nil
	}
	req.Serviceability = "serviceable"
	req.ServiceabilityReason = "serviceable"
	sample.Serviceability = "serviceable"
	s.state.Requests[req.ID] = req
	s.state.Samples[sample.ID] = sample
	start := spec.RequestedAt
	if spec.Earliest.After(start) {
		start = spec.Earliest
	}
	journey := s.buildJourney(sample, req, res.Plan, start, !presealed)
	if presealed {
		sample.Sealed = true
		t := now
		sample.SealedAt = &t
		sample.Status = SampleSealed
		sample.CurrentHolderID = c.user.ID
		loc := s.state.Locations[sample.OriginLocationID]
		if loc != nil {
			c := loc.Coordinate
			sample.LatestLocation = &c
			sample.LocationRecordedAt = &t
		}
	}
	activeAsg := []string{}
	for _, a := range s.state.Assignments {
		if a.SampleID == sample.ID && a.Status != AsgCompleted && a.Status != AsgCancelled {
			activeAsg = append(activeAsg, a.ID)
		}
	}
