		"requestId": req.ID, "sampleId": sample.ID, "journeyId": journey.ID,
	})
	return 201, J{
		"requestId": req.ID, "sampleId": sample.ID, "journeyId": journey.ID,
		"serviceability": "serviceable", "serviceabilityReason": "serviceable",
		"activeAssignmentIds": activeAsg, "alreadySealed": presealed,
