package main

import (
	"time"
)

type originSpec struct {
	Origin      Coordinate
	OriginType  string
	OriginNodeID string
	RequestedAt time.Time
	Deadline    time.Time
	Earliest    time.Time
	Latest      time.Time
}

func parseOriginSpec(body J, forCreate bool) (*originSpec, *ApiError) {
	origin, aerr := reqCoord(body, "origin", "invalid_origin")
	if aerr != nil {
		return nil, aerr
	}
	originType, aerr := optStr(body, "originType")
	if aerr != nil {
		return nil, aerr
	}
	if originType == "" {
		originType = "home"
	}
	if originType != "home" && originType != "clinic" && originType != "node" {
		return nil, apiErr(400, "invalid_origin_type", "originType must be home, clinic or node")
	}
	originNodeID, aerr := optStr(body, "originNodeId")
	if aerr != nil {
		return nil, aerr
	}
	requestedAt, aerr := reqTimeField(body, "requestedAt")
	if aerr != nil {
		return nil, aerr
	}
	deadline, aerr := reqTimeField(body, "deliveryDeadline")
	if aerr != nil {
		return nil, aerr
	}
	if !deadline.After(requestedAt) {
		return nil, apiErr(400, "invalid_deadline", "deliveryDeadline must be after requestedAt")
	}
	earliest := requestedAt
	if t, aerr := optTimeField(body, "earliestCollectionAt"); aerr != nil {
		return nil, aerr
	} else if t != nil {
		earliest = *t
	}
	latest := deadline
	if t, aerr := optTimeField(body, "latestCollectionAt"); aerr != nil {
		return nil, aerr
	} else if t != nil {
		latest = *t
	}
	if latest.Before(earliest) {
		return nil, apiErr(400, "invalid_collection_window", "latestCollectionAt must be at or after earliestCollectionAt")
	}
	if originType == "node" && originNodeID == "" {
		return nil, apiErr(400, "invalid_origin", "originNodeId is required when originType is node")
	}
	return &originSpec{
		Origin: origin, OriginType: originType, OriginNodeID: originNodeID,
		RequestedAt: requestedAt, Deadline: deadline, Earliest: earliest, Latest: latest,
	}, nil
}

func (s *Service) hCheckServiceability(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleRequester, RoleDispatcher, RoleAdministrator); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "origin", "originType", "originNodeId", "sampleTypeId", "requestedAt", "deliveryDeadline", "earliestCollectionAt", "latestCollectionAt"); err != nil {
		return 0, nil, err
	}
	spec, aerr := parseOriginSpec(c.body, false)
	if aerr != nil {
		return 0, nil, aerr
	}
	sampleTypeID, aerr := reqStr(c.body, "sampleTypeId")
	if aerr != nil {
		return 0, nil, aerr
	}
	sampleType := s.state.SampleTypes[sampleTypeID]
	if sampleType == nil {
		return 0, nil, apiErr(404, "not_found", "sample type not found")
	}
	if spec.OriginType == "node" {
		loc := s.state.Locations[spec.OriginNodeID]
		if loc == nil || loc.Implicit {
			return 0, nil, apiErr(400, "invalid_origin", "origin node not found")
		}
	}
	// dry run: computes against the published snapshot only, creates nothing
	res := s.checkServiceability(spec.Origin, spec.OriginType, spec.OriginNodeID, sampleType, spec.RequestedAt, spec.Deadline, spec.Earliest)
	c.audit("check_serviceability", "", "", "", true, map[string]interface{}{
		"serviceable": res.Serviceable, "reason": res.Reason, "sampleTypeId": sampleTypeID,
	})
	resp := J{
		"serviceable":          res.Serviceable,
		"reason":               res.Reason,
		"serviceabilityVersion": s.state.Snapshot.Version,
	}
	if res.TargetLabID != "" {
		resp["targetLaboratoryId"] = res.TargetLabID
	}
	if !res.EstimatedArrival.IsZero() {
		resp["estimatedArrivalAt"] = fmtTime(res.EstimatedArrival)
	}
	return 200, resp, nil
}

func (s *Service) createRequestCommon(c *opCtx, op string, presealed bool) (int, interface{}, *ApiError) {
	spec, aerr := parseOriginSpec(c.body, true)
	if aerr != nil {
		return 0, nil, aerr
	}
	sampleTypeID, aerr := reqStr(c.body, "sampleTypeId")
	if aerr != nil {
		return 0, nil, aerr
	}
	containerType, aerr := reqStr(c.body, "containerType")
	if aerr != nil {
		return 0, nil, aerr
	}
	tempMin, aerr := reqNum(c.body, "temperatureMinC")
	if aerr != nil {
		return 0, nil, aerr
	}
	tempMax, aerr := reqNum(c.body, "temperatureMaxC")
	if aerr != nil {
		return 0, nil, aerr
	}
	if tempMin > tempMax {
		return 0, nil, apiErr(400, "handling_mismatch", "temperatureMinC must be <= temperatureMaxC")
	}
	incompat, aerr := optStrList(c.body, "incompatibleSampleTypes")
	if aerr != nil {
		return 0, nil, aerr
	}
	requesterID, aerr := optStr(c.body, "requesterId")
	if aerr != nil {
		return 0, nil, aerr
	}
	sampleType := s.state.SampleTypes[sampleTypeID]
	if sampleType == nil {
		return 0, nil, apiErr(404, "not_found", "sample type not found")
	}
	if !presealed {
		if requesterID != "" && requesterID != c.user.ID {
			return 0, nil, apiErr(403, "forbidden", "cannot create a request for another requester")
		}
		requesterID = c.user.ID
	} else {
		if requesterID == "" {
			requesterID = c.user.ID
		}
		if spec.OriginType == "home" {
			return 0, nil, apiErr(400, "invalid_origin_type", "pre-sealed samples must originate from a clinic or node")
		}
	}
	// handling attributes must match the sample type
	if containerType != sampleType.ContainerType ||
		tempMin < sampleType.TemperatureMinC || tempMax > sampleType.TemperatureMaxC {
		return 0, nil, apiErr(400, "handling_mismatch", "container and temperature requirements do not match the sample type")
	}
	if spec.OriginType == "node" {
		loc := s.state.Locations[spec.OriginNodeID]
		if loc == nil || loc.Implicit {
			return 0, nil, apiErr(400, "invalid_origin", "origin node not found")
		}
		if !loc.Active || !loc.HasFunction(LocCollectionPoint) {
			return 0, nil, apiErr(400, "invalid_origin_state", "origin node is not an active collection point")
		}
	}
	now := time.Now().UTC()
	req := &Request{
		ID: newUUID(), RequesterID: requesterID,
		Origin: spec.Origin, OriginType: spec.OriginType, OriginNodeID: spec.OriginNodeID,
		RequestedAt: spec.RequestedAt, DeliveryDeadline: spec.Deadline,
		EarliestCollectionAt: spec.Earliest, LatestCollectionAt: spec.Latest,
		SampleTypeID: sampleTypeID, ContainerType: containerType,
		TemperatureMinC: tempMin, TemperatureMaxC: tempMax,
		IncompatibleSampleTypes: incompat, AlreadySealed: presealed, CreatedAt: now,
	}
	sample := &Sample{
		ID: newUUID(), RequestID: req.ID, RequesterID: requesterID,
		Origin: spec.Origin, OriginType: spec.OriginType,
		RequestedAt: spec.RequestedAt, DeliveryDeadline: spec.Deadline,
		EarliestCollectionAt: spec.Earliest, LatestCollectionAt: spec.Latest,
		SampleTypeID: sampleTypeID, ContainerType: containerType,
		TemperatureMinC: tempMin, TemperatureMaxC: tempMax,
		IncompatibleSampleTypes: incompat,
		Status: SampleRequested, CreatedAt: now,
	}
	res := s.checkServiceability(spec.Origin, spec.OriginType, spec.OriginNodeID, sampleType, spec.RequestedAt, spec.Deadline, spec.Earliest)
	if !res.Serviceable {
		req.Serviceability = "unserviceable"
		req.ServiceabilityReason = res.Reason
		sample.Serviceability = "unserviceable"
		s.state.Requests[req.ID] = req
		s.state.Samples[sample.ID] = sample
		c.audit(op, "request", req.ID, sample.ID, true, map[string]interface{}{
			"serviceability": "unserviceable", "reason": res.Reason,
		})
		s.emit("request.created", "request", req.ID, map[string]interface{}{
			"requestId": req.ID, "sampleId": sample.ID, "serviceability": "unserviceable",
		})
		return 201, J{
			"requestId": req.ID, "sampleId": sample.ID, "journeyId": nil,
			"serviceability": "unserviceable", "serviceabilityReason": res.Reason,
			"activeAssignmentIds": []string{}, "alreadySealed": presealed,
			"earliestCollectionAt": fmtTime(spec.Earliest), "latestCollectionAt": fmtTime(spec.Latest),
			"originType": spec.OriginType,
		}, nil
	}
	req.Serviceability = "serviceable"
	req.ServiceabilityReason = "serviceable"
	sample.Serviceability = "serviceable"
	s.state.Requests[req.ID] = req
	s.state.Samples[sample.ID] = sample
	start := spec.RequestedAt
	if spec.Earliest.After(start) {
		start = spec.Earliest
	}
	journey := s.buildJourney(sample, req, res.Plan, start, !presealed)
	if presealed {
		sample.Sealed = true
		t := now
		sample.SealedAt = &t
		sample.Status = SampleSealed
		sample.CurrentHolderID = c.user.ID
		loc := s.state.Locations[sample.OriginLocationID]
		if loc != nil {
			c := loc.Coordinate
			sample.LatestLocation = &c
			sample.LocationRecordedAt = &t
		}
	}
	activeAsg := []string{}
	for _, a := range s.state.Assignments {
		if a.SampleID == sample.ID && a.Status != AsgCompleted && a.Status != AsgCancelled {
			activeAsg = append(activeAsg, a.ID)
		}
	}
	c.audit(op, "request", req.ID, sample.ID, true, map[string]interface{}{
		"serviceability": "serviceable", "journeyId": journey.ID, "alreadySealed": presealed,
	})
	s.emit("request.created", "request", req.ID, map[string]interface{}{
		"requestId": req.ID, "sampleId": sample.ID, "journeyId": journey.ID,
	})
	return 201, J{
		"requestId": req.ID, "sampleId": sample.ID, "journeyId": journey.ID,
		"serviceability": "serviceable", "serviceabilityReason": "serviceable",
		"activeAssignmentIds": activeAsg, "alreadySealed": presealed,
		"earliestCollectionAt": fmtTime(spec.Earliest), "latestCollectionAt": fmtTime(spec.Latest),
		"originType": spec.OriginType, "targetLaboratoryId": res.TargetLabID,
	}, nil
}

func (s *Service) hCreateCollectionRequest(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleRequester); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "requesterId", "origin", "originType", "originNodeId", "requestedAt", "deliveryDeadline", "earliestCollectionAt", "latestCollectionAt", "sampleTypeId", "containerType", "temperatureMinC", "temperatureMaxC", "incompatibleSampleTypes", "idempotencyKey"); err != nil {
		return 0, nil, err
	}
	return s.runIdempotent(c, "create_collection_request", false, func() (int, interface{}, *ApiError) {
		return s.createRequestCommon(c, "create_collection_request", false)
	})
}

func (s *Service) hIngestPresealed(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleCollectionPro, RoleDeliveryPartner, RoleNodeHandler, RoleLaboratoryTeam); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "requesterId", "origin", "originType", "originNodeId", "requestedAt", "deliveryDeadline", "earliestCollectionAt", "latestCollectionAt", "sampleTypeId", "containerType", "temperatureMinC", "temperatureMaxC", "incompatibleSampleTypes", "idempotencyKey"); err != nil {
		return 0, nil, err
	}
	return s.runIdempotent(c, "ingest_presealed_sample", true, func() (int, interface{}, *ApiError) {
		return s.createRequestCommon(c, "ingest_presealed_sample", true)
	})
}

// ---------- reads ----------

func (s *Service) canSeeSample(user *User, role string, sample *Sample) bool {
	switch role {
	case RoleAdministrator, RoleDispatcher:
		return true
	case RoleRequester:
		return sample.RequesterID == user.ID
	case RoleCollectionPro, RoleDeliveryPartner, RoleNodeHandler, RoleLaboratoryTeam:
		if sample.CurrentHolderID == user.ID {
			return true
		}
		for _, a := range s.state.Assignments {
			if a.SampleID == sample.ID && (a.AcceptedWorkerID == user.ID || a.OfferedToWorkerID == user.ID) {
				return true
			}
		}
	}
	return false
}

func (s *Service) hReadSampleState(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleRequester, RoleDispatcher, RoleAdministrator, RoleCollectionPro, RoleDeliveryPartner, RoleNodeHandler, RoleLaboratoryTeam); err != nil {
		return 0, nil, err
	}
	sampleID, _ := c.body["_pathId"].(string)
	sample := s.state.Samples[sampleID]
	if sample == nil {
		return 0, nil, apiErr(404, "not_found", "sample not found")
	}
	if !s.canSeeSample(c.user, c.sess.ActiveRole, sample) {
		return 0, nil, apiErr(403, "forbidden", "not permitted to view this sample")
	}
	c.audit("read_sample_state", "sample", sample.ID, sample.ID, true, nil)
	return 200, s.sampleStateView(sample), nil
}

func (s *Service) hReadSampleLifecycle(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleRequester, RoleDispatcher, RoleAdministrator, RoleCollectionPro, RoleDeliveryPartner, RoleNodeHandler, RoleLaboratoryTeam); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "sampleId"); err != nil {
		return 0, nil, err
	}
	sampleID, err := reqStr(c.body, "sampleId")
	if err != nil {
		return 0, nil, err
	}
	sample := s.state.Samples[sampleID]
	if sample == nil {
		return 0, nil, apiErr(404, "not_found", "sample not found")
	}
	if !s.canSeeSample(c.user, c.sess.ActiveRole, sample) {
		return 0, nil, apiErr(403, "forbidden", "not permitted to view this sample")
	}
	c.audit("read_sample_lifecycle", "sample", sample.ID, sample.ID, true, nil)
	return 200, s.sampleLifecycleView(sample), nil
}

func (s *Service) hReadJourneyPlan(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleRequester, RoleDispatcher, RoleAdministrator, RoleCollectionPro, RoleDeliveryPartner, RoleNodeHandler, RoleLaboratoryTeam); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "journeyId"); err != nil {
		return 0, nil, err
	}
	journeyID, err := reqStr(c.body, "journeyId")
	if err != nil {
		return 0, nil, err
	}
	j := s.state.Journeys[journeyID]
	if j == nil {
		return 0, nil, apiErr(404, "not_found", "journey not found")
	}
	role := c.sess.ActiveRole
	if role == RoleDispatcher || role == RoleAdministrator {
		c.audit("read_journey_plan", "journey", j.ID, "", true, nil)
		return 200, s.journeyPlanView(j, 2), nil
	}
	if role == RoleRequester {
		for _, sid := range j.SampleIDs {
			if sample := s.state.Samples[sid]; sample != nil && sample.RequesterID == c.user.ID {
				c.audit("read_journey_plan", "journey", j.ID, sid, true, nil)
				return 200, s.requesterJourneyPlanView(j), nil
			}
		}
		return 0, nil, apiErr(403, "forbidden", "not permitted to view this journey")
	}
	// workers: scoped view of their assigned legs
	involved := false
	for _, a := range s.state.Assignments {
		if a.JourneyID == j.ID && (a.AcceptedWorkerID == c.user.ID || a.OfferedToWorkerID == c.user.ID) {
			involved = true
			break
		}
	}
	if !involved {
		return 0, nil, apiErr(403, "forbidden", "not permitted to view this journey")
	}
	c.audit("read_journey_plan", "journey", j.ID, "", true, nil)
	return 200, s.workerJourneyPlanView(j, c.user.ID), nil
}

func (s *Service) hReadServiceabilitySnapshot(c *opCtx) (int, interface{}, *ApiError) {
	snap := s.state.Snapshot
	regions := []J{}
	for _, r := range snap.Regions {
		regions = append(regions, J{
			"locationId": r.LocationID, "name": r.Name,
			"latitude": r.Latitude, "longitude": r.Longitude, "coverageKm": r.CoverageKm,
		})
	}
	c.audit("read_serviceability_snapshot", "", "", "", true, nil)
	return 200, J{
		"version": snap.Version, "status": snap.Status, "computedAt": fmtTime(snap.ComputedAt),
		"networkRevision": snap.NetworkRevision, "regions": regions,
		"activeCollectionPointCount": snap.ActiveCollectionPointCount,
	}, nil
}

