   230		h := r.Header.Get("Authorization")
   231		if h == "" || !strings.HasPrefix(h, "Bearer ") {
   232			return nil, nil, apiErr(401, "unauthorized", "missing bearer [REDACTED]")
   233		}
   234		token := strings.TrimSpace(strings.TrimPrefix(h, "Bearer "))
   235		sess := s.state.Sessions[token]
   236		if sess == nil {
   237			return nil, nil, apiErr(401, "unauthorized", "invalid or expired token")
   238		}
   239		user := s.state.Users[sess.UserID]
   240		if user == nil || !user.Active {
   241			return nil, nil, apiErr(401, "unauthorized", "user is not active")
   242		}
   243		return user, sess, nil
