   269	// ---------- idempotency ----------
   270	
   271	func payloadHash(raw []byte) string {
   272		h := sha256.Sum256(raw)
   273		return hex.EncodeToString(h[:])
   274	}
   275	
   276	// runIdempotent wraps a mutating operation with idempotency-key handling.
   277	func (s *Service) runIdempotent(c *opCtx, op string, required bool, fn func() (int, interface{}, *ApiError)) (int, interface{}, *ApiError) {
   278		key, _ := optStr(c.body, "idempotencyKey")
   279		if key == "" {
   280			if required {
   281				return 0, nil, apiErr(400, "idempotency_required", "idempotencyKey is required for this operation")
   282			}
   283			return fn()
   284		}
   285		fullKey := op + ":" + c.user.ID + ":" + key
   286		if rec := s.state.Idempotency[fullKey]; rec != nil {
   287			if rec.PayloadHash != payloadHash(c.raw) {
   288				return 0, nil, apiErr(409, "idempotency_conflict", "idempotency key was already used with a different payload")
   289			}
   290			var stored interface{}
   291			if err := json.Unmarshal(rec.Response, &stored); err != nil {
   292				return 0, nil, apiErr(500, "internal_error", "failed to replay stored response")
   293			}
   294			return rec.StatusCode, stored, nil
   295		}
   296		status, resp, aerr := fn()
   297		if aerr != nil {
   298			return 0, nil, aerr
   299		}
   300		raw, err := json.Marshal(resp)
   301		if err != nil {
   302			return 0, nil, apiErr(500, "internal_error", "failed to encode response")
   303		}
   304		s.state.Idempotency[fullKey] = &IdemRecord{
   305			Key: key, Op: op, UserID: c.user.ID, PayloadHash: payloadHash(c.raw),
   306			StatusCode: status, Response: raw, CreatedAt: time.Now().UTC(),
   307		}
   308		return status, resp, nil
   309	}
