   369	// matchRoute matches a request path against a route pattern with {param}
   370	// segments. Returns the captured path parameter (single-param patterns).
   371	func matchRoute(pattern, path string) (string, bool) {
   372		pp := strings.Split(strings.Trim(pattern, "/"), "/")
   373		sp := strings.Split(strings.Trim(path, "/"), "/")
   374		if len(pp) != len(sp) {
   375			return "", false
   376		}
   377		param := ""
   378		for i := range pp {
   379			if strings.HasPrefix(pp[i], "{") && strings.HasSuffix(pp[i], "}") {
   380				param = sp[i]
   381				continue
   382			}
   383			if pp[i] != sp[i] {
   384				return "", false
   385			}
   386		}
   387		return param, true
   388	}
