   390	func (s *Service) ServeAPI(w http.ResponseWriter, r *http.Request) {
   391		path := r.URL.Path
   392		// WebSocket upgrades are handled outside the service lock
   393		if strings.ToLower(r.Header.Get("Upgrade")) == "websocket" {
   394			if path == "/api/events" {
   395				s.serveEventsWS(w, r)
   396			} else {
   397				writeErr(w, apiErr(404, "not_found", "resource not found"))
   398			}
   399			return
   400		}
   401		pathMatched := false
   402		for _, rt := range s.routes() {
   403			pathID, ok := matchRoute(rt.path, path)
   404			if !ok {
   405				continue
   406			}
   407			pathMatched = true
   408			if rt.method == r.Method {
   409				s.serveRoute(w, r, rt, pathID)
   410				return
   411			}
   412		}
   413		if pathMatched {
   414			writeErr(w, apiErr(405, "method_not_allowed", "method not allowed"))
   415			return
   416		}
   417		writeErr(w, apiErr(404, "not_found", "resource not found"))
   418	}
   419	
   420	func (s *Service) serveRoute(w http.ResponseWriter, r *http.Request, rt route, pathID string) {
   421		var user *User
   422		var sess *Session
   423		if rt.auth {
   424			s.mu.Lock()
   425			u, se, aerr := s.authenticate(r)
   426			s.mu.Unlock()
   427			if aerr != nil {
   428				writeErr(w, aerr)
   429				return
   430			}
   431			user, sess = u, se
   432		}
   433		var body J
   434		var raw []byte
   435		if r.Method == "POST" {
   436			var aerr *ApiError
   437			body, raw, aerr = decodeBody(r)
   438			if aerr != nil {
   439				s.mu.Lock()
   440				s.audit(userIDOf(user), roleOf(sess), opName(rt.path), "", "", "", false, map[string]interface{}{"error": aerr.Code})
   441				_ = s.persist()
   442				s.mu.Unlock()
   443				writeErr(w, aerr)
   444				return
   445			}
   446		}
   447		c := &opCtx{svc: s, r: r, user: user, sess: sess, body: body, raw: raw}
   448		if pathID != "" {
   449			c.body = J{}
   450			if body != nil {
   451				c.body = body
   452			}
   453			c.body["_pathId"] = pathID
   454		}
   455		s.mu.Lock()
   456		status, resp, aerr := rt.handler(c)
   457		if aerr == nil {
   458			if perr := s.persist(); perr != nil {
   459				s.mu.Unlock()
   460				writeErr(w, apiErr(500, "internal_error", "failed to persist state"))
   461				return
   462			}
   463		} else {
   464			// audit the failure, then persist audit only (state mutations from failed
   465			// ops are discarded by reloading? no — failed ops must not mutate state)
   466			s.pendingAudits = append(s.pendingAudits, &AuditRow{
   467				AuditID: newUUID(), ActorID: userIDOf(user), Role: roleOf(sess),
   468				Action: opName(rt.path), Success: false, OccurredAt: time.Now().UTC(),
   469				Details: []byte(fmt.Sprintf(`{"error":%q}`, aerr.Code)),
   470			})
   471			_ = s.persist()
   472		}
   473		s.mu.Unlock()
   474		if aerr != nil {
   475			writeErr(w, aerr)
   476			return
   477		}
   478		writeJSON(w, status, J{"data": resp})
   479	}
