package main

import (
	"sort"
	"time"
)

// ---------- role work ----------

func (s *Service) hListRoleWork(c *opCtx) (int, interface{}, *ApiError) {
	if c.sess.ActiveRole == "" {
		return 0, nil, apiErr(409, "role_not_selected", "select an active role before performing this action")
	}
	if err := checkFields(c.body, "role", "status"); err != nil {
		return 0, nil, err
	}
	role, aerr := optStr(c.body, "role")
	if aerr != nil {
		return 0, nil, aerr
	}
	if role == "" {
		role = c.sess.ActiveRole
	}
	if !validRole(role) {
		return 0, nil, apiErr(400, "invalid_role", "unknown role "+role)
	}
	if !c.user.HasRole(role) {
		return 0, nil, apiErr(403, "forbidden", "you do not hold this role")
	}
	statusFilter, aerr := optStr(c.body, "status")
	if aerr != nil {
		return 0, nil, aerr
	}
	pending := []J{}
	inProgress := []J{}
	completed := []J{}
	matchStatus := func(st string) bool {
		return statusFilter == "" || st == statusFilter
	}
	switch role {
	case RoleRequester:
		items := []*Sample{}
		for _, sample := range s.state.Samples {
			if sample.RequesterID == c.user.ID {
				items = append(items, sample)
			}
		}
		sort.Slice(items, func(i, j int) bool { return items[i].CreatedAt.Before(items[j].CreatedAt) })
		for _, sample := range items {
			if !matchStatus(sample.Status) {
				continue
			}
			v := s.sampleWorkItemView(sample)
			switch sample.Status {
			case SampleRequested:
				pending = append(pending, v)
			case SampleSealed, SampleInTransit, SampleAtNode, SampleException:
				inProgress = append(inProgress, v)
			default:
				completed = append(completed, v)
			}
		}
	case RoleDispatcher, RoleAdministrator:
		journeys := []*Journey{}
		for _, j := range s.state.Journeys {
			journeys = append(journeys, j)
		}
		sort.Slice(journeys, func(i, j int) bool { return journeys[i].CreatedAt.Before(journeys[j].CreatedAt) })
		for _, j := range journeys {
			if !matchStatus(j.Status) {
				continue
			}
			v := s.journeyWorkItemView(j)
			switch j.Status {
			case JourneyPlanned:
				pending = append(pending, v)
			case JourneyInProgress:
				inProgress = append(inProgress, v)
			default:
				completed = append(completed, v)
			}
		}
	default:
		// worker roles: assignments offered to or accepted by the user
		items := []*Assignment{}
		for _, a := range s.state.Assignments {
			if a.Kind != "" && kindRole(a.Kind) == role &&
				(a.OfferedToWorkerID == c.user.ID || a.AcceptedWorkerID == c.user.ID) {
				items = append(items, a)
			}
		}
		sort.Slice(items, func(i, j int) bool { return items[i].CreatedAt.Before(items[j].CreatedAt) })
		for _, a := range items {
			if !matchStatus(a.Status) {
				continue
			}
			v := s.assignmentWorkItemView(a)
			switch a.Status {
			case AsgOffered, AsgPending:
				pending = append(pending, v)
			case AsgAccepted, AsgInProgress:
				inProgress = append(inProgress, v)
			default:
				completed = append(completed, v)
			}
		}
	}
	c.audit("list_role_work", "", "", "", true, map[string]interface{}{"role": role})
	return 200, J{"pending": pending, "inProgress": inProgress, "completed": completed}, nil
}

// ---------- operations state ----------

func (s *Service) operationsStateView(sampleTypeFilter string) J {
	samples := []J{}
	for _, sample := range s.state.Samples {
		if sampleTypeFilter != "" && sample.SampleTypeID != sampleTypeFilter {
			continue
		}
		samples = append(samples, J{
			"sampleId": sample.ID, "sample_id": sample.ID,
			"requestId": sample.RequestID, "status": sample.Status,
			"origin": coordView(sample.Origin),
			"deliveryDeadline": fmtTime(sample.DeliveryDeadline),
			"activeJourneyId": strOrNil(sample.ActiveJourneyID),
			"currentHolderId": strOrNil(sample.CurrentHolderID),
			"latestLocation": coordViewPtr(sample.LatestLocation),
			"locationRecordedAt": fmtTimePtr(sample.LocationRecordedAt),
			"locationStale": s.locationStale(sample.LocationRecordedAt),
		})
	}
	sort.Slice(samples, func(i, j int) bool { return samples[i]["sampleId"].(string) < samples[j]["sampleId"].(string) })
	workers := []J{}
	spreadMin, spreadMax := -1, 0
	for _, u := range s.state.Users {
		isWorker := false
		for _, r := range u.Roles {
			if r == RoleCollectionPro || r == RoleDeliveryPartner || r == RoleNodeHandler || r == RoleLaboratoryTeam {
				isWorker = true
			}
		}
		if !isWorker {
			continue
		}
		active := s.activeAssignmentCount(u.ID)
		if spreadMin < 0 || active < spreadMin {
			spreadMin = active
		}
		if active > spreadMax {
			spreadMax = active
		}
		status := "unavailable"
		if u.Available {
			status = "available"
		}
		workers = append(workers, J{
			"workerId": u.ID, "worker_id": u.ID,
			"fullName": u.FullName, "roles": u.Roles,
			"available": u.Available, "status": status,
			"capacityUnits": u.CapacityUnits,
			"assignmentCount": active,
			"latestLocation": coordViewPtr(u.LatestLocation), "latest_location": coordViewPtr(u.LatestLocation),
			"locationRecordedAt": fmtTimePtr(u.LocationRecordedAt),
			"locationStale": s.locationStale(u.LocationRecordedAt),
		})
	}
	sort.Slice(workers, func(i, j int) bool { return workers[i]["workerId"].(string) < workers[j]["workerId"].(string) })
	spread := 0
	if spreadMin >= 0 {
		spread = spreadMax - spreadMin
	}
	locations := []J{}
	for _, loc := range s.state.Locations {
		if loc.Implicit {
			continue
		}
		locations = append(locations, operationsLocationView(loc))
	}
	sort.Slice(locations, func(i, j int) bool { return locations[i]["locationId"].(string) < locations[j]["locationId"].(string) })
	connections := []J{}
	for _, conn := range s.state.Connections {
		connections = append(connections, connectionView(conn))
	}
	sort.Slice(connections, func(i, j int) bool { return connections[i]["connectionId"].(string) < connections[j]["connectionId"].(string) })
	routes := []J{}
	for _, j := range s.state.Journeys {
		sampleIDs := j.SampleIDs
		if sampleIDs == nil {
			sampleIDs = []string{}
		}
		routes = append(routes, J{
			"journeyId": j.ID, "status": j.Status, "routeMode": j.RouteMode,
			"planVersion": j.PlanVersion, "sampleIds": sampleIDs,
			"estimatedDeliveryAt": fmtTime(j.EstimatedDeliveryAt),
			"totalCostUnits": j.TotalCostUnits, "replanStatus": j.ReplanStatus,
		})
	}
	handoffs := []J{}
	for _, h := range s.state.Handoffs {
		handoffs = append(handoffs, s.handoffView(h))
	}
	delays := []J{}
	for _, j := range s.state.Journeys {
		if j.Status != JourneyPlanned && j.Status != JourneyInProgress {
			continue
		}
		for _, sid := range j.SampleIDs {
			if sample := s.state.Samples[sid]; sample != nil && j.EstimatedDeliveryAt.After(sample.DeliveryDeadline) {
				delays = append(delays, J{
					"journeyId": j.ID, "sampleId": sid,
					"estimatedDeliveryAt": fmtTime(j.EstimatedDeliveryAt),
					"deliveryDeadline": fmtTime(sample.DeliveryDeadline),
				})
			}
		}
	}
	exceptions := []J{}
	for _, sample := range s.state.Samples {
		if sample.Status == SampleException || sample.Status == SampleExpired {
			code, reason := "", ""
			if sample.Exception != nil {
				code = sample.Exception.Code
				reason = sample.Exception.Reason
			}
			exceptions = append(exceptions, J{
				"sampleId": sample.ID, "status": sample.Status, "code": code, "reason": reason,
			})
		}
	}
	ineligible := 0
	for _, a := range s.state.Assignments {
		if a.Status == AsgPending && len(s.eligibleWorkers(a, false)) == 0 {
			ineligible++
		}
	}
	return J{
		"samples": samples, "workers": workers, "locations": locations,
		"connections": connections, "routes": routes, "handoffs": handoffs,
		"delays": delays, "exceptions": exceptions,
		"assignmentCountSpread": spread, "ineligibleAssignmentCount": ineligible,
	}
}

func (s *Service) hReadOperationsState(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleDispatcher, RoleAdministrator, RoleNodeHandler, RoleLaboratoryTeam); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "filters"); err != nil {
		return 0, nil, err
	}
	typeFilter := ""
	if v, ok := c.body["filters"]; ok && v != nil {
		fm, ok := v.(map[string]interface{})
		if !ok {
			return 0, nil, apiErr(400, "invalid_json", "filters must be an object")
		}
		for k := range fm {
			if k != "sampleTypeId" {
				return 0, nil, apiErr(400, "invalid_json", "unknown filter "+k)
			}
		}
		if s2, ok := fm["sampleTypeId"].(string); ok {
			typeFilter = s2
		}
	}
	c.audit("read_operations_state", "", "", "", true, nil)
	return 200, s.operationsStateView(typeFilter), nil
}

// ---------- journey management ----------

func (s *Service) checkPlanVersion(j *Journey, body J) *ApiError {
	v, ok := body["expectedPlanVersion"]
	if !ok || v == nil {
		return apiErr(400, "invalid_plan_version", "expectedPlanVersion is required")
	}
	n, ok := v.(float64)
	if !ok || n != float64(int(n)) || int(n) < 1 {
		return apiErr(400, "invalid_plan_version", "expectedPlanVersion must be a positive integer")
	}
	if int(n) != j.PlanVersion {
		return apiErr(409, "stale_plan", "the journey plan has changed; reload and retry")
	}
	return nil
}

func (s *Service) hCancelJourney(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleDispatcher, RoleAdministrator); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "journeyId", "expectedPlanVersion", "reason", "idempotencyKey"); err != nil {
		return 0, nil, err
	}
	return s.runIdempotent(c, "cancel_journey", true, func() (int, interface{}, *ApiError) {
		journeyID, err := reqStr(c.body, "journeyId")
		if err != nil {
			return 0, nil, err
		}
		reason, _ := optStr(c.body, "reason")
		j := s.state.Journeys[journeyID]
		if j == nil {
			return 0, nil, apiErr(404, "not_found", "journey not found")
		}
		if aerr := s.checkPlanVersion(j, c.body); aerr != nil {
			return 0, nil, aerr
		}
		if j.Status == JourneyCancelled || j.Status == JourneyCompleted {
			return 0, nil, apiErr(409, "inactive_plan", "journey is already finished")
		}
		s.cancelUnfinishedAssignments(j, "journey_cancelled")
		j.Status = JourneyCancelled
		j.CancellationReason = reason
		j.PlanVersion++
		sampleIDs := j.SampleIDs
		for _, sid := range j.SampleIDs {
			if sample := s.state.Samples[sid]; sample != nil &&
				sample.Status != SampleReceived && sample.Status != SampleExpired {
				sample.Status = SampleCancelled
				c.audit("cancel_journey", "sample", sid, sid, true, map[string]interface{}{"journeyId": j.ID})
			}
		}
		c.audit("cancel_journey", "journey", j.ID, "", true, map[string]interface{}{"reason": reason})
		s.emit("journey.cancelled", "journey", j.ID, map[string]interface{}{"journeyId": j.ID})
		if sampleIDs == nil {
			sampleIDs = []string{}
		}
		return 201, J{"journeyId": j.ID, "status": "cancelled", "sampleIds": sampleIDs}, nil
	})
}

func (s *Service) hSplitJourney(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleDispatcher, RoleAdministrator); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "journeyId", "expectedPlanVersion", "sampleIds", "idempotencyKey"); err != nil {
		return 0, nil, err
	}
	return s.runIdempotent(c, "split_journey", true, func() (int, interface{}, *ApiError) {
		journeyID, err := reqStr(c.body, "journeyId")
		if err != nil {
			return 0, nil, err
		}
		sampleIDs, err := optStrList(c.body, "sampleIds")
		if err != nil {
			return 0, nil, err
		}
		if len(sampleIDs) == 0 {
			return 0, nil, apiErr(400, "invalid_json", "sampleIds must be a non-empty array")
		}
		j := s.state.Journeys[journeyID]
		if j == nil {
			return 0, nil, apiErr(404, "not_found", "journey not found")
		}
		if aerr := s.checkPlanVersion(j, c.body); aerr != nil {
			return 0, nil, aerr
		}
		if j.Status != JourneyPlanned && j.Status != JourneyInProgress {
			return 0, nil, apiErr(409, "inactive_plan", "journey is not active")
		}
		if len(j.SampleIDs) < 2 {
			return 0, nil, apiErr(409, "invalid_split", "journey contains a single sample")
		}
		for _, sid := range sampleIDs {
			if !containsString(j.SampleIDs, sid) {
				return 0, nil, apiErr(409, "invalid_split", "sample is not part of this journey")
			}
			if sample := s.state.Samples[sid]; sample != nil && sample.Status == SampleReceived {
				return 0, nil, apiErr(409, "completed_work_immutable", "completed samples cannot be split")
			}
		}
		if len(sampleIDs) == len(j.SampleIDs) {
			return 0, nil, apiErr(409, "invalid_split", "cannot split all samples out of a journey")
		}
		// perform split: first listed sample gets a fresh journey from its position
		splitSampleID := sampleIDs[0]
		sample := s.state.Samples[splitSampleID]
		remaining := []string{}
		for _, sid := range j.SampleIDs {
			if sid != splitSampleID {
				remaining = append(remaining, sid)
			}
		}
		j.SampleIDs = remaining
		j.PlanVersion++
		if len(remaining) == 1 && j.RouteMode == "batched" {
			if len(j.LegIDs) <= 1 {
				j.RouteMode = "direct"
			} else {
				j.RouteMode = "multi_stop"
			}
		}
		// build new journey for the split sample from its current position
		nj, status := s.replanSample(sample, "split")
		if nj == nil {
			// rollback sample list change
			j.SampleIDs = append(j.SampleIDs, splitSampleID)
			j.PlanVersion--
			if status == ReplanExpired {
				return 0, nil, apiErr(409, "deadline_exceeded", "no valid route can meet the sample deadline")
			}
			return 0, nil, apiErr(409, "no_valid_route", "no valid route for the split sample")
		}
		nj.ParentJourneyID = j.ID
		j.SplitJourneyID = nj.ID
		c.audit("split_journey", "journey", j.ID, splitSampleID, true, map[string]interface{}{
			"splitJourneyId": nj.ID, "sampleIds": sampleIDs,
		})
		s.emit("journey.split", "journey", j.ID, map[string]interface{}{
			"journeyId": j.ID, "splitJourneyId": nj.ID,
		})
		return 201, J{"journey": s.journeyPlanView(j, 2), "splitJourney": s.journeyPlanView(nj, 2)}, nil
	})
}

func samplesCompatible(s *Service, samples []*Sample) (string, bool) {
	for i, a := range samples {
		ta := s.state.SampleTypes[a.SampleTypeID]
		if ta != nil && !ta.BatchingAllowed {
			return "pulse_no_batch", false
		}
		for _, b := range samples[i+1:] {
			tb := s.state.SampleTypes[b.SampleTypeID]
			if containsString(a.IncompatibleSampleTypes, b.SampleTypeID) ||
				containsString(b.IncompatibleSampleTypes, a.SampleTypeID) {
				return "incompatible_batch", false
			}
			if ta != nil && containsString(ta.IncompatibleSampleTypes, b.SampleTypeID) {
				return "incompatible_batch", false
			}
			if tb != nil && containsString(tb.IncompatibleSampleTypes, a.SampleTypeID) {
				return "incompatible_batch", false
			}
			if a.ContainerType != b.ContainerType {
				return "incompatible_batch", false
			}
		}
	}
	return "", true
}

func (s *Service) hMergeJourneys(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleDispatcher, RoleAdministrator); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "targetJourneyId", "expectedPlanVersion", "sourceJourneyIds", "idempotencyKey"); err != nil {
		return 0, nil, err
	}
	return s.runIdempotent(c, "merge_journeys", true, func() (int, interface{}, *ApiError) {
		targetID, err := reqStr(c.body, "targetJourneyId")
		if err != nil {
			return 0, nil, err
		}
		sourceIDs, err := optStrList(c.body, "sourceJourneyIds")
		if err != nil {
			return 0, nil, err
		}
		if len(sourceIDs) == 0 {
			return 0, nil, apiErr(400, "invalid_json", "sourceJourneyIds must be a non-empty array")
		}
		target := s.state.Journeys[targetID]
		if target == nil {
			return 0, nil, apiErr(404, "not_found", "target journey not found")
		}
		if aerr := s.checkPlanVersion(target, c.body); aerr != nil {
			return 0, nil, aerr
		}
		if target.Status != JourneyPlanned && target.Status != JourneyInProgress {
			return 0, nil, apiErr(409, "inactive_plan", "target journey is not active")
		}
		sources := []*Journey{}
		for _, sid := range sourceIDs {
			sj := s.state.Journeys[sid]
			if sj == nil {
				return 0, nil, apiErr(404, "not_found", "source journey not found")
			}
			if sj.ID == target.ID {
				return 0, nil, apiErr(409, "invalid_merge", "cannot merge a journey into itself")
			}
			if sj.Status != JourneyPlanned && sj.Status != JourneyInProgress {
				return 0, nil, apiErr(409, "inactive_plan", "source journey is not active")
			}
			sources = append(sources, sj)
		}
		// no journey may have started executing (completed legs or custody transfers)
		allJourneys := append([]*Journey{target}, sources...)
		allSamples := []*Sample{}
		for _, j := range allJourneys {
			for _, sid := range j.SampleIDs {
				sample := s.state.Samples[sid]
				if sample == nil {
					continue
				}
				if sample.Status == SampleReceived {
					return 0, nil, apiErr(409, "completed_work_immutable", "completed samples cannot be merged")
				}
				if len(sample.CompletedLegIDs) > 0 {
					return 0, nil, apiErr(409, "partial_journey_merge", "journeys with completed legs cannot be merged")
				}
				allSamples = append(allSamples, sample)
			}
		}
		if code, ok := samplesCompatible(s, allSamples); !ok {
			return 0, nil, apiErr(409, code, "samples are not allowed to travel together")
		}
		// routes must share the same target laboratory and entry node
		targetLab := ""
		targetEntry := ""
		if len(target.Stops) > 0 {
			targetLab = target.Stops[len(target.Stops)-1].LocationID
			for _, st := range target.Stops {
				if st.StopType == "handoff" {
					targetEntry = st.LocationID
					break
				}
			}
			if targetEntry == "" {
				targetEntry = target.Stops[0].LocationID
			}
		}
		for _, sj := range sources {
			if len(sj.Stops) == 0 {
				return 0, nil, apiErr(409, "invalid_merge", "source journey has no route")
			}
			lab := sj.Stops[len(sj.Stops)-1].LocationID
			if lab != targetLab {
				return 0, nil, apiErr(409, "invalid_merge", "journeys target different laboratories")
			}
			entry := ""
			for _, st := range sj.Stops {
				if st.StopType == "handoff" {
					entry = st.LocationID
					break
				}
			}
			if entry == "" {
				entry = sj.Stops[0].LocationID
			}
			if entry != targetEntry {
				return 0, nil, apiErr(409, "invalid_merge", "journeys follow different routes")
			}
		}
		// capacity check: every added sample reserves along the target route
		type reserveTarget struct {
			pool   *CapacityPool
			cooled bool
		}
		toReserve := []reserveTarget{}
		for _, sj := range sources {
			for _, sid := range sj.SampleIDs {
				sample := s.state.Samples[sid]
				cooled := sampleRequiresCooled(s, sample)
				for _, legID := range target.LegIDs {
					if a := s.state.Assignments[legID]; a != nil && a.ConnectionID != "" {
						if conn := s.state.Connections[a.ConnectionID]; conn != nil {
							toReserve = append(toReserve, reserveTarget{&conn.Capacity, cooled})
						}
					}
				}
				for _, id := range target.NodeAssignmentIDs {
					if a := s.state.Assignments[id]; a != nil {
						if loc := s.state.Locations[a.NodeID]; loc != nil {
							toReserve = append(toReserve, reserveTarget{&loc.Capacity, cooled})
						}
					}
				}
				for _, id := range target.LaboratoryAssignmentIDs {
					if a := s.state.Assignments[id]; a != nil {
						if loc := s.state.Locations[a.LaboratoryID]; loc != nil {
							toReserve = append(toReserve, reserveTarget{&loc.Capacity, cooled})
						}
					}
				}
			}
		}
		for _, rt := range toReserve {
			if rt.pool.Available(rt.cooled) < 1 {
				code := "capacity_exhausted"
				if rt.cooled {
					code = "cooled_capacity_exhausted"
				}
				return 0, nil, apiErr(409, code, "not enough capacity on the shared route")
			}
		}
		// deadline check: arrival must still meet every sample deadline
		for _, sj := range sources {
			for _, sid := range sj.SampleIDs {
				if sample := s.state.Samples[sid]; sample != nil && target.EstimatedDeliveryAt.After(sample.DeliveryDeadline) {
					return 0, nil, apiErr(409, "deadline_exceeded", "merged journey cannot meet every sample deadline")
				}
			}
		}
		for _, rt := range toReserve {
			rt.pool.Reserve(rt.cooled)
		}
		// move samples & collection assignments into target
		for _, sj := range sources {
			for _, sid := range sj.SampleIDs {
				sample := s.state.Samples[sid]
				target.SampleIDs = append(target.SampleIDs, sid)
				if sample != nil {
					sample.ActiveJourneyID = target.ID
					sample.TargetLaboratoryID = targetLab
				}
			}
			for _, id := range sj.CollectionAssignmentIDs {
				if a := s.state.Assignments[id]; a != nil && a.Status != AsgCancelled {
					a.JourneyID = target.ID
					target.CollectionAssignmentIDs = append(target.CollectionAssignmentIDs, id)
				}
			}
			// release source-only reservations and cancel source assignments
			s.cancelUnfinishedAssignments(sj, "merged")
			sj.Status = JourneyMerged
			sj.ReplanStatus = ReplanReplaced
			c.audit("merge_journeys", "journey", sj.ID, "", true, map[string]interface{}{"targetJourneyId": target.ID})
		}
		if len(target.SampleIDs) > 1 {
			target.RouteMode = "batched"
		}
		target.PlanVersion++
		c.audit("merge_journeys", "journey", target.ID, "", true, map[string]interface{}{
			"sourceJourneyIds": sourceIDs,
		})
		s.emit("journey.merged", "journey", target.ID, map[string]interface{}{
			"journeyId": target.ID, "sourceJourneyIds": sourceIDs,
		})
		return 201, s.journeyPlanView(target, 2), nil
	})
}

func (s *Service) hRerouteJourney(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleDispatcher, RoleAdministrator); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "journeyId", "expectedPlanVersion", "reason", "idempotencyKey"); err != nil {
		return 0, nil, err
	}
	return s.runIdempotent(c, "reroute_journey", true, func() (int, interface{}, *ApiError) {
		journeyID, err := reqStr(c.body, "journeyId")
		if err != nil {
			return 0, nil, err
		}
		j := s.state.Journeys[journeyID]
		if j == nil {
			return 0, nil, apiErr(404, "not_found", "journey not found")
		}
		if aerr := s.checkPlanVersion(j, c.body); aerr != nil {
			return 0, nil, aerr
		}
		if j.Status != JourneyPlanned && j.Status != JourneyInProgress {
			return 0, nil, apiErr(409, "inactive_plan", "journey is already finished")
		}
		if len(j.SampleIDs) > 1 {
			return 0, nil, apiErr(409, "invalid_split", "reroute supports single-sample journeys; split first")
		}
		sample := s.state.Samples[j.SampleIDs[0]]
		if sample == nil {
			return 0, nil, apiErr(404, "not_found", "sample not found")
		}
		nj, status := s.replanSample(sample, "dispatcher_reroute")
		j.PlanVersion++
		c.audit("reroute_journey", "journey", j.ID, sample.ID, true, map[string]interface{}{
			"replanStatus": status,
		})
		resp := J{
			"journeyId": j.ID, "replanStatus": status,
			"replacementPlanId": nil, "replacementJourney": nil,
		}
		if nj != nil {
			resp["replacementPlanId"] = nj.ID
			resp["replacementJourney"] = s.journeyPlanView(nj, 2)
		}
		return 201, resp, nil
	})
}

func (s *Service) hEditActivePlan(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleDispatcher, RoleAdministrator); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "journeyId", "expectedPlanVersion", "changeType", "changes", "idempotencyKey"); err != nil {
		return 0, nil, err
	}
	return s.runIdempotent(c, "edit_active_plan", true, func() (int, interface{}, *ApiError) {
		journeyID, err := reqStr(c.body, "journeyId")
		if err != nil {
			return 0, nil, err
		}
		changeType, err := reqStr(c.body, "changeType")
		if err != nil {
			return 0, nil, err
		}
		validChanges := map[string]bool{
			"add_stop": true, "remove_stop": true, "reorder_stops": true,
			"replace_worker": true, "reassign_worker": true,
			"merge_samples": true, "split_samples": true, "split_batch": true,
			"cancel_work": true, "reroute": true, "replace_route": true,
		}
		if !validChanges[changeType] {
			return 0, nil, apiErr(400, "invalid_change_type", "unknown changeType")
		}
		j := s.state.Journeys[journeyID]
		if j == nil {
			return 0, nil, apiErr(404, "not_found", "journey not found")
		}
		if aerr := s.checkPlanVersion(j, c.body); aerr != nil {
			return 0, nil, aerr
		}
		if j.Status != JourneyPlanned && j.Status != JourneyInProgress {
			return 0, nil, apiErr(409, "inactive_plan", "journey is not active")
		}
		changes, _ := c.body["changes"].(map[string]interface{})
		if changes == nil {
			changes = map[string]interface{}{}
		}
		var aerr *ApiError
		switch changeType {
		case "replace_worker", "reassign_worker":
			aerr = s.editReplaceWorker(c, j, changes)
		case "cancel_work":
			s.cancelUnfinishedAssignments(j, "edit_cancel_work")
			j.Status = JourneyCancelled
			j.PlanVersion++
			for _, sid := range j.SampleIDs {
				if sample := s.state.Samples[sid]; sample != nil && sample.Status != SampleReceived {
					sample.Status = SampleCancelled
				}
			}
		case "reroute", "replace_route":
			if len(j.SampleIDs) != 1 {
				aerr = apiErr(409, "invalid_transition", "reroute supports single-sample journeys; split first")
			} else {
				sample := s.state.Samples[j.SampleIDs[0]]
				nj, status := s.replanSample(sample, "edit_reroute")
				if nj == nil {
					if status == ReplanExpired {
						aerr = apiErr(409, "deadline_exceeded", "no valid route can meet the sample deadline")
					} else {
						aerr = apiErr(409, "no_valid_route", "no valid route available")
					}
				} else {
					j.PlanVersion++
				}
			}
		case "add_stop":
			aerr = s.editAddStop(c, j, changes)
		case "remove_stop":
			aerr = s.editRemoveStop(c, j, changes)
		case "reorder_stops":
			aerr = apiErr(409, "invalid_stop_order", "reordering stops is not supported for this journey state")
		case "split_samples", "split_batch":
			aerr = apiErr(409, "invalid_split", "use split-journey to split samples from this journey")
		case "merge_samples":
			aerr = apiErr(409, "invalid_merge", "use merge-journeys to combine journeys")
		}
		if aerr != nil {
			return 0, nil, aerr
		}
		c.audit("edit_active_plan", "journey", j.ID, "", true, map[string]interface{}{"changeType": changeType})
		s.emit("journey.edited", "journey", j.ID, map[string]interface{}{
			"journeyId": j.ID, "changeType": changeType,
		})
		return 201, s.journeyPlanView(j, 2), nil
	})
}

func (s *Service) editReplaceWorker(c *opCtx, j *Journey, changes map[string]interface{}) *ApiError {
	asgID, _ := changes["assignmentId"].(string)
	workerID, _ := changes["workerId"].(string)
	if asgID == "" || workerID == "" {
		return apiErr(400, "invalid_json", "changes.assignmentId and changes.workerId are required")
	}
	a := s.state.Assignments[asgID]
	if a == nil || a.JourneyID != j.ID {
		return apiErr(404, "not_found", "assignment not found in this journey")
	}
	if a.Status == AsgCompleted || a.Status == AsgCancelled {
		return apiErr(409, "completed_work_immutable", "cannot change a completed assignment")
	}
	worker := s.state.Users[workerID]
	if worker == nil {
		return apiErr(400, "invalid_worker", "worker not found")
	}
	if !worker.Active || !worker.HasRole(kindRole(a.Kind)) {
		return apiErr(400, "invalid_worker", "worker cannot perform this assignment")
	}
	eligible := false
	for _, u := range s.eligibleWorkers(a, false) {
		if u.ID == workerID {
			eligible = true
		}
	}
	if !eligible {
		return apiErr(409, "ineligible_worker", "worker is not eligible for this assignment")
	}
	now := time.Now().UTC()
	a.Status = AsgOffered
	a.OfferedToWorkerID = workerID
	a.AcceptedWorkerID = ""
	a.OfferedAt = &now
	exp := now.Add(offerTimeoutSeconds * time.Second)
	a.OfferExpiresAt = &exp
	j.PlanVersion++
	s.audit(c.user.ID, c.sess.ActiveRole, "assignment.offered", "assignment", a.ID, a.SampleID, true, map[string]interface{}{
		"workerId": workerID, "kind": a.Kind, "reassigned": true,
	})
	return nil
}

func (s *Service) editAddStop(c *opCtx, j *Journey, changes map[string]interface{}) *ApiError {
	locID, _ := changes["locationId"].(string)
	if locID == "" {
		return apiErr(400, "invalid_json", "changes.locationId is required")
	}
	loc := s.state.Locations[locID]
	if loc == nil || loc.Implicit {
		return apiErr(404, "not_found", "location not found")
	}
	if !loc.Active {
		return apiErr(409, "location_inactive", "location is not active")
	}
	if len(j.SampleIDs) != 1 {
		return apiErr(409, "invalid_transition", "add_stop supports single-sample journeys")
	}
	sample := s.state.Samples[j.SampleIDs[0]]
	// rebuild remaining route through the new stop: find route from current
	// position to the new stop, then from the new stop onward
	posNodeID := s.samplePositionNode(sample)
	posLoc := s.state.Locations[posNodeID]
	if posLoc == nil || posLoc.Implicit {
		return apiErr(409, "no_valid_route", "cannot determine current sample position")
	}
	sampleType := s.state.SampleTypes[sample.SampleTypeID]
	leg1 := s.findRoute([]string{posLoc.ID}, sampleType, true)
	_ = leg1
	// route position -> new stop -> lab
	dist1, _ := s.dijkstra(posLoc.ID, sampleType.RequiresCooledRoute, true, sampleType.RequiresCooledRoute)
	if _, ok := dist1[locID]; !ok {
		return apiErr(409, "no_valid_route", "no route from the current position to the new stop")
	}
	dist2, _ := s.dijkstra(locID, sampleType.RequiresCooledRoute, true, sampleType.RequiresCooledRoute)
	labOK := false
	for _, loc2 := range s.state.Locations {
		if !loc2.Implicit && loc2.Active && loc2.HasFunction(LocLaboratory) && s.labAccepts(loc2, sample.SampleTypeID) {
			if _, ok := dist2[loc2.ID]; ok {
				labOK = true
			}
		}
	}
	if !labOK {
		return apiErr(409, "no_valid_route", "no route from the new stop to an accepting laboratory")
	}
	// materialize: cancel unfinished work and rebuild through the stop
	s.cancelUnfinishedAssignments(j, "add_stop")
	oldStops := j.Stops
	j.Stops = nil
	j.LegIDs = nil
	j.NodeAssignmentIDs = nil
	j.LaboratoryAssignmentIDs = nil
	// keep completed stops
	maxSeq := 0
	for _, st := range oldStops {
		if st.CompletedAt != nil {
			j.Stops = append(j.Stops, st)
			if st.Sequence > maxSeq {
				maxSeq = st.Sequence
			}
		}
	}
	// simple two-segment rebuild: position -> newStop -> best lab
	plan1 := s.findRoute([]string{posLoc.ID}, sampleType, true)
	if plan1 == nil {
		return apiErr(409, "no_valid_route", "no route from current position")
	}
	// force route through new stop: build segments manually
	seg1 := s.buildSegment(j, sample, posLoc.ID, locID, sampleType)
	if seg1 == nil {
		return apiErr(409, "no_valid_route", "no route from current position to the new stop")
	}
	labPlan := s.findRoute([]string{locID}, sampleType, true)
	if labPlan == nil {
		return apiErr(409, "no_valid_route", "no route from the new stop to a laboratory")
	}
	now := time.Now().UTC()
	t := now
	seq := maxSeq
	fromID := posLoc.ID
	for _, connID := range seg1.ConnPath {
		conn := s.state.Connections[connID]
		next := conn.ToLocationID
		if conn.FromLocationID != fromID {
			next = conn.FromLocationID
		}
		t = t.Add(time.Duration(conn.TravelMinutes) * time.Minute)
		seq++
		isLast := next == locID
		stopType := "handoff"
		if isLast {
			stopType = "handoff"
		}
		nextLoc := s.state.Locations[next]
		j.Stops = append(j.Stops, &Stop{
			ID: newUUID(), LocationID: next, StopType: stopType, Sequence: seq,
			EstimatedAt: t, DwellMinutes: nextLoc.HandlingMinutes, Coordinate: nextLoc.Coordinate,
		})
		leg := s.newTransportAssignment(j, sample, len(j.LegIDs)+1, fromID, next, connID)
		j.LegIDs = append(j.LegIDs, leg.ID)
		conn.Capacity.Reserve(sampleRequiresCooled(s, sample))
		nodeAsg := s.newNodeAssignment(j, sample, next)
		j.NodeAssignmentIDs = append(j.NodeAssignmentIDs, nodeAsg.ID)
		nextLoc.Capacity.Reserve(sampleRequiresCooled(s, sample))
		t = t.Add(time.Duration(nextLoc.HandlingMinutes) * time.Minute)
		fromID = next
	}
	for _, connID := range labPlan.ConnPath {
		conn := s.state.Connections[connID]
		next := conn.ToLocationID
		if conn.FromLocationID != fromID {
			next = conn.FromLocationID
		}
		t = t.Add(time.Duration(conn.TravelMinutes) * time.Minute)
		seq++
		nextLoc := s.state.Locations[next]
		isLab := next == labPlan.LabID
		stopType := "handoff"
		dwell := nextLoc.HandlingMinutes
		if isLab {
			stopType = "delivery"
			dwell = 0
		}
		j.Stops = append(j.Stops, &Stop{
			ID: newUUID(), LocationID: next, StopType: stopType, Sequence: seq,
			EstimatedAt: t, DwellMinutes: dwell, Coordinate: nextLoc.Coordinate,
		})
		leg := s.newTransportAssignment(j, sample, len(j.LegIDs)+1, fromID, next, connID)
		j.LegIDs = append(j.LegIDs, leg.ID)
		conn.Capacity.Reserve(sampleRequiresCooled(s, sample))
		if !isLab {
			nodeAsg := s.newNodeAssignment(j, sample, next)
			j.NodeAssignmentIDs = append(j.NodeAssignmentIDs, nodeAsg.ID)
			nextLoc.Capacity.Reserve(sampleRequiresCooled(s, sample))
			t = t.Add(time.Duration(nextLoc.HandlingMinutes) * time.Minute)
		}
		fromID = next
	}
	if labPlan.EntryID == labPlan.LabID && fromID == labPlan.LabID {
		seq++
		labLoc := s.state.Locations[labPlan.LabID]
		j.Stops = append(j.Stops, &Stop{
			ID: newUUID(), LocationID: labPlan.LabID, StopType: "delivery", Sequence: seq,
			EstimatedAt: t, DwellMinutes: 0, Coordinate: labLoc.Coordinate,
		})
	}
	labAsg := s.newLaboratoryAssignment(j, sample, labPlan.LabID)
	j.LaboratoryAssignmentIDs = append(j.LaboratoryAssignmentIDs, labAsg.ID)
	lab := s.state.Locations[labPlan.LabID]
	lab.Capacity.Reserve(sampleRequiresCooled(s, sample))
	if t.After(sample.DeliveryDeadline) {
		return apiErr(409, "deadline_exceeded", "the new route cannot meet the sample deadline")
	}
	j.EstimatedDeliveryAt = t
	sample.TargetLaboratoryID = labPlan.LabID
	j.PlanVersion++
	for _, id := range j.LegIDs {
		s.offerAssignment(s.state.Assignments[id])
	}
	for _, id := range j.NodeAssignmentIDs {
		s.offerAssignment(s.state.Assignments[id])
	}
	for _, id := range j.LaboratoryAssignmentIDs {
		s.offerAssignment(s.state.Assignments[id])
	}
	return nil
}

func (s *Service) buildSegment(j *Journey, sample *Sample, fromID, toID string, sampleType *SampleType) *routePlan {
	dist, prev := s.dijkstra(fromID, sampleType.RequiresCooledRoute, true, sampleType.RequiresCooledRoute)
	if _, ok := dist[toID]; !ok {
		return nil
	}
	conns := []string{}
	cur := toID
	for cur != fromID {
		connID, ok := prev[cur]
		if !ok {
			return nil
		}
		conns = append([]string{connID}, conns...)
		conn := s.state.Connections[connID]
		if conn.FromLocationID == cur {
			cur = conn.ToLocationID
		} else {
			cur = conn.FromLocationID
		}
	}
	return &routePlan{EntryID: fromID, LabID: toID, ConnPath: conns, TravelMinutes: dist[toID]}
}

func (s *Service) editRemoveStop(c *opCtx, j *Journey, changes map[string]interface{}) *ApiError {
	stopID, _ := changes["stopId"].(string)
	if stopID == "" {
		return apiErr(400, "invalid_json", "changes.stopId is required")
	}
	var target *Stop
	for _, st := range j.Stops {
		if st.ID == stopID {
			target = st
		}
	}
	if target == nil {
		return apiErr(404, "not_found", "stop not found in this journey")
	}
	if target.CompletedAt != nil {
		return apiErr(409, "completed_work_immutable", "cannot remove a completed stop")
	}
	if target.StopType != "handoff" {
		return apiErr(409, "invalid_stop_order", "only unfinished handoff stops can be removed")
	}
	// verify a connection exists between the neighbouring stops
	var prevStop, nextStop *Stop
	for _, st := range j.Stops {
		if st.Sequence < target.Sequence && (prevStop == nil || st.Sequence > prevStop.Sequence) {
			prevStop = st
		}
		if st.Sequence > target.Sequence && (nextStop == nil || st.Sequence < nextStop.Sequence) {
			nextStop = st
		}
	}
	if prevStop == nil || nextStop == nil {
		return apiErr(409, "invalid_stop_order", "cannot remove this stop")
	}
	found := false
	for _, conn := range s.state.Connections {
		if !conn.Active {
			continue
		}
		if (conn.FromLocationID == prevStop.LocationID && conn.ToLocationID == nextStop.LocationID) ||
			(conn.FromLocationID == nextStop.LocationID && conn.ToLocationID == prevStop.LocationID) {
			found = true
		}
	}
	if !found {
		return apiErr(409, "no_valid_route", "no connection between the neighbouring stops")
	}
	// remove stop and its node assignment; rebuild the connecting leg
	newStops := []*Stop{}
	for _, st := range j.Stops {
		if st.ID != stopID {
			newStops = append(newStops, st)
		}
	}
	j.Stops = newStops
	for _, id := range j.NodeAssignmentIDs {
		if a := s.state.Assignments[id]; a != nil && a.NodeID == target.LocationID && a.Status != AsgCompleted {
			a.Status = AsgCancelled
			if sample := s.state.Samples[j.SampleIDs[0]]; sample != nil {
				if loc := s.state.Locations[a.NodeID]; loc != nil {
					loc.Capacity.Release(sampleRequiresCooled(s, sample))
				}
			}
		}
	}
	j.PlanVersion++
	return nil
}

// ---------- disruption ----------

func (s *Service) hReportDisruption(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleDispatcher, RoleAdministrator); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "resourceType", "resourceId", "reason", "occurredAt", "idempotencyKey"); err != nil {
		return 0, nil, err
	}
	return s.runIdempotent(c, "report_disruption", true, func() (int, interface{}, *ApiError) {
		resourceType, err := reqStr(c.body, "resourceType")
		if err != nil {
			return 0, nil, err
		}
		validTypes := map[string]bool{
			"worker": true, "node": true, "location": true, "connection": true,
			"route": true, "laboratory": true, "capacity": true,
		}
		if !validTypes[resourceType] {
			return 0, nil, apiErr(400, "invalid_resource_type", "unknown resourceType")
		}
		resourceID, err := reqStr(c.body, "resourceId")
		if err != nil {
			return 0, nil, err
		}
		reason, _ := optStr(c.body, "reason")
		occurredAt, aerr := optTimeField(c.body, "occurredAt")
		if aerr != nil {
			return 0, nil, aerr
		}
		// apply the disruption
		switch resourceType {
		case "worker":
			u := s.state.Users[resourceID]
			if u == nil {
				return 0, nil, apiErr(404, "not_found", "worker not found")
			}
			u.Available = false
		case "node", "location", "laboratory":
			loc := s.state.Locations[resourceID]
			if loc == nil || loc.Implicit {
				return 0, nil, apiErr(404, "not_found", "location not found")
			}
			loc.Active = false
			s.networkChanged()
		case "connection", "route":
			conn := s.state.Connections[resourceID]
			if conn == nil {
				return 0, nil, apiErr(404, "not_found", "connection not found")
			}
			conn.Active = false
			s.networkChanged()
		case "capacity":
			if loc := s.state.Locations[resourceID]; loc != nil && !loc.Implicit {
				loc.Capacity.CapacityUnits = loc.Capacity.ReservedUnits
				loc.Capacity.CooledCapacityUnits = loc.Capacity.CooledReservedUnits
			} else if conn := s.state.Connections[resourceID]; conn != nil {
				conn.Capacity.CapacityUnits = conn.Capacity.ReservedUnits
				conn.Capacity.CooledCapacityUnits = conn.Capacity.CooledReservedUnits
			} else {
				return 0, nil, apiErr(404, "not_found", "capacity resource not found")
			}
			s.networkChanged()
		}
		disruptionID := newUUID()
		c.audit("report_disruption", resourceType, resourceID, "", true, map[string]interface{}{
			"disruptionId": disruptionID, "reason": reason, "occurredAt": fmtTimePtr(occurredAt),
		})
		// find affected samples and replan
		affected := []string{}
		replacements := []string{}
		overallStatus := ReplanNotRequired
		for _, j := range s.state.Journeys {
			if j.Status != JourneyPlanned && j.Status != JourneyInProgress {
				continue
			}
			if !s.journeyUsesResource(j, resourceType, resourceID) {
				continue
			}
			for _, sid := range j.SampleIDs {
				sample := s.state.Samples[sid]
				if sample == nil || sample.Status == SampleReceived || sample.Status == SampleCancelled ||
					sample.Status == SampleExpired {
					continue
				}
				affected = append(affected, sid)
				nj, status := s.replanSample(sample, "disruption:"+resourceType)
				if status == ReplanExpired {
					overallStatus = ReplanExpired
				} else if status == ReplanException && overallStatus != ReplanExpired {
					overallStatus = ReplanException
				} else if status == ReplanReplaced {
					if overallStatus != ReplanExpired && overallStatus != ReplanException {
						overallStatus = ReplanReplaced
					}
					if nj != nil {
						replacements = append(replacements, nj.ID)
					}
				}
			}
		}
		s.emit("disruption.reported", resourceType, resourceID, map[string]interface{}{
			"disruptionId": disruptionID, "resourceType": resourceType, "resourceId": resourceID,
			"affectedSampleIds": affected,
		})
		return 201, J{
			"disruptionId": disruptionID, "affectedSampleIds": affected,
			"replacementPlanIds": replacements, "replanStatus": overallStatus,
		}, nil
	})
}

func (s *Service) journeyUsesResource(j *Journey, resourceType, resourceID string) bool {
	unfinished := func(a *Assignment) bool {
		return a != nil && a.Status != AsgCompleted && a.Status != AsgCancelled
	}
	switch resourceType {
	case "worker":
		for _, ids := range [][]string{j.CollectionAssignmentIDs, j.LegIDs, j.NodeAssignmentIDs, j.LaboratoryAssignmentIDs} {
			for _, id := range ids {
				a := s.state.Assignments[id]
				if unfinished(a) && (a.AcceptedWorkerID == resourceID || a.OfferedToWorkerID == resourceID) {
					return true
				}
			}
		}
	case "node", "location":
		for _, st := range j.Stops {
			if st.CompletedAt == nil && st.LocationID == resourceID {
				return true
			}
		}
	case "laboratory":
		for _, id := range j.LaboratoryAssignmentIDs {
			a := s.state.Assignments[id]
			if unfinished(a) && a.LaboratoryID == resourceID {
				return true
			}
		}
		for _, st := range j.Stops {
			if st.CompletedAt == nil && st.StopType == "delivery" && st.LocationID == resourceID {
				return true
			}
		}
	case "connection", "route":
		for _, id := range j.LegIDs {
			a := s.state.Assignments[id]
			if unfinished(a) && a.ConnectionID == resourceID {
				return true
			}
		}
	case "capacity":
		for _, id := range j.LegIDs {
			a := s.state.Assignments[id]
			if unfinished(a) && a.ConnectionID == resourceID {
				return true
			}
		}
		for _, id := range j.NodeAssignmentIDs {
			a := s.state.Assignments[id]
			if unfinished(a) && a.NodeID == resourceID {
				return true
			}
		}
		for _, id := range j.LaboratoryAssignmentIDs {
			a := s.state.Assignments[id]
			if unfinished(a) && a.LaboratoryID == resourceID {
				return true
			}
		}
	}
	return false
}

// ---------- audit search ----------

func (s *Service) hSearchAuditTrail(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleDispatcher, RoleAdministrator); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "query", "actorId", "entityType", "entityId", "action", "role", "success", "fromTime", "toTime", "limit", "offset", "order"); err != nil {
		return 0, nil, err
	}
	f := AuditFilter{Limit: 50, NewestFirst: true}
	var aerr *ApiError
	if f.Query, aerr = optStr(c.body, "query"); aerr != nil {
		return 0, nil, aerr
	}
	if f.ActorID, aerr = optStr(c.body, "actorId"); aerr != nil {
		return 0, nil, aerr
	}
	if f.EntityType, aerr = optStr(c.body, "entityType"); aerr != nil {
		return 0, nil, aerr
	}
	if f.EntityID, aerr = optStr(c.body, "entityId"); aerr != nil {
		return 0, nil, aerr
	}
	if f.Action, aerr = optStr(c.body, "action"); aerr != nil {
		return 0, nil, aerr
	}
	if f.Role, aerr = optStr(c.body, "role"); aerr != nil {
		return 0, nil, aerr
	}
	if v, ok := c.body["success"]; ok && v != nil {
		b, ok := v.(bool)
		if !ok {
			return 0, nil, apiErr(400, "invalid_json", "success must be a boolean")
		}
		f.Success = &b
	}
	if t, aerr := optTimeField(c.body, "fromTime"); aerr != nil {
		return 0, nil, aerr
	} else {
		f.From = t
	}
	if t, aerr := optTimeField(c.body, "toTime"); aerr != nil {
		return 0, nil, aerr
	} else {
		f.To = t
	}
	if v, ok := c.body["limit"]; ok && v != nil {
		n, ok := v.(float64)
		if !ok || n != float64(int(n)) {
			return 0, nil, apiErr(400, "invalid_limit", "limit must be an integer")
		}
		if int(n) < 1 || int(n) > 500 {
			return 0, nil, apiErr(400, "invalid_limit", "limit must be between 1 and 500")
		}
		f.Limit = int(n)
	}
	if v, ok := c.body["offset"]; ok && v != nil {
		n, ok := v.(float64)
		if !ok || n != float64(int(n)) || int(n) < 0 {
			return 0, nil, apiErr(400, "invalid_offset", "offset must be a non-negative integer")
		}
		f.Offset = int(n)
	}
	if v, ok := c.body["order"]; ok && v != nil {
		ord, ok := v.(string)
		if !ok || (ord != "newest_first" && ord != "oldest_first") {
			return 0, nil, apiErr(400, "invalid_order", "order must be newest_first or oldest_first")
		}
		f.NewestFirst = ord == "newest_first"
	}
	rows, total, err := s.store.SearchAudit(f)
	if err != nil {
		return 0, nil, apiErr(500, "internal_error", "audit search failed")
	}
	items := []J{}
	for _, r := range rows {
		items = append(items, auditView(r))
	}
	hasMore := f.Offset+len(rows) < total
	order := "newest_first"
	if !f.NewestFirst {
		order = "oldest_first"
	}
	c.audit("search_audit_trail", "", "", "", true, map[string]interface{}{"total": total})
	resp := J{
		"entries": items, "total": total, "returned": len(rows),
		"offset": f.Offset, "limit": f.Limit, "order": order, "hasMore": hasMore,
	}
	if hasMore {
		resp["nextOffset"] = f.Offset + len(rows)
	}
	return 200, resp, nil
}

