action.file_text:
* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  background: #f4f5f7;
  color: #1c2333;
}
a { color: #1d4ed8; text-decoration: none; }
a:hover { text-decoration: underline; }

.topbar {
  display: flex; align-items: center; gap: 16px;
  background: #17203a; color: #fff; padding: 10px 20px;
}
.topbar h1 { font-size: 17px; margin: 0; font-weight: 600; }
.topbar nav { display: flex; gap: 12px; flex: 1; }
.topbar nav a { color: #cdd6f4; font-size: 14px; }
.topbar nav a.active { color: #fff; font-weight: 600; }
.topbar .who { font-size: 13px; color: #cdd6f4; }

.container { max-width: 1100px; margin: 24px auto; padding: 0 16px; }
.card {
  background: #fff; border: 1px solid #e2e5ec; border-radius: 8px;
  padding: 16px 20px; margin-bottom: 16px;
}
.card h2 { margin-top: 0; font-size: 17px; }
.card h3 { font-size: 15px; }

button {
  font: inherit; cursor: pointer; border-radius: 6px;
  border: 1px solid #c4cad6; background: #fff; padding: 6px 14px;
}
button.primary { background: #1d4ed8; border-color: #1d4ed8; color: #fff; }
button.danger { background: #b91c1c; border-color: #b91c1c; color: #fff; }
button:disabled { opacity: 0.5; cursor: not-allowed; }

input, select, textarea {
  font: inherit; padding: 6px 8px; border: 1px solid #c4cad6; border-radius: 6px;
  background: #fff;
}
label { display: block; font-size: 13px; font-weight: 600; margin: 10px 0 4px; }
.field-row { display: flex; gap: 16px; flex-wrap: wrap; }
.field-row > div { min-width: 180px; }

.alert { border-radius: 6px; padding: 10px 14px; margin: 10px 0; font-size: 14px; }
.alert.error { background: #fee2e2; color: #991b1b; border: 1px solid #fca5a5; }
.alert.ok { background: #dcfce7; color: #166534; border: 1px solid #86efac; }
.alert.info { background: #dbeafe; color: #1e40af; border: 1px solid #93c5fd; }

table { border-collapse: collapse; width: 100%; font-size: 13px; }
th, td { text-align: left; padding: 6px 10px; border-bottom: 1px solid #e2e5ec; vertical-align: top; }
th { background: #f8f9fc; font-weight: 600; }

.badge {
  display: inline-block; padding: 2px 8px; border-radius: 10px;
  font-size: 12px; font-weight: 600; background: #e2e5ec;
}
.badge.stale { background: #fef3c7; color: #92400e; }
.badge.fresh { background: #dcfce7; color: #166534; }
.badge.exception { background: #fee2e2; color: #991b1b; }
.badge.ok { background: #dcfce7; color: #166534; }

.timeline { list-style: none; margin: 8px 0; padding: 0 0 0 18px; border-left: 2px solid #c4cad6; }
.timeline li { margin: 0 0 10px; padding-left: 10px; position: relative; }
.timeline li::before {
  content: ''; position: absolute; left: -23px; top: 5px; width: 8px; height: 8px;
  border-radius: 50%; background: #1d4ed8;
}
.timeline .t-time { font-size: 12px; color: #6b7280; }

.grid2 { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
@media (max-width: 900px) { .grid2 { grid-template-columns: 1fr; } }

.map-wrap { height: 420px; border-radius: 8px; overflow: hidden; border: 1px solid #e2e5ec; }
.map-wrap.small { height: 260px; }

.muted { color: #6b7280; font-size: 13px; }
.kv { display: grid; grid-template-columns: 200px 1fr; gap: 4px 12px; font-size: 14px; }
.kv dt { font-weight: 600; color: #4b5563; margin: 0; }
.kv dd { margin: 0; }
.actions { display: flex; gap: 8px; margin-top: 10px; flex-wrap: wrap; }
.section-tabs { display: flex; gap: 8px; margin-bottom: 12px; flex-wrap: wrap; }
.section-tabs button.active { background: #1d4ed8; color: #fff; border-color: #1d4ed8; }

