import React from 'react';
import { TimelineEntry } from '../types';

export function entryStatus(e: TimelineEntry): string {
  return String(e.status ?? e.action ?? 'update');
}

export function entryTime(e: TimelineEntry): string {
  const t = e.occurredAt ?? e.occurred_at;
  return t ? new Date(String(t)).toLocaleString() : '';
}

export default function Timeline({ entries, label }: { entries: TimelineEntry[]; label?: string }) {
  return (
    <div>
      {label && <h3>{label}</h3>}
      <ol className="timeline" aria-label={label ?? 'Status history'}>
        {entries.map((e, i) => (
          <li key={i}>
            <div>
              <strong>{entryStatus(e)}</strong>
              {e.role ? <span className="muted"> · {String(e.role)}</span> : null}
            </div>
            <div className="t-time">{entryTime(e)}</div>
          </li>
        ))}
      </ol>
    </div>
  );
}

