      return `Journey ${item.journeyId}`;
    case 'collection':
      return `Collection assignment ${item.assignmentId}`;
    case 'transport':
      return `Transport assignment ${item.assignmentId}`;
    case 'node':
      return `Node assignment ${item.assignmentId}`;
    case 'laboratory':
      return `Laboratory assignment ${item.assignmentId}`;
    default:
