import React, { useCallback, useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { api, nowIso, uuid } from '../api';
import { useAuth } from '../App';
import Timeline from '../components/Timeline';
import CapacityTable from '../components/CapacityTable';
import { RoleWork, WorkItem } from '../types';

export default function WorkPage() {
  const { user } = useAuth();
  const [work, setWork] = useState<RoleWork | null>(null);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');

  const load = useCallback(async () => {
    try {
      const res = await api.post('/api/list-role-work', {});
      setWork(res);
      setError('');
    } catch (e: any) {
      setError(e.message ?? 'Could not load work');
    }
  }, []);

  useEffect(() => {
    load();
  }, [load, user?.activeRole]);

  const run = useCallback(
    async (fn: () => Promise<any>, okMsg: string) => {
      setNotice('');
      setError('');
      try {
        await fn();
        setNotice(okMsg);
        await load();
      } catch (e: any) {
        setError(e.message ?? 'Action failed');
      }
    },
    [load]
  );

  if (!user) return null;
  return (
    <div>
      <h2>My work</h2>
      {error && <div className="alert error" role="alert">{error}</div>}
      {notice && <div className="alert ok" role="status">{notice}</div>}
      {!work && <p className="muted">Loading…</p>}
      {work && (
        <>
          <section aria-label="Pending offers">
            <h3>Pending offers</h3>
            {work.pending.length === 0 && <p className="muted">No pending offers.</p>}
            {work.pending.map((it) => (
              <WorkItemCard key={keyOf(it)} item={it} run={run} />
            ))}
          </section>
          <section aria-label="Current work">
            <h3>Current work</h3>
            {work.inProgress.length === 0 && <p className="muted">No work in progress.</p>}
            {work.inProgress.map((it) => (
              <WorkItemCard key={keyOf(it)} item={it} run={run} />
            ))}
          </section>
          <section aria-label="Past work">
            <h3>Past work</h3>
            {work.completed.length === 0 && <p className="muted">No completed work yet.</p>}
            {work.completed.map((it) => (
              <WorkItemCard key={keyOf(it)} item={it} run={run} />
            ))}
          </section>
        </>
      )}
    </div>
  );
}

function keyOf(it: WorkItem): string {
  return String(it.assignmentId ?? it.sampleId ?? it.journeyId ?? Math.random());
}

function WorkItemCard({
  item,
  run,
}: {
  item: WorkItem;
  run: (fn: () => Promise<any>, okMsg: string) => Promise<void>;
}) {
  const [showHistory, setShowHistory] = useState(false);
  const title = itemTitle(item);
  return (
    <div className="card">
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <strong>{title}</strong>
        <span>
          <span className="badge">{item.status}</span>{' '}
          {item.locationStale !== undefined && (
            <span className={`badge ${item.locationStale ? 'stale' : 'fresh'}`}>
              {item.locationStale ? 'location stale' : 'location fresh'}
            </span>
          )}
        </span>
      </div>
      <dl className="kv" style={{ marginTop: 8 }}>
        {item.sampleId && (
          <>
            <dt>Sample</dt>
            <dd>
              <Link to={`/samples/${item.sampleId}`}>{item.sampleId}</Link>
            </dd>
          </>
        )}
        {item.journeyId && (
          <>
            <dt>Journey</dt>
            <dd>{item.journeyId}</dd>
          </>
        )}
        {item.fromLocationId && (
          <>
            <dt>From</dt>
            <dd>{item.fromLocationId}</dd>
          </>
        )}
        {item.toLocationId && (
          <>
            <dt>To</dt>
            <dd>{item.toLocationId}</dd>
          </>
        )}
        {item.deliveryDeadline && (
          <>
            <dt>Delivery deadline</dt>
            <dd>{new Date(item.deliveryDeadline).toLocaleString()}</dd>
          </>
        )}
        {item.offerExpiresAt && (
          <>
            <dt>Offer expires</dt>
            <dd>{new Date(item.offerExpiresAt).toLocaleString()}</dd>
          </>
        )}
      </dl>
      <AssignmentActions item={item} run={run} />
      {item.destinationCapacity && (
        <details style={{ marginTop: 8 }}>
          <summary>Destination capacity</summary>
          <CapacityTable capacity={item.destinationCapacity} />
        </details>
      )}
      <div className="actions">
        <button onClick={() => setShowHistory((s) => !s)}>
          {showHistory ? 'Hide status history' : 'Show status history'}
        </button>
      </div>
      {showHistory && <Timeline entries={item.history ?? []} label="Status history" />}
    </div>
  );
}

function itemTitle(item: WorkItem): string {
  switch (item.kind) {
    case 'sample':
