      setNotice('Handoff confirmed');
      await load();
    } catch (e: any) {
      setError(e.message ?? 'Could not confirm handoff');
    }
  };

  return (
    <div>
      <h2>
        Sample {state.sampleId}{' '}
        <span className={`badge ${isException ? 'exception' : ''}`}>{status}</span>
      </h2>
      {notice && <div className="alert ok" role="status">{notice}</div>}
      {isException && (
        <div className="alert error" role="alert" aria-label="Exception">
          <strong>Exception:</strong>{' '}
          {lifecycle.exception?.code ?? status}
          {lifecycle.exception?.reason ? ` — ${lifecycle.exception.reason}` : ''}
        </div>
      )}
      <div className="grid2">
        <div className="card">
          <h2>Tracking</h2>
          <dl className="kv">
            <dt>Current status</dt>
            <dd>{status}</dd>
            <dt>Current custodian</dt>
            <dd>{lifecycle.currentHolderId ?? state.currentHolderId ?? '—'}</dd>
            <dt>Current / last known location</dt>
            <dd>
              {state.latestLocation ?? lifecycle.latestLocation
                ? `${(state.latestLocation ?? lifecycle.latestLocation)!.latitude.toFixed(5)}, ${(state.latestLocation ?? lifecycle.latestLocation)!.longitude.toFixed(5)}`
                : 'No location recorded yet'}
            </dd>
            <dt>Last update</dt>
            <dd>
              {state.locationRecordedAt ?? lifecycle.locationRecordedAt
                ? new Date(String(state.locationRecordedAt ?? lifecycle.locationRecordedAt)).toLocaleString()
                : '—'}
            </dd>
            <dt>Location freshness</dt>
            <dd>
              <span className={`badge ${lifecycle.locationStale ? 'stale' : 'fresh'}`}>
                {lifecycle.locationStale ? 'stale' : 'fresh'}
              </span>
              {isOwner && <span className="muted"> (visible to you as the request owner)</span>}
            </dd>
            <dt>Delivery deadline</dt>
            <dd>{state.deliveryDeadline ? new Date(state.deliveryDeadline).toLocaleString() : '—'}</dd>
            <dt>Sealed</dt>
            <dd>{lifecycle.sealed ? 'yes' : 'no'}</dd>
            <dt>Route progress</dt>
            <dd>
              {plan
                ? `${lifecycle.completedLegIds.length} of ${plan.legs?.length ?? lifecycle.completedLegIds.length} legs completed`
                : `${lifecycle.completedLegIds.length} legs completed`}
            </dd>
          </dl>
          {canConfirmHandoff && (
            <div className="actions">
              {lifecycle.pendingHandoff?.senderId === user!.userId && (
                <button className="primary" onClick={() => confirmHandoff('sender')}>
                  Confirm handoff as sender
                </button>
              )}
              {lifecycle.pendingHandoff?.receiverId === user!.userId && (
                <button className="primary" onClick={() => confirmHandoff('receiver')}>
                  Confirm handoff as receiver
                </button>
              )}
            </div>
          )}
        </div>
        <div className="card">
          <h2>Map</h2>
          <MapView
            markers={[
              ...(state.origin
                ? [{ id: 'origin', lat: state.origin.latitude, lng: state.origin.longitude, label: 'Origin', color: '#1d4ed8' }]
                : []),
              ...((state.latestLocation ?? lifecycle.latestLocation)
                ? [{
                    id: 'current',
                    lat: (state.latestLocation ?? lifecycle.latestLocation)!.latitude,
                    lng: (state.latestLocation ?? lifecycle.latestLocation)!.longitude,
                    label: 'Last known location',
                    color: '#b91c1c',
                  }]
                : []),
            ]}
          />
        </div>
      </div>
      <div className="card">
        <h2>Status history</h2>
        <Timeline entries={lifecycle.timeline ?? state.timeline ?? []} label="Ordered status history" />
      </div>
      {plan && (
        <div className="card">
          <h2>Journey plan</h2>
          <dl className="kv">
            <dt>Journey</dt>
            <dd>{plan.journeyId}</dd>
            <dt>Status</dt>
            <dd>{plan.status}</dd>
            <dt>Plan version</dt>
            <dd>{plan.planVersion}</dd>
            <dt>Route mode</dt>
            <dd>{plan.routeMode ?? '—'}</dd>
            <dt>Estimated delivery</dt>
            <dd>{plan.estimatedDeliveryAt ? new Date(plan.estimatedDeliveryAt).toLocaleString() : '—'}</dd>
          </dl>
          {plan.legs && plan.legs.length > 0 && (
            <table aria-label="Journey legs">
              <thead>
                <tr>
                  <th>#</th>
                  <th>Leg</th>
                  <th>From</th>
                  <th>To</th>
                  <th>Status</th>
                </tr>
              </thead>
              <tbody>
                {plan.legs.map((leg: any, i: number) => (
                  <tr key={leg.assignmentId ?? i}>
                    <td>{i + 1}</td>
                    <td>{leg.kind ?? leg.assignmentId}</td>
                    <td>{leg.fromLocationId ?? '—'}</td>
                    <td>{leg.toLocationId ?? leg.nodeId ?? leg.laboratoryId ?? '—'}</td>
                    <td>{leg.status}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      )}
    </div>
  );
