import React, { useEffect, useRef } from 'react';
import maplibregl from 'maplibre-gl';
import { Protocol } from 'pmtiles';

let protocolRegistered = false;
function registerProtocol() {
  if (!protocolRegistered) {
    const protocol = new Protocol();
    maplibregl.addProtocol('pmtiles', protocol.tile);
    protocolRegistered = true;
  }
}

export interface MapMarker {
  id: string;
  lat: number;
  lng: number;
  label?: string;
  color?: string;
}

export default function MapView({
  markers = [],
  height,
}: {
  markers?: MapMarker[];
  height?: number;
}) {
  const ref = useRef<HTMLDivElement>(null);
  const mapRef = useRef<maplibregl.Map | null>(null);
  const markersRef = useRef<maplibregl.Marker[]>([]);

  useEffect(() => {
    registerProtocol();
    if (!ref.current || mapRef.current) return;
    const map = new maplibregl.Map({
      container: ref.current,
      style: '/map-assets/style.json',
      center: [77.5946, 12.9716],
      zoom: 11,
      attributionControl: { compact: true },
    });
    map.addControl(new maplibregl.NavigationControl(), 'top-right');
    mapRef.current = map;
    return () => {
      map.remove();
      mapRef.current = null;
    };
  }, []);

  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;
    markersRef.current.forEach((m) => m.remove());
    markersRef.current = markers.map((mk) => {
      const el = document.createElement('div');
      el.style.width = '14px';
      el.style.height = '14px';
      el.style.borderRadius = '50%';
      el.style.background = mk.color ?? '#1d4ed8';
      el.style.border = '2px solid #fff';
      const marker = new maplibregl.Marker({ element: el })
        .setLngLat([mk.lng, mk.lat])
        .addTo(map);
      if (mk.label) {
        marker.setPopup(new maplibregl.Popup({ offset: 12 }).setText(mk.label));
      }
      return marker;
    });
    if (markers.length > 0) {
      const bounds = new maplibregl.LngLatBounds();
      markers.forEach((m) => bounds.extend([m.lng, m.lat]));
      if (markers.length === 1) {
        map.easeTo({ center: [markers[0].lng, markers[0].lat], zoom: 12 });
      } else {
        map.fitBounds(bounds, { padding: 60, maxZoom: 13 });
      }
    }
  }, [markers]);

  return (
    <div
      ref={ref}
      className={`map-wrap${height && height < 300 ? ' small' : ''}`}
      style={height ? { height } : undefined}
      role="region"
      aria-label="Map"
    />
  );
}

