import React, { useCallback, useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import { api, nowIso, uuid } from '../api';
import { useAuth } from '../App';
import Timeline from '../components/Timeline';
import MapView from '../components/MapView';
import { JourneyPlan, SampleLifecycle, SampleState } from '../types';

export default function SampleDetailPage() {
  const { id } = useParams<{ id: string }>();
  const { user } = useAuth();
  const [state, setState] = useState<SampleState | null>(null);
  const [lifecycle, setLifecycle] = useState<SampleLifecycle | null>(null);
  const [plan, setPlan] = useState<JourneyPlan | null>(null);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');

  const load = useCallback(async () => {
    if (!id) return;
    try {
      const st = await api.post('/api/read-sample-state', { sampleId: id });
      setState(st);
      const lc = await api.post('/api/read-sample-lifecycle', { sampleId: id });
      setLifecycle(lc);
      const journeyId = st.activeJourneyId ?? lc.activeJourneyId;
      if (journeyId) {
        try {
          const jp = await api.post('/api/read-journey-plan', { journeyId });
          setPlan(jp);
        } catch {
          setPlan(null);
        }
      } else {
        setPlan(null);
      }
      setError('');
    } catch (e: any) {
      setError(e.message ?? 'Could not load sample');
    }
  }, [id]);

  useEffect(() => {
    load();
  }, [load]);

  if (error) {
    return <div className="alert error" role="alert">{error}</div>;
  }
  if (!state || !lifecycle) {
    return <p className="muted">Loading…</p>;
  }
  const status = state.state?.status ?? lifecycle.status;
  const isException = status === 'exception' || status === 'expired' || !!lifecycle.exception;
  const isOwner = user?.userId === state.requesterId;
  const canConfirmHandoff =
    lifecycle.pendingHandoffId &&
    user &&
    (lifecycle.pendingHandoff?.senderId === user.userId ||
      lifecycle.pendingHandoff?.receiverId === user.userId);

  const confirmHandoff = async (side: 'sender' | 'receiver') => {
    setNotice('');
    try {
      await api.post('/api/confirm-handoff', {
        handoffId: lifecycle.pendingHandoffId,
        confirmationSide: side,
        confirmedAt: nowIso(),
