                : '—'}
            </dd>
            <dt>Location freshness</dt>
            <dd>
              <span className={`badge ${lifecycle.locationStale ? 'stale' : 'fresh'}`}>
                {lifecycle.locationStale ? 'stale' : 'fresh'}
              </span>
              {isOwner && <span className="muted"> (visible to you as the request owner)</span>}
            </dd>
            <dt>Delivery deadline</dt>
            <dd>{state.deliveryDeadline ? new Date(state.deliveryDeadline).toLocaleString() : '—'}</dd>
            <dt>Sealed</dt>
            <dd>{lifecycle.sealed ? 'yes' : 'no'}</dd>
            <dt>Route progress</dt>
            <dd>
              {plan
                ? `${lifecycle.completedLegIds.length} of ${plan.legs?.length ?? lifecycle.completedLegIds.length} legs completed`
                : `${lifecycle.completedLegIds.length} legs completed`}
            </dd>
          </dl>
          {canConfirmHandoff && (
            <div className="actions">
              {lifecycle.pendingHandoff?.senderId === user!.userId && (
                <button className="primary" onClick={() => confirmHandoff('sender')}>
