            <dt>Estimated delivery</dt>
            <dd>{plan.estimatedDeliveryAt ? new Date(plan.estimatedDeliveryAt).toLocaleString() : '—'}</dd>
          </dl>
          {plan.legs && plan.legs.length > 0 && (
            <table aria-label="Journey legs">
