import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { api, nowIso, uuid } from '../api';

function localToIso(v: string): string {
  return new Date(v).toISOString();
}

function defaultLocal(hoursFromNow: number): string {
  const d = new Date(Date.now() + hoursFromNow * 3600 * 1000);
  d.setSeconds(0, 0);
  const pad = (n: number) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

export default function NewRequestPage() {
  const navigate = useNavigate();
  const [originType, setOriginType] = useState('home');
  const [lat, setLat] = useState('12.9716');
  const [lng, setLng] = useState('77.5946');
  const [originNodeId, setOriginNodeId] = useState('');
  const [sampleTypeId, setSampleTypeId] = useState('');
  const [requestedAt, setRequestedAt] = useState(defaultLocal(0));
  const [earliest, setEarliest] = useState(defaultLocal(0));
  const [latest, setLatest] = useState(defaultLocal(4));
  const [deadline, setDeadline] = useState(defaultLocal(12));
  const [containerType, setContainerType] = useState('standard');
  const [tempMin, setTempMin] = useState('2');
  const [tempMax, setTempMax] = useState('25');
  const [incompat, setIncompat] = useState('');
  const [checkResult, setCheckResult] = useState<any>(null);
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);

  const specBody = () => ({
    origin: { latitude: parseFloat(lat), longitude: parseFloat(lng) },
    originType,
    originNodeId: originType === 'node' ? originNodeId : '',
    sampleTypeId,
    requestedAt: localToIso(requestedAt),
    deliveryDeadline: localToIso(deadline),
    earliestCollectionAt: localToIso(earliest),
    latestCollectionAt: localToIso(latest),
  });

  const check = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setCheckResult(null);
    setBusy(true);
    try {
      const res = await api.post('/api/check-serviceability', specBody());
      setCheckResult(res);
    } catch (err: any) {
      setError(err.message ?? 'Serviceability check failed');
    } finally {
      setBusy(false);
    }
  };

  const create = async () => {
    setError('');
    setBusy(true);
    try {
      const res = await api.post('/api/create-collection-request', {
        ...specBody(),
        containerType,
        temperatureMinC: parseFloat(tempMin),
        temperatureMaxC: parseFloat(tempMax),
        incompatibleSampleTypes: incompat
          .split(',')
          .map((s) => s.trim())
          .filter(Boolean),
        idempotencyKey: uuid(),
      });
      navigate(`/samples/${res.sampleId}`);
    } catch (err: any) {
      setError(err.message ?? 'Could not create request');
    } finally {
      setBusy(false);
    }
  };

  return (
    <div>
      <h2>New collection request</h2>
      {error && <div className="alert error" role="alert">{error}</div>}
      <div className="card">
        <form onSubmit={check}>
          <div className="field-row">
            <div>
              <label htmlFor="originType">Origin type</label>
              <select id="originType" value={originType} onChange={(e) => setOriginType(e.target.value)}>
                <option value="home">Home</option>
                <option value="clinic">Clinic</option>
                <option value="node">Network node</option>
              </select>
            </div>
            <div>
              <label htmlFor="sampleTypeId">Sample type ID</label>
              <input
                id="sampleTypeId"
                value={sampleTypeId}
                onChange={(e) => setSampleTypeId(e.target.value)}
                placeholder="Sample type id (e.g. Amber, Indigo, Frost, Pulse)"
                required
              />
            </div>
          </div>
          <div className="field-row">
            <div>
              <label htmlFor="lat">Origin latitude</label>
              <input id="lat" value={lat} onChange={(e) => setLat(e.target.value)} required />
            </div>
            <div>
              <label htmlFor="lng">Origin longitude</label>
              <input id="lng" value={lng} onChange={(e) => setLng(e.target.value)} required />
            </div>
          </div>
          {originType === 'node' && (
            <div>
              <label htmlFor="originNodeId">Origin node ID</label>
              <input
                id="originNodeId"
                value={originNodeId}
                onChange={(e) => setOriginNodeId(e.target.value)}
                required
              />
            </div>
          )}
          <div className="field-row">
            <div>
              <label htmlFor="requestedAt">Requested at</label>
              <input
                id="requestedAt"
                type="datetime-local"
                value={requestedAt}
                onChange={(e) => setRequestedAt(e.target.value)}
                required
              />
            </div>
            <div>
              <label htmlFor="deadline">Delivery deadline</label>
              <input
                id="deadline"
                type="datetime-local"
                value={deadline}
                onChange={(e) => setDeadline(e.target.value)}
                required
              />
            </div>
          </div>
          <div className="field-row">
            <div>
              <label htmlFor="earliest">Earliest collection</label>
              <input
                id="earliest"
                type="datetime-local"
                value={earliest}
                onChange={(e) => setEarliest(e.target.value)}
                required
              />
            </div>
            <div>
              <label htmlFor="latest">Latest collection</label>
              <input
                id="latest"
                type="datetime-local"
                value={latest}
                onChange={(e) => setLatest(e.target.value)}
                required
              />
            </div>
          </div>
          <div className="actions">
            <button className="primary" type="submit" disabled={busy}>
              Check serviceability
            </button>
          </div>
        </form>
      </div>
      {checkResult && (
        <div className="card" aria-label="Serviceability result">
          <h2>Serviceability result</h2>
          <p className="muted">Dry run only — no request, sample, journey, assignment or reservation was created.</p>
          <dl className="kv">
            <dt>Serviceable</dt>
            <dd>
              <span className={`badge ${checkResult.serviceable ? 'fresh' : 'stale'}`}>
                {checkResult.serviceable ? 'serviceable' : 'not serviceable'}
              </span>
            </dd>
            <dt>Reason</dt>
            <dd>{checkResult.reason}</dd>
            <dt>Calculation version</dt>
            <dd>{checkResult.serviceabilityVersion}</dd>
            {checkResult.targetLaboratoryId && (
              <>
                <dt>Target laboratory</dt>
                <dd>{checkResult.targetLaboratoryId}</dd>
              </>
            )}
            {checkResult.estimatedArrivalAt && (
              <>
                <dt>Estimated arrival</dt>
                <dd>{new Date(checkResult.estimatedArrivalAt).toLocaleString()}</dd>
              </>
            )}
          </dl>
          {checkResult.serviceable && (
            <>
              <h3>Handling attributes</h3>
              <div className="field-row">
                <div>
                  <label htmlFor="containerType">Container type</label>
                  <input
                    id="containerType"
                    value={containerType}
                    onChange={(e) => setContainerType(e.target.value)}
                  />
                </div>
                <div>
                  <label htmlFor="incompat">Incompatible sample type IDs (comma separated)</label>
                  <input id="incompat" value={incompat} onChange={(e) => setIncompat(e.target.value)} />
                </div>
              </div>
              <div className="field-row">
                <div>
                  <label htmlFor="tempMin">Temperature min (°C)</label>
                  <input id="tempMin" value={tempMin} onChange={(e) => setTempMin(e.target.value)} />
                </div>
                <div>
                  <label htmlFor="tempMax">Temperature max (°C)</label>
                  <input id="tempMax" value={tempMax} onChange={(e) => setTempMax(e.target.value)} />
                </div>
              </div>
              <div className="actions">
                <button className="primary" onClick={create} disabled={busy}>
                  Create collection request
                </button>
              </div>
            </>
          )}
        </div>
      )}
    </div>
  );
}

