                <option value="oldest_first">Oldest first</option>
              </select>
            </div>
          </div>
          <div className="actions">
            <button className="primary" type="submit">
              Search audit trail
            </button>
          </div>
        </form>
      </div>
      {result && (
        <div className="card">
          <p className="muted">
            {result.total} record{result.total === 1 ? '' : 's'} found
          </p>
          <table aria-label="Audit entries">
            <thead>
              <tr>
                <th>Time</th>
                <th>Actor</th>
                <th>Role</th>
                <th>Action</th>
                <th>Entity</th>
                <th>Outcome</th>
                <th>Details</th>
              </tr>
            </thead>
            <tbody>
              {result.entries.map((e) => (
                <tr key={e.auditId}>
                  <td>{e.occurredAt ? new Date(e.occurredAt).toLocaleString() : ''}</td>
                  <td>{e.actorId}</td>
                  <td>{e.role}</td>
                  <td>{e.action}</td>
                  <td>
                    {e.entityType} {e.entityId}
                  </td>
                  <td>{e.success ? 'success' : 'failure'}</td>
                  <td>
                    <code style={{ fontSize: 11 }}>
                      {e.details ? JSON.stringify(e.details).slice(0, 120) : ''}
                    </code>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          <div className="actions">
            {offset > 0 && (
              <button onClick={() => search(Math.max(0, offset - 50))}>Previous page</button>
            )}
            {result.hasMore && result.nextOffset !== undefined && (
              <button onClick={() => search(result.nextOffset!)}>Next page</button>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

