import React, { useCallback, useEffect, useState } from 'react';
import { api } from '../api';
import CapacityTable from '../components/CapacityTable';
import { OperationsState, ROLE_LABELS, ServiceabilitySnapshot } from '../types';

const ALL_ROLES = Object.keys(ROLE_LABELS);
const FUNCTIONS = ['collection_point', 'transfer_point', 'hub', 'laboratory'];

export default function AdminPage() {
  const [ops, setOps] = useState<OperationsState | null>(null);
  const [snapshot, setSnapshot] = useState<ServiceabilitySnapshot | null>(null);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');

  const load = useCallback(async () => {
    try {
      const res = await api.post('/api/read-operations-state', { filters: {} });
      setOps(res);
      const snap = await api.post('/api/read-serviceability-snapshot', {});
      setSnapshot(snap);
      setError('');
    } catch (e: any) {
      setError(e.message ?? 'Could not load admin data');
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  const run = async (fn: () => Promise<any>, okMsg: string) => {
    setNotice('');
    setError('');
    try {
      await fn();
      setNotice(okMsg);
      await load();
    } catch (e: any) {
      setError(e.message ?? 'Action failed');
    }
  };

  return (
    <div>
      <h2>Administration</h2>
      {error && <div className="alert error" role="alert">{error}</div>}
      {notice && <div className="alert ok" role="status">{notice}</div>}

      <details className="card" open>
        <summary><strong>Users</strong></summary>
        <CreateUserForm run={run} />
        <UpdateUserForm run={run} />
        <WorkerAvailabilityForm run={run} />
      </details>

      <details className="card">
        <summary><strong>Locations</strong></summary>
        <CreateLocationForm run={run} />
        <LocationStatusForm run={run} />
        <LocationFunctionForm run={run} />
        {ops && (
          <table aria-label="Existing locations">
            <thead>
              <tr>
                <th>ID</th>
                <th>Name</th>
                <th>Functions</th>
                <th>Active</th>
                <th>Capacity</th>
              </tr>
            </thead>
            <tbody>
              {(ops.locations ?? []).map((l) => (
                <tr key={l.locationId}>
                  <td><code>{l.locationId}</code></td>
                  <td>{l.name}</td>
                  <td>{(l.functions ?? []).join(', ')}</td>
                  <td>{l.active ? 'yes' : 'no'}</td>
                  <td>
                    {l.capacity
                      ? `regular ${l.capacity.availableUnits}/${l.capacity.capacityUnits}, cooled ${l.capacity.cooledAvailableUnits}/${l.capacity.cooledCapacityUnits}`
                      : '—'}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </details>

      <details className="card">
        <summary><strong>Connections</strong></summary>
        <CreateConnectionForm run={run} />
        <ConnectionStatusForm run={run} />
        {ops && (
          <table aria-label="Existing connections">
            <thead>
              <tr>
                <th>ID</th>
                <th>From</th>
                <th>To</th>
                <th>Travel (min)</th>
                <th>Cooled</th>
                <th>Active</th>
              </tr>
            </thead>
            <tbody>
              {(ops.connections ?? []).map((c) => (
                <tr key={c.connectionId}>
                  <td><code>{c.connectionId}</code></td>
                  <td>{c.fromLocationId}</td>
                  <td>{c.toLocationId}</td>
                  <td>{c.travelMinutes}</td>
                  <td>{c.cooled ? 'yes' : 'no'}</td>
                  <td>{c.active ? 'yes' : 'no'}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </details>

      <details className="card">
        <summary><strong>Sample types</strong></summary>
        <CreateSampleTypeForm run={run} />
        <UpdateSampleTypeForm run={run} />
      </details>

      <details className="card">
        <summary><strong>Capacity and laboratory acceptance</strong></summary>
        <CapacityForm run={run} />
        <LabAcceptanceForm run={run} />
      </details>

      <div className="card">
        <h2>Serviceability snapshot</h2>
        {snapshot ? (
          <>
            <dl className="kv">
              <dt>Version</dt>
              <dd>{snapshot.version}</dd>
              <dt>Status</dt>
              <dd>{snapshot.status}</dd>
              <dt>Computed at</dt>
              <dd>{snapshot.computedAt ? new Date(snapshot.computedAt).toLocaleString() : '—'}</dd>
              <dt>Network revision</dt>
              <dd>{snapshot.networkRevision}</dd>
              <dt>Active collection points</dt>
              <dd>{snapshot.activeCollectionPointCount}</dd>
            </dl>
            <table aria-label="Serviceability regions">
              <thead>
                <tr>
                  <th>Location</th>
                  <th>Name</th>
                  <th>Latitude</th>
                  <th>Longitude</th>
                  <th>Coverage (km)</th>
                </tr>
              </thead>
              <tbody>
                {(snapshot.regions ?? []).map((r) => (
                  <tr key={r.locationId}>
                    <td><code>{r.locationId}</code></td>
                    <td>{r.name}</td>
                    <td>{r.latitude}</td>
                    <td>{r.longitude}</td>
                    <td>{r.coverageKm}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </>
        ) : (
          <p className="muted">Loading…</p>
        )}
      </div>
    </div>
  );
}

type Run = (fn: () => Promise<any>, okMsg: string) => Promise<void>;

function TextField({ id, label, value, onChange, required }: {
  id: string; label: string; value: string; onChange: (v: string) => void; required?: boolean;
}) {
  return (
    <div>
      <label htmlFor={id}>{label}</label>
      <input id={id} value={value} onChange={(e) => onChange(e.target.value)} required={required} />
    </div>
  );
}

function CreateUserForm({ run }: { run: Run }) {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [fullName, setFullName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');
  const [roles, setRoles] = useState<string[]>([]);
  const [qualifications, setQualifications] = useState('');
  const [certifications, setCertifications] = useState('');
  const [assignedLocationId, setAssignedLocationId] = useState('');
  const toggleRole = (r: string) =>
    setRoles((cur) => (cur.includes(r) ? cur.filter((x) => x !== r) : [...cur, r]));
  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        run(
          () =>
            api.post('/api/create-user', {
              username,
              initialPassword: password,
              email,
              fullName,
              phone,
              roles,
              qualifications: qualifications.split(',').map((s) => s.trim()).filter(Boolean),
              certifications: certifications.split(',').map((s) => s.trim()).filter(Boolean),
              active: true,
              assignedLocationId,
            }),
          `User ${username} created`
        );
      }}
    >
      <h3>Create user</h3>
      <div className="field-row">
        <TextField id="cu-username" label="Username" value={username} onChange={setUsername} required />
        <TextField id="cu-password" label="Initial password" value={password} onChange={setPassword} required />
      </div>
      <div className="field-row">
        <TextField id="cu-fullname" label="Full name" value={fullName} onChange={setFullName} required />
        <TextField id="cu-email" label="Email" value={email} onChange={setEmail} />
      </div>
      <div className="field-row">
        <TextField id="cu-phone" label="Phone" value={phone} onChange={setPhone} />
        <TextField
          id="cu-assigned"
          label="Assigned node / laboratory ID"
          value={assignedLocationId}
          onChange={setAssignedLocationId}
        />
      </div>
      <fieldset style={{ border: '1px solid #e2e5ec', borderRadius: 6, margin: '8px 0' }}>
        <legend>Roles</legend>
        {ALL_ROLES.map((r) => (
          <label key={r} style={{ display: 'inline-flex', gap: 4, marginRight: 12, fontWeight: 400 }}>
            <input type="checkbox" checked={roles.includes(r)} onChange={() => toggleRole(r)} />
            {ROLE_LABELS[r]}
          </label>
        ))}
      </fieldset>
      <div className="field-row">
        <TextField
          id="cu-quals"
          label="Qualifications (comma separated)"
          value={qualifications}
          onChange={setQualifications}
        />
        <TextField
          id="cu-certs"
          label="Certifications (comma separated)"
          value={certifications}
          onChange={setCertifications}
        />
      </div>
      <div className="actions">
        <button className="primary" type="submit">Create user</button>
      </div>
    </form>
  );
}

function UpdateUserForm({ run }: { run: Run }) {
  const [userId, setUserId] = useState('');
  const [roles, setRoles] = useState('');
  const [qualifications, setQualifications] = useState('');
  const [certifications, setCertifications] = useState('');
  const [active, setActive] = useState(true);
  const [assignedLocationId, setAssignedLocationId] = useState('');
  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        run(
          () =>
            api.post('/api/update-user-access', {
              userId,
              roles: roles.split(',').map((s) => s.trim()).filter(Boolean),
              qualifications: qualifications.split(',').map((s) => s.trim()).filter(Boolean),
              certifications: certifications.split(',').map((s) => s.trim()).filter(Boolean),
              active,
              assignedLocationId,
            }),
          'User access updated'
        );
      }}
    >
      <h3>Update user access</h3>
      <div className="field-row">
        <TextField id="uu-id" label="User ID" value={userId} onChange={setUserId} required />
        <TextField
          id="uu-roles"
          label="Roles (comma separated)"
          value={roles}
          onChange={setRoles}
        />
      </div>
      <div className="field-row">
        <TextField
          id="uu-quals"
          label="Qualifications (comma separated)"
          value={qualifications}
          onChange={setQualifications}
        />
        <TextField
          id="uu-certs"
          label="Certifications (comma separated)"
          value={certifications}
          onChange={setCertifications}
        />
      </div>
      <div className="field-row">
        <TextField
          id="uu-assigned"
          label="Assigned node / laboratory ID"
          value={assignedLocationId}
          onChange={setAssignedLocationId}
        />
        <div>
          <label htmlFor="uu-active">Active</label>
          <select id="uu-active" value={active ? 'yes' : 'no'} onChange={(e) => setActive(e.target.value === 'yes')}>
            <option value="yes">active</option>
            <option value="no">inactive</option>
          </select>
        </div>
      </div>
      <div className="actions">
        <button type="submit">Update user access</button>
      </div>
    </form>
  );
}

function WorkerAvailabilityForm({ run }: { run: Run }) {
  const [workerId, setWorkerId] = useState('');
  const [available, setAvailable] = useState(true);
  const [capacityUnits, setCapacityUnits] = useState('1');
  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        run(
          () =>
            api.post('/api/set-worker-availability', {
              workerId,
              available,
              capacityUnits: parseInt(capacityUnits || '0', 10),
            }),
          'Worker availability updated'
        );
      }}
    >
      <h3>Set worker availability</h3>
      <div className="field-row">
        <TextField id="wa-id" label="Worker ID" value={workerId} onChange={setWorkerId} required />
        <div>
          <label htmlFor="wa-avail">Available</label>
          <select id="wa-avail" value={available ? 'yes' : 'no'} onChange={(e) => setAvailable(e.target.value === 'yes')}>
            <option value="yes">available</option>
            <option value="no">unavailable</option>
          </select>
        </div>
      </div>
      <div className="field-row">
        <TextField id="wa-cap" label="Capacity units" value={capacityUnits} onChange={setCapacityUnits} />
        <div />
      </div>
      <div className="actions">
        <button type="submit">Save availability</button>
      </div>
    </form>
  );
}

function CreateLocationForm({ run }: { run: Run }) {
  const [name, setName] = useState('');
  const [lat, setLat] = useState('12.9716');
  const [lng, setLng] = useState('77.5946');
  const [coverageKm, setCoverageKm] = useState('5');
  const [handlingMinutes, setHandlingMinutes] = useState('10');
  const [functions, setFunctions] = useState<string[]>(['collection_point']);
  const toggle = (f: string) =>
    setFunctions((cur) => (cur.includes(f) ? cur.filter((x) => x !== f) : [...cur, f]));
  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        run(
          () =>
            api.post('/api/create-location', {
              name,
              coordinate: { latitude: parseFloat(lat), longitude: parseFloat(lng) },
              coverageKm: parseFloat(coverageKm),
              handlingMinutes: parseInt(handlingMinutes || '0', 10),
              active: true,
              functions,
            }),
          `Location ${name} created`
        );
      }}
    >
      <h3>Create location</h3>
      <div className="field-row">
        <TextField id="cl-name" label="Name" value={name} onChange={setName} required />
        <TextField id="cl-coverage" label="Coverage (km)" value={coverageKm} onChange={setCoverageKm} />
      </div>
      <div className="field-row">
        <TextField id="cl-lat" label="Latitude" value={lat} onChange={setLat} required />
        <TextField id="cl-lng" label="Longitude" value={lng} onChange={setLng} required />
      </div>
      <div className="field-row">
        <TextField id="cl-handling" label="Handling minutes" value={handlingMinutes} onChange={setHandlingMinutes} />
        <div />
      </div>
      <fieldset style={{ border: '1px solid #e2e5ec', borderRadius: 6, margin: '8px 0' }}>
        <legend>Functions</legend>
        {FUNCTIONS.map((f) => (
          <label key={f} style={{ display: 'inline-flex', gap: 4, marginRight: 12, fontWeight: 400 }}>
            <input type="checkbox" checked={functions.includes(f)} onChange={() => toggle(f)} />
            {f}
          </label>
        ))}
      </fieldset>
      <div className="actions">
        <button className="primary" type="submit">Create location</button>
      </div>
    </form>
  );
}

function LocationStatusForm({ run }: { run: Run }) {
  const [locationId, setLocationId] = useState('');
  const [active, setActive] = useState(true);
  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        run(
          () => api.post('/api/set-location-status', { locationId, active }),
          'Location status updated'
        );
      }}
    >
      <h3>Activate / deactivate location</h3>
      <div className="field-row">
        <TextField id="ls-id" label="Location ID" value={locationId} onChange={setLocationId} required />
        <div>
          <label htmlFor="ls-active">Status</label>
          <select id="ls-active" value={active ? 'yes' : 'no'} onChange={(e) => setActive(e.target.value === 'yes')}>
            <option value="yes">active</option>
            <option value="no">inactive</option>
          </select>
        </div>
      </div>
      <div className="actions">
        <button type="submit">Save location status</button>
      </div>
    </form>
  );
}

function LocationFunctionForm({ run }: { run: Run }) {
  const [locationId, setLocationId] = useState('');
  const [fn, setFn] = useState('collection_point');
  const [active, setActive] = useState(true);
  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        run(
          () => api.post('/api/set-location-function-status', { locationId, function: fn, active }),
          'Location function status updated'
        );
      }}
    >
      <h3>Activate / deactivate a location function</h3>
      <div className="field-row">
        <TextField id="lf-id" label="Location ID" value={locationId} onChange={setLocationId} required />
        <div>
          <label htmlFor="lf-fn">Function</label>
          <select id="lf-fn" value={fn} onChange={(e) => setFn(e.target.value)}>
            {FUNCTIONS.map((f) => (
              <option key={f} value={f}>{f}</option>
            ))}
          </select>
        </div>
      </div>
      <div className="field-row">
        <div>
          <label htmlFor="lf-active">Status</label>
          <select id="lf-active" value={active ? 'yes' : 'no'} onChange={(e) => setActive(e.target.value === 'yes')}>
            <option value="yes">active</option>
            <option value="no">inactive</option>
          </select>
        </div>
        <div />
      </div>
      <div className="actions">
        <button type="submit">Save function status</button>
      </div>
    </form>
  );
}

function CreateConnectionForm({ run }: { run: Run }) {
  const [fromId, setFromId] = useState('');
  const [toId, setToId] = useState('');
  const [travelMinutes, setTravelMinutes] = useState('30');
  const [costUnits, setCostUnits] = useState('1');
  const [cooled, setCooled] = useState(false);
  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        run(
          () =>
            api.post('/api/create-connection', {
              fromLocationId: fromId,
              toLocationId: toId,
              travelMinutes: parseInt(travelMinutes || '0', 10),
              costUnits: parseInt(costUnits || '0', 10),
              cooled,
              active: true,
            }),
          'Connection created'
        );
      }}
    >
      <h3>Create connection</h3>
      <div className="field-row">
        <TextField id="cc-from" label="From location ID" value={fromId} onChange={setFromId} required />
        <TextField id="cc-to" label="To location ID" value={toId} onChange={setToId} required />
      </div>
      <div className="field-row">
        <TextField id="cc-travel" label="Travel minutes" value={travelMinutes} onChange={setTravelMinutes} />
        <TextField id="cc-cost" label="Cost units" value={costUnits} onChange={setCostUnits} />
      </div>
      <label style={{ display: 'inline-flex', gap: 6, fontWeight: 400 }}>
        <input type="checkbox" checked={cooled} onChange={(e) => setCooled(e.target.checked)} />
        Cooled transport
      </label>
      <div className="actions">
        <button className="primary" type="submit">Create connection</button>
      </div>
    </form>
  );
}

function ConnectionStatusForm({ run }: { run: Run }) {
  const [connectionId, setConnectionId] = useState('');
  const [active, setActive] = useState(true);
  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        run(
          () => api.post('/api/set-connection-status', { connectionId, active }),
          'Connection status updated'
        );
      }}
    >
      <h3>Activate / deactivate connection</h3>
      <div className="field-row">
        <TextField id="cs-id" label="Connection ID" value={connectionId} onChange={setConnectionId} required />
