func main() {
	databaseURL := os.Getenv("DATABASE_URL")
	if databaseURL == "" {
		databaseURL = "postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable"
	}
	var store *Store
	var err error
	for i := 0; i < 30; i++ {
		store, err = OpenStore(databaseURL)
		if err == nil {
			break
		}
		log.Printf("waiting for database: %v", err)
		time.Sleep(time.Second)
	}
	if err != nil {
		log.Fatalf("database unavailable: %v", err)
	}
	state, err := store.LoadState()
	if err != nil {
		log.Fatalf("load state: %v", err)
	}
	if state == nil {
		state = NewState()
	}
	seedSampleTypes(state)
	ensureAdmin(state)
	svc := NewService(store, state)
	if state.Snapshot.Version < 1 || state.Snapshot.Status == "" {
		svc.networkChanged()
	}
	if err := svc.persist(); err != nil {
		log.Fatalf("initial persist: %v", err)
	}
	go func() {
		ticker := time.NewTicker(2 * time.Second)
		defer ticker.Stop()
		for range ticker.C {
			svc.Sweep()
		}
	}()

	frontendDir := os.Getenv("FRONTEND_DIR")
	if frontendDir == "" {
		frontendDir = "/workspace/frontend/dist"
	}
	mux := http.NewServeMux()
	mux.HandleFunc("/ready", func(w http.ResponseWriter, r *http.Request) {
		if err := store.Ping(); err != nil {
			w.WriteHeader(http.StatusServiceUnavailable)
			_ = json.NewEncoder(w).Encode(J{"status": "unavailable"})
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(J{"status": "ready"})
	})
	mux.HandleFunc("/api/", svc.ServeAPI)
	mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		p := filepath.Clean(r.URL.Path)
		if strings.Contains(p, "..") {
			http.NotFound(w, r)
			return
		}
		full := filepath.Join(frontendDir, p)
		if p == "/" || p == "." {
			full = filepath.Join(frontendDir, "index.html")
		}
		if st, err := os.Stat(full); err == nil && !st.IsDir() {
			http.ServeFile(w, r, full)
			return
		}
		// SPA fallback
		http.ServeFile(w, r, filepath.Join(frontendDir, "index.html"))
	})
	addr := os.Getenv("LISTEN_ADDR")
	if addr == "" {
		addr = "127.0.0.1:8080"
	}
	log.Printf("listening on %s", addr)
	if err := http.ListenAndServe(addr, mux); err != nil {
		log.Fatal(err)
	}
}
