import React, { useCallback, useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { api, nowIso, uuid } from '../api';
import MapView, { MapMarker } from '../components/MapView';
import { JourneyPlan, OperationsState } from '../types';

export default function MonitorPage() {
  const [ops, setOps] = useState<OperationsState | null>(null);
  const [typeFilter, setTypeFilter] = useState('');
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const [plan, setPlan] = useState<JourneyPlan | null>(null);

  const load = useCallback(async (filter: string) => {
    try {
      const res = await api.post('/api/read-operations-state', {
        filters: filter ? { sampleTypeId: filter } : {},
      });
      setOps(res);
      setError('');
    } catch (e: any) {
      setError(e.message ?? 'Could not load operations state');
    }
  }, []);

  useEffect(() => {
    load(typeFilter);
  }, [load, typeFilter]);

  const run = async (fn: () => Promise<any>, okMsg: string) => {
    setNotice('');
    setError('');
    try {
      await fn();
      setNotice(okMsg);
      await load(typeFilter);
    } catch (e: any) {
      setError(e.message ?? 'Action failed');
    }
  };

  const viewPlan = async (journeyId: string) => {
    setError('');
    try {
      const res = await api.post('/api/read-journey-plan', { journeyId });
      setPlan(res);
    } catch (e: any) {
      setError(e.message ?? 'Could not load journey plan');
    }
  };

  const markers: MapMarker[] = [];
  if (ops) {
    for (const loc of ops.locations ?? []) {
      markers.push({
        id: `loc-${loc.locationId}`,
        lat: loc.coordinate.latitude,
        lng: loc.coordinate.longitude,
        label: `${loc.name} (${(loc.functions ?? []).join(', ')})`,
        color: loc.active ? '#1d4ed8' : '#94a3b8',
      });
    }
    for (const w of ops.workers ?? []) {
      if (w.latestLocation) {
        markers.push({
          id: `w-${w.workerId}`,
          lat: w.latestLocation.latitude,
          lng: w.latestLocation.longitude,
          label: `${w.fullName} — ${w.status}`,
          color: w.available ? '#16a34a' : '#94a3b8',
        });
      }
    }
    for (const s of ops.samples ?? []) {
      if (s.latestLocation) {
        markers.push({
          id: `s-${s.sampleId}`,
          lat: s.latestLocation.latitude,
          lng: s.latestLocation.longitude,
          label: `Sample ${s.sampleId} — ${s.status}`,
          color: '#b91c1c',
        });
      }
    }
  }

  return (
    <div>
      <h2>Operations monitor</h2>
      {error && <div className="alert error" role="alert">{error}</div>}
      {notice && <div className="alert ok" role="status">{notice}</div>}
      <div className="card">
        <div className="field-row">
          <div>
            <label htmlFor="typeFilter">Filter by sample type ID</label>
            <input
              id="typeFilter"
              value={typeFilter}
              onChange={(e) => setTypeFilter(e.target.value)}
              placeholder="Leave empty for all"
            />
          </div>
          <div>
            <label>Live map</label>
            <p className="muted" style={{ margin: 0 }}>
              Blue: locations · Green/grey: workers · Red: samples
            </p>
          </div>
        </div>
        <MapView markers={markers} height={420} />
      </div>
      {ops && (
        <>
          <div className="grid2">
            <div className="card">
              <h2>Workload fairness</h2>
              <dl className="kv">
                <dt>Assignment count spread</dt>
                <dd>{ops.assignmentCountSpread}</dd>
                <dt>Assignments with no eligible worker</dt>
                <dd>{ops.ineligibleAssignmentCount}</dd>
              </dl>
            </div>
            <div className="card">
              <h2>Report disruption</h2>
              <DisruptionForm run={run} />
            </div>
          </div>
          <div className="card">
            <h2>Samples</h2>
            <table aria-label="Samples">
              <thead>
                <tr>
                  <th>Sample</th>
                  <th>Status</th>
                  <th>Current holder</th>
                  <th>Last update</th>
                  <th>Location</th>
                </tr>
              </thead>
              <tbody>
                {(ops.samples ?? []).map((s) => (
                  <tr key={s.sampleId}>
                    <td>
                      <Link to={`/samples/${s.sampleId}`}>{s.sampleId}</Link>
                    </td>
                    <td>{s.status}</td>
                    <td>{s.currentHolderId ?? '—'}</td>
                    <td>{s.locationRecordedAt ? new Date(s.locationRecordedAt).toLocaleString() : '—'}</td>
                    <td>
                      <span className={`badge ${s.locationStale ? 'stale' : 'fresh'}`}>
                        {s.locationStale ? 'stale' : 'fresh'}
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="card">
            <h2>Routes / journeys</h2>
            <table aria-label="Journeys">
              <thead>
                <tr>
                  <th>Journey</th>
                  <th>Status</th>
                  <th>Mode</th>
                  <th>Plan version</th>
                  <th>Samples</th>
                  <th>Estimated delivery</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {(ops.routes ?? []).map((r) => (
                  <tr key={r.journeyId}>
                    <td>{r.journeyId}</td>
                    <td>{r.status}</td>
                    <td>{r.routeMode}</td>
                    <td>{r.planVersion}</td>
                    <td>{(r.sampleIds ?? []).length}</td>
                    <td>{r.estimatedDeliveryAt ? new Date(r.estimatedDeliveryAt).toLocaleString() : '—'}</td>
                    <td>
                      <div className="actions">
                        <button onClick={() => viewPlan(r.journeyId)}>View plan</button>
                        {(r.status === 'planned' || r.status === 'in_progress') && (
                          <>
                            <button
                              onClick={() => {
                                const reason = window.prompt('Reason for replan / reroute:') ?? 'replan';
                                run(
                                  () =>
                                    api.post('/api/reroute-journey', {
                                      journeyId: r.journeyId,
                                      expectedPlanVersion: r.planVersion,
                                      reason,
                                      idempotencyKey: uuid(),
                                    }),
                                  'Journey replanned'
                                );
                              }}
                            >
                              Reroute
                            </button>
                            <button
                              className="danger"
                              onClick={() => {
                                const reason = window.prompt('Reason for cancellation:') ?? 'cancelled';
                                run(
                                  () =>
                                    api.post('/api/cancel-journey', {
                                      journeyId: r.journeyId,
                                      expectedPlanVersion: r.planVersion,
                                      reason,
                                      idempotencyKey: uuid(),
                                    }),
                                  'Journey cancelled'
                                );
                              }}
                            >
                              Cancel
                            </button>
                          </>
                        )}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
            {plan && (
              <div style={{ marginTop: 12 }}>
                <h3>
                  Journey {plan.journeyId} — {plan.status} (plan version {plan.planVersion})
                </h3>
                <table aria-label="Journey legs">
                  <thead>
                    <tr>
                      <th>#</th>
                      <th>Kind</th>
                      <th>From</th>
                      <th>To</th>
                      <th>Status</th>
                    </tr>
                  </thead>
                  <tbody>
                    {(plan.legs ?? []).map((leg: any, i: number) => (
                      <tr key={leg.assignmentId ?? i}>
                        <td>{i + 1}</td>
                        <td>{leg.kind}</td>
                        <td>{leg.fromLocationId ?? '—'}</td>
                        <td>{leg.toLocationId ?? leg.nodeId ?? leg.laboratoryId ?? '—'}</td>
                        <td>{leg.status}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
          <div className="grid2">
            <div className="card">
              <h2>Exceptions</h2>
              {(ops.exceptions ?? []).length === 0 && <p className="muted">No exceptions.</p>}
              <ul>
                {(ops.exceptions ?? []).map((e, i) => (
                  <li key={i}>
                    <Link to={`/samples/${e.sampleId}`}>{e.sampleId}</Link> — {e.status} — {e.code}{' '}
                    {e.reason}
                  </li>
                ))}
              </ul>
            </div>
            <div className="card">
              <h2>Deadline risks</h2>
              {(ops.delays ?? []).length === 0 && <p className="muted">No journeys at risk.</p>}
              <ul>
                {(ops.delays ?? []).map((d, i) => (
                  <li key={i}>
                    Journey {d.journeyId} / sample {d.sampleId}: estimated{' '}
                    {new Date(d.estimatedDeliveryAt).toLocaleString()} vs deadline{' '}
                    {new Date(d.deliveryDeadline).toLocaleString()}
                  </li>
                ))}
              </ul>
            </div>
          </div>
          <div className="card">
            <h2>Workers</h2>
            <table aria-label="Workers">
              <thead>
                <tr>
                  <th>Worker</th>
                  <th>Roles</th>
                  <th>Status</th>
                  <th>Active assignments</th>
                  <th>Location</th>
                </tr>
              </thead>
              <tbody>
                {(ops.workers ?? []).map((w) => (
                  <tr key={w.workerId}>
                    <td>{w.fullName}</td>
                    <td>{(w.roles ?? []).join(', ')}</td>
                    <td>{w.status}</td>
                    <td>{w.assignmentCount}</td>
                    <td>
                      <span className={`badge ${w.locationStale ? 'stale' : 'fresh'}`}>
                        {w.locationStale ? 'stale' : 'fresh'}
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="card">
            <h2>Locations</h2>
            <table aria-label="Locations">
              <thead>
                <tr>
                  <th>Location</th>
                  <th>Functions</th>
                  <th>Status</th>
                  <th>Regular capacity</th>
                  <th>Cooled capacity</th>
                </tr>
              </thead>
              <tbody>
                {(ops.locations ?? []).map((l) => (
                  <tr key={l.locationId}>
                    <td>{l.name}</td>
                    <td>{(l.functions ?? []).join(', ')}</td>
                    <td>{l.active ? 'active' : 'inactive'}</td>
                    <td>
                      {l.capacity ? `${l.capacity.availableUnits}/${l.capacity.capacityUnits}` : '—'}
                    </td>
                    <td>
                      {l.capacity
                        ? `${l.capacity.cooledAvailableUnits}/${l.capacity.cooledCapacityUnits}`
                        : '—'}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </>
      )}
    </div>
  );
}

function DisruptionForm({ run }: { run: (fn: () => Promise<any>, okMsg: string) => Promise<void> }) {
  const [resourceType, setResourceType] = useState('worker');
  const [resourceId, setResourceId] = useState('');
  const [reason, setReason] = useState('');
  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        run(
          () =>
            api.post('/api/report-disruption', {
              resourceType,
              resourceId,
              reason,
              occurredAt: nowIso(),
              idempotencyKey: uuid(),
            }),
          'Disruption reported and replanning triggered'
        );
      }}
    >
      <label htmlFor="dResourceType">Resource type</label>
      <select
        id="dResourceType"
        value={resourceType}
        onChange={(e) => setResourceType(e.target.value)}
      >
        {['worker', 'node', 'location', 'connection', 'route', 'laboratory', 'capacity'].map((t) => (
          <option key={t} value={t}>{t}</option>
        ))}
      </select>
      <label htmlFor="dResourceId">Resource ID</label>
      <input
        id="dResourceId"
        value={resourceId}
        onChange={(e) => setResourceId(e.target.value)}
        required
      />
      <label htmlFor="dReason">Reason</label>
      <input id="dReason" value={reason} onChange={(e) => setReason(e.target.value)} required />
      <div className="actions">
        <button className="primary" type="submit">
          Report disruption
        </button>
      </div>
    </form>
  );
}

