import { enabledFunctions, OperationsState, ROLE_LABELS, ServiceabilitySnapshot } from '../types';

const ALL_ROLES = Object.keys(ROLE_LABELS) as Array<keyof typeof ROLE_LABELS>;
const FUNCTIONS = ['collection_point', 'transfer_point', 'hub', 'laboratory'];

export default function AdminPage() {
  const [ops, setOps] = useState<OperationsState | null>(null);
  const [snapshot, setSnapshot] = useState<ServiceabilitySnapshot | null>(null);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');

  const load = useCallback(async () => {
    try {
      const res = await api.post('/api/read-operations-state', { filters: {} });
      setOps(res);
      const snap = await api.post('/api/read-serviceability-snapshot', {});
      setSnapshot(snap);
      setError('');
    } catch (e: any) {
      setError(e.message ?? 'Could not load admin data');
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  const run = async (fn: () => Promise<any>, okMsg: string) => {
    setNotice('');
    setError('');
    try {
      await fn();
      setNotice(okMsg);
      await load();
    } catch (e: any) {
      setError(e.message ?? 'Action failed');
    }
  };

  return (
    <div>
      <h2>Administration</h2>
      {error && <div className="alert error" role="alert">{error}</div>}
      {notice && <div className="alert ok" role="status">{notice}</div>}

      <details className="card" open>
        <summary><strong>Users</strong></summary>
        <CreateUserForm run={run} />
        <UpdateUserForm run={run} />
        <WorkerAvailabilityForm run={run} />
      </details>

      <details className="card">
        <summary><strong>Locations</strong></summary>
        <CreateLocationForm run={run} />
        <LocationStatusForm run={run} />
        <LocationFunctionForm run={run} />
        {ops && (
          <table aria-label="Existing locations">
            <thead>
              <tr>
                <th>ID</th>
                <th>Name</th>
                <th>Functions</th>
                <th>Active</th>
                <th>Capacity</th>
              </tr>
            </thead>
            <tbody>
              {(ops.locations ?? []).map((l) => (
                <tr key={l.locationId}>
                  <td><code>{l.locationId}</code></td>
                  <td>{l.name}</td>
                  <td>{enabledFunctions(l.functions).join(', ')}</td>
                  <td>{l.active ? 'yes' : 'no'}</td>
                  <td>
                    {l.capacity
                      ? `regular ${l.capacity.availableUnits}/${l.capacity.capacityUnits}, cooled ${l.capacity.cooledAvailableUnits}/${l.capacity.cooledCapacityUnits}`
                      : '—'}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </details>

      <details className="card">
        <summary><strong>Connections</strong></summary>
        <CreateConnectionForm run={run} />
        <ConnectionStatusForm run={run} />
        {ops && (
          <table aria-label="Existing connections">
            <thead>
              <tr>
                <th>ID</th>
                <th>From</th>
                <th>To</th>
                <th>Travel (min)</th>
                <th>Cooled</th>
                <th>Active</th>
              </tr>
            </thead>
            <tbody>
              {(ops.connections ?? []).map((c) => (
                <tr key={c.connectionId}>
                  <td><code>{c.connectionId}</code></td>
                  <td>{c.fromLocationId}</td>
                  <td>{c.toLocationId}</td>
                  <td>{c.travelMinutes}</td>
                  <td>{c.cooled ? 'yes' : 'no'}</td>
                  <td>{c.active ? 'yes' : 'no'}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </details>

      <details className="card">
        <summary><strong>Sample types</strong></summary>
        <CreateSampleTypeForm run={run} />
        <UpdateSampleTypeForm run={run} />
      </details>

      <details className="card">
        <summary><strong>Capacity and laboratory acceptance</strong></summary>
        <CapacityForm run={run} />
        <LabAcceptanceForm run={run} />
      </details>

      <div className="card">
        <h2>Serviceability snapshot</h2>
        {snapshot ? (
          <>
            <dl className="kv">
              <dt>Version</dt>
              <dd>{snapshot.version}</dd>
              <dt>Status</dt>
              <dd>{snapshot.status}</dd>
              <dt>Computed at</dt>
              <dd>{snapshot.computedAt ? new Date(snapshot.computedAt).toLocaleString() : '—'}</dd>
              <dt>Network revision</dt>
              <dd>{snapshot.networkRevision}</dd>
              <dt>Active collection points</dt>
              <dd>{snapshot.activeCollectionPointCount}</dd>
            </dl>
            <table aria-label="Serviceability regions">
              <thead>
                <tr>
                  <th>Location</th>
                  <th>Name</th>
                  <th>Latitude</th>
                  <th>Longitude</th>
                  <th>Coverage (km)</th>
                </tr>
              </thead>
              <tbody>
                {(snapshot.regions ?? []).map((r) => (
                  <tr key={r.locationId}>
                    <td><code>{r.locationId}</code></td>
                    <td>{r.name}</td>
                    <td>{r.latitude}</td>
                    <td>{r.longitude}</td>
                    <td>{r.coverageKm}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </>
        ) : (
          <p className="muted">Loading…</p>
        )}
      </div>
    </div>
  );
}

type Run = (fn: () => Promise<any>, okMsg: string) => Promise<void>;

function TextField({ id, label, value, onChange, required }: {
  id: string; label: string; value: string; onChange: (v: string) => void; required?: boolean;
}) {
  return (
    <div>
      <label htmlFor={id}>{label}</label>
      <input id={id} value={value} onChange={(e) => onChange(e.target.value)} required={required} />
    </div>
  );
}

function CreateUserForm({ run }: { run: Run }) {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [fullName, setFullName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');
  const [roles, setRoles] = useState<string[]>([]);
  const [qualifications, setQualifications] = useState('');
  const [certifications, setCertifications] = useState('');
  const [assignedLocationId, setAssignedLocationId] = useState('');
  const toggleRole = (r: string) =>
    setRoles((cur) => (cur.includes(r) ? cur.filter((x) => x !== r) : [...cur, r]));
  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        run(
          () =>
            api.post('/api/create-user', {
              username,
              initialPassword: password,
              email,
              fullName,
              phone,
              roles,
              qualifications: qualifications.split(',').map((s) => s.trim()).filter(Boolean),
              certifications: certifications.split(',').map((s) => s.trim()).filter(Boolean),
              active: true,
              assignedLocationId,
            }),
          `User ${username} created`
        );
      }}
    >
      <h3>Create user</h3>
      <div className="field-row">
        <TextField id="cu-username" label="Username" value={username} onChange={setUsername} required />
        <TextField id="cu-password" label="Initial password" value={password} onChange={setPassword} required />
      </div>
      <div className="field-row">
        <TextField id="cu-fullname" label="Full name" value={fullName} onChange={setFullName} required />
        <TextField id="cu-email" label="Email" value={email} onChange={setEmail} />
      </div>
      <div className="field-row">
        <TextField id="cu-phone" label="Phone" value={phone} onChange={setPhone} />
        <TextField
          id="cu-assigned"
          label="Assigned node / laboratory ID"
          value={assignedLocationId}
          onChange={setAssignedLocationId}
        />
      </div>
      <fieldset style={{ border: '1px solid #e2e5ec', borderRadius: 6, margin: '8px 0' }}>
        <legend>Roles</legend>
        {ALL_ROLES.map((r) => (
          <label key={r} style={{ display: 'inline-flex', gap: 4, marginRight: 12, fontWeight: 400 }}>
            <input type="checkbox" checked={roles.includes(r)} onChange={() => toggleRole(r)} />
            {ROLE_LABELS[r]}
          </label>
        ))}
      </fieldset>
      <div className="field-row">
        <TextField
          id="cu-quals"
          label="Qualifications (comma separated)"
          value={qualifications}
          onChange={setQualifications}
        />
        <TextField
          id="cu-certs"
          label="Certifications (comma separated)"
          value={certifications}
          onChange={setCertifications}
        />
      </div>
      <div className="actions">
        <button className="primary" type="submit">Create user</button>
      </div>
    </form>
  );
}

