function CreateLocationForm({ run }: { run: Run }) {
  const [name, setName] = useState('');
  const [lat, setLat] = useState('12.9716');
  const [lng, setLng] = useState('77.5946');
  const [coverageKm, setCoverageKm] = useState('5');
  const [handlingMinutes, setHandlingMinutes] = useState('10');
  const [functions, setFunctions] = useState<string[]>(['collection_point']);
  const toggle = (f: string) =>
    setFunctions((cur) => (cur.includes(f) ? cur.filter((x) => x !== f) : [...cur, f]));
  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        run(
          () =>
            api.post('/api/create-location', {
              name,
              coordinate: { latitude: parseFloat(lat), longitude: parseFloat(lng) },
              coverageKm: parseFloat(coverageKm),
              handlingMinutes: parseInt(handlingMinutes || '0', 10),
              active: true,
              functions,
            }),
          `Location ${name} created`
        );
      }}
    >
      <h3>Create location</h3>
      <div className="field-row">
        <TextField id="cl-name" label="Name" value={name} onChange={setName} required />
        <TextField id="cl-coverage" label="Coverage (km)" value={coverageKm} onChange={setCoverageKm} />
      </div>
      <div className="field-row">
        <TextField id="cl-lat" label="Latitude" value={lat} onChange={setLat} required />
        <TextField id="cl-lng" label="Longitude" value={lng} onChange={setLng} required />
      </div>
      <div className="field-row">
        <TextField id="cl-handling" label="Handling minutes" value={handlingMinutes} onChange={setHandlingMinutes} />
        <div />
      </div>
      <fieldset style={{ border: '1px solid #e2e5ec', borderRadius: 6, margin: '8px 0' }}>
        <legend>Functions</legend>
        {FUNCTIONS.map((f) => (
          <label key={f} style={{ display: 'inline-flex', gap: 4, marginRight: 12, fontWeight: 400 }}>
            <input type="checkbox" checked={functions.includes(f)} onChange={() => toggle(f)} />
            {f}
          </label>
        ))}
      </fieldset>
      <div className="actions">
        <button className="primary" type="submit">Create location</button>
      </div>
    </form>
  );
}

