	for _, id := range j.CollectionAssignmentIDs {
		s.offerAssignment(s.state.Assignments[id])
	}
	for _, id := range j.LegIDs {
		s.offerAssignment(s.state.Assignments[id])
	}
	for _, id := range j.NodeAssignmentIDs {
		s.offerAssignment(s.state.Assignments[id])
	}
	for _, id := range j.LaboratoryAssignmentIDs {
		s.offerAssignment(s.state.Assignments[id])
	}
	s.emit("journey.created", "journey", j.ID, map[string]interface{}{
		"journeyId": j.ID, "sampleIds": j.SampleIDs, "routeMode": j.RouteMode,
	})
