	case RoleDispatcher, RoleAdministrator:
		journeys := []*Journey{}
		for _, j := range s.state.Journeys {
			journeys = append(journeys, j)
		}
		sort.Slice(journeys, func(i, j int) bool { return journeys[i].CreatedAt.Before(journeys[j].CreatedAt) })
		for _, j := range journeys {
			if !matchStatus(j.Status) {
				continue
			}
			v := s.journeyWorkItemView(j)
			switch j.Status {
			case JourneyPlanned:
				pending = append(pending, v)
			case JourneyInProgress:
				inProgress = append(inProgress, v)
			default:
				completed = append(completed, v)
			}
		}
	default:
		// worker roles: assignments offered to or accepted by the user
		items := []*Assignment{}
		for _, a := range s.state.Assignments {
			if a.Kind != "" && kindRole(a.Kind) == role &&
				(a.OfferedToWorkerID == c.user.ID || a.AcceptedWorkerID == c.user.ID) {
				items = append(items, a)
			}
		}
		sort.Slice(items, func(i, j int) bool { return items[i].CreatedAt.Before(items[j].CreatedAt) })
		for _, a := range items {
			if !matchStatus(a.Status) {
				continue
			}
			v := s.assignmentWorkItemView(a)
			switch a.Status {
			case AsgOffered, AsgPending:
				pending = append(pending, v)
			case AsgAccepted, AsgInProgress:
				inProgress = append(inProgress, v)
			default:
				completed = append(completed, v)
			}
		}
	}
	c.audit("list_role_work", "", "", "", true, map[string]interface{}{"role": role})
	return 200, J{"pending": pending, "inProgress": inProgress, "completed": completed}, nil
