// wsToken extracts the session token from the Sec-WebSocket-Protocol header.
// Clients authenticate by offering a "bearer.<base64url(token)>" subprotocol.
func wsToken(r *http.Request) string {
	for _, hdr := range r.Header.Values("Sec-WebSocket-Protocol") {
		for _, p := range strings.Split(hdr, ",") {
			p = strings.TrimSpace(p)
			if !strings.HasPrefix(p, "bearer.") {
