package main

import (
	"encoding/json"
	"fmt"
	"sort"
	"sync"
	"time"
)

type Service struct {
	mu            sync.Mutex
	store         *Store
	state         *State
	pendingAudits []*AuditRow
	pendingEvents []*EventRow
	hub           *WSHub
}

func NewService(store *Store, state *State) *Service {
	return &Service{store: store, state: state, hub: NewWSHub()}
}

func (s *Service) audit(actorID, role, action, entityType, entityID, sampleID string, success bool, details map[string]interface{}) {
	if details == nil {
		details = map[string]interface{}{}
	}
	raw, _ := json.Marshal(details)
	s.pendingAudits = append(s.pendingAudits, &AuditRow{
		AuditID:    newUUID(),
		ActorID:    actorID,
		Role:       role,
		Action:     action,
		EntityType: entityType,
		EntityID:   entityID,
		SampleID:   sampleID,
		Success:    success,
		OccurredAt: time.Now().UTC(),
		Details:    raw,
	})
}

func (s *Service) emit(eventType, entityType, entityID string, payload interface{}) {
	raw, _ := json.Marshal(payload)
	s.pendingEvents = append(s.pendingEvents, &EventRow{
		Type: eventType, EntityType: entityType, EntityID: entityID, Payload: raw,
	})
}

func (s *Service) persist() error {
	audits := s.pendingAudits
	events := s.pendingEvents
	if err := s.store.Persist(s.state, audits, events); err != nil {
		return err
	}
	s.pendingAudits = nil
	s.pendingEvents = nil
	for _, e := range events {
		s.hub.Broadcast(e)
	}
	return nil
}

func (s *Service) networkChanged() {
	s.state.NetworkRevision++
	regions := []ServiceabilityRegion{}
	count := 0
	for _, loc := range s.state.Locations {
		if loc.Implicit {
			continue
		}
		if loc.Active && loc.HasFunction(LocCollectionPoint) {
			count++
			regions = append(regions, ServiceabilityRegion{
				LocationID: loc.ID, Name: loc.Name,
				Latitude: loc.Coordinate.Latitude, Longitude: loc.Coordinate.Longitude,
				CoverageKm: loc.CoverageKm,
			})
		}
	}
	sort.Slice(regions, func(i, j int) bool { return regions[i].LocationID < regions[j].LocationID })
	s.state.Snapshot = ServiceabilitySnapshot{
		Version: s.state.NetworkRevision, Status: "complete", ComputedAt: time.Now().UTC(),
		NetworkRevision: s.state.NetworkRevision, Regions: regions,
		ActiveCollectionPointCount: count,
	}
	if s.state.Snapshot.Version < 1 {
		s.state.Snapshot.Version = 1
	}
}

// ---------------- eligibility & offering ----------------

func kindRole(kind string) string {
	switch kind {
	case KindCollection:
		return RoleCollectionPro
	case KindTransport:
		return RoleDeliveryPartner
	case KindNode:
		return RoleNodeHandler
	case KindLaboratory:
		return RoleLaboratoryTeam
	}
	return ""
}

func (s *Service) activeAssignmentCount(workerID string) int {
	n := 0
	for _, a := range s.state.Assignments {
		if a.AcceptedWorkerID == workerID && (a.Status == AsgAccepted || a.Status == AsgInProgress) {
			n++
		}
	}
	return n
}

// eligibleWorkers returns workers eligible for the assignment, ignoring the
// declined-by list. qualifiedOnly ignores availability and capacity.
func (s *Service) eligibleWorkers(a *Assignment, qualifiedOnly bool) []*User {
	role := kindRole(a.Kind)
	sample := s.state.Samples[a.SampleID]
	out := []*User{}
	for _, u := range s.state.Users {
		if !u.Active || !u.HasRole(role) {
			continue
		}
		switch a.Kind {
		case KindCollection:
			if sample != nil {
				st := s.state.SampleTypes[sample.SampleTypeID]
				if st != nil && st.QualifiedCollectorRequired && !u.HasQualification(st.RequiredQualification) {
					continue
				}
			}
		case KindNode:
			if u.AssignedLocationID != a.NodeID {
				continue
			}
		case KindLaboratory:
			if u.AssignedLocationID != a.LaboratoryID {
				continue
			}
		}
		if !qualifiedOnly {
			if !u.Available {
				continue
			}
			if u.CapacityUnits >= 0 && s.activeAssignmentCount(u.ID) >= u.CapacityUnits {
				continue
			}
		}
		out = append(out, u)
	}
	return out
}

// offerAssignment offers the assignment to the fairest eligible worker.
func (s *Service) offerAssignment(a *Assignment) {
	candidates := []*User{}
	for _, u := range s.eligibleWorkers(a, false) {
		if containsString(a.DeclinedBy, u.ID) {
			continue
		}
		candidates = append(candidates, u)
	}
	if len(candidates) == 0 {
		a.Status = AsgPending
		a.OfferedToWorkerID = ""
		a.OfferExpiresAt = nil
		return
	}
	now := time.Now().UTC()
	sort.Slice(candidates, func(i, j int) bool {
		ci, cj := candidates[i], candidates[j]
		pi := ci.DeclinePenaltyUntil != nil && ci.DeclinePenaltyUntil.After(now)
		pj := cj.DeclinePenaltyUntil != nil && cj.DeclinePenaltyUntil.After(now)
		if pi != pj {
			return !pi
		}
		ai, aj := s.activeAssignmentCount(ci.ID), s.activeAssignmentCount(cj.ID)
		if ai != aj {
			return ai < aj
		}
		if ci.AssignmentCount != cj.AssignmentCount {
			return ci.AssignmentCount < cj.AssignmentCount
		}
		return ci.CreatedAt.Before(cj.CreatedAt)
	})
	chosen := candidates[0]
	a.Status = AsgOffered
	a.OfferedToWorkerID = chosen.ID
	t := now
	a.OfferedAt = &t
	exp := now.Add(offerTimeoutSeconds * time.Second)
	a.OfferExpiresAt = &exp
	s.audit("", "", "assignment.offered", "assignment", a.ID, a.SampleID, true, map[string]interface{}{
		"workerId": chosen.ID, "kind": a.Kind, "offerExpiresAt": fmtTime(exp),
	})
	s.emit("assignment.offered", "assignment", a.ID, map[string]interface{}{
		"assignmentId": a.ID, "workerId": chosen.ID, "kind": a.Kind, "sampleId": a.SampleID,
	})
}

func (s *Service) recordDecline(a *Assignment, workerID, reason string) {
	if !containsString(a.DeclinedBy, workerID) {
		a.DeclinedBy = append(a.DeclinedBy, workerID)
	}
	if u := s.state.Users[workerID]; u != nil {
		u.DeclineCount++
		if u.DeclineCount >= 2 {
			until := time.Now().UTC().Add(5 * time.Minute)
			u.DeclinePenaltyUntil = &until
		}
	}
	s.audit("", "", "assignment.declined", "assignment", a.ID, a.SampleID, true, map[string]interface{}{
		"workerId": workerID, "reason": reason,
	})
	s.emit("assignment.declined", "assignment", a.ID, map[string]interface{}{
		"assignmentId": a.ID, "workerId": workerID, "reason": reason,
	})
}

// ---------------- routing ----------------

type routePlan struct {
	EntryID         string
	LabID           string
	NodePath        []string // entry .. lab
	ConnPath        []string
	Leg1Minutes     int // origin -> entry travel when origin is not the entry node
	TravelMinutes   int // connection travel minutes
	HandlingMinutes int
	Cost            float64
}

// dijkstra computes shortest travel times from entry over active connections.
func (s *Service) dijkstra(entryID string, cooledOnly, checkCapacity bool, cooled bool) (map[string]int, map[string]string) {
	dist := map[string]int{entryID: 0}
	prev := map[string]string{} // node -> connection id used to reach it
	visited := map[string]bool{}
	for {
		var cur string
		best := -1
		for n, d := range dist {
			if !visited[n] && (best < 0 || d < best) {
				cur, best = n, d
			}
		}
		if cur == "" {
			break
		}
		visited[cur] = true
		for _, conn := range s.state.Connections {
			if !conn.Active {
				continue
			}
			var next string
			if conn.FromLocationID == cur {
				next = conn.ToLocationID
			} else if conn.ToLocationID == cur {
				next = conn.FromLocationID
			} else {
				continue
			}
			loc := s.state.Locations[next]
			if loc == nil || !loc.Active || loc.Implicit {
				continue
			}
			if cooledOnly && !conn.Cooled {
				continue
			}
			if checkCapacity && conn.Capacity.Available(cooled) < 1 {
				continue
			}
			nd := best + conn.TravelMinutes
			if d, ok := dist[next]; !ok || nd < d {
				dist[next] = nd
				prev[next] = conn.ID
			}
		}
	}
	return dist, prev
}

func (s *Service) labAccepts(lab *Location, sampleTypeID string) bool {
	return containsString(lab.AcceptedSampleTypeIDs, sampleTypeID)
}

// findRoute searches for the best route from any entry node to an accepting lab.
// mode: 0 = structural only (ignore capacity), 1 = require capacity.
func (s *Service) findRoute(entryIDs []string, sampleType *SampleType, checkCapacity bool) *routePlan {
	var best *routePlan
	for _, entryID := range entryIDs {
		dist, prev := s.dijkstra(entryID, sampleType.RequiresCooledRoute, checkCapacity, sampleType.RequiresCooledRoute)
		for _, loc := range s.state.Locations {
			if loc.Implicit || !loc.Active || !loc.HasFunction(LocLaboratory) {
				continue
			}
			if !s.labAccepts(loc, sampleType.ID) {
				continue
			}
			d, ok := dist[loc.ID]
			if !ok {
				continue
			}
			if checkCapacity && loc.Capacity.Available(sampleType.RequiresCooledRoute) < 1 {
				continue
			}
			// rebuild path
			conns := []string{}
			nodes := []string{loc.ID}
			cur := loc.ID
			for cur != entryID {
				connID, ok := prev[cur]
				if !ok {
					break
				}
				conns = append([]string{connID}, conns...)
				conn := s.state.Connections[connID]
				if conn.FromLocationID == cur {
					cur = conn.ToLocationID
				} else {
					cur = conn.FromLocationID
				}
				nodes = append([]string{cur}, nodes...)
			}
			if cur != entryID {
				continue
			}
			handling := 0
			okPath := true
			for i, n := range nodes {
				if i == 0 || i == len(nodes)-1 {
					continue
				}
				nl := s.state.Locations[n]
				handling += nl.HandlingMinutes
				if checkCapacity && nl.Capacity.Available(sampleType.RequiresCooledRoute) < 1 {
					okPath = false
					break
				}
			}
			if !okPath {
				continue
			}
			cost := 0.0
			for _, cid := range conns {
				cost += s.state.Connections[cid].CostUnits
			}
			rp := &routePlan{
				EntryID: entryID, LabID: loc.ID, NodePath: nodes, ConnPath: conns,
				TravelMinutes: d, HandlingMinutes: handling, Cost: cost,
			}
			if best == nil || rp.TravelMinutes+rp.HandlingMinutes < best.TravelMinutes+best.HandlingMinutes {
				best = rp
			}
		}
	}
	return best
}

// entryNodesForOrigin resolves candidate entry collection points for an origin.
// Returns (entryIDs, error code) — code is "" on success.
func (s *Service) entryNodesForOrigin(origin Coordinate, originType, originNodeID string) ([]string, string) {
	if originType == "node" {
		loc := s.state.Locations[originNodeID]
		if loc == nil || loc.Implicit {
			return nil, "invalid_origin"
		}
		if !loc.Active || !loc.HasFunction(LocCollectionPoint) {
			return nil, "outside_service_coverage"
		}
		return []string{loc.ID}, ""
	}
	ids := []string{}
	for _, loc := range s.state.Locations {
		if loc.Implicit || !loc.Active || !loc.HasFunction(LocCollectionPoint) {
			continue
		}
		if haversineKm(origin, loc.Coordinate) <= loc.CoverageKm {
			ids = append(ids, loc.ID)
		}
	}
	if len(ids) == 0 {
		return nil, "outside_service_coverage"
	}
	sort.Strings(ids)
	return ids, ""
}

type serviceabilityResult struct {
	Serviceable   bool
	Reason        string
	TargetLabID   string
	EstimatedArrival time.Time
	Plan          *routePlan
}

func (s *Service) checkServiceability(origin Coordinate, originType, originNodeID string, sampleType *SampleType, requestedAt, deadline, earliestCollection time.Time) serviceabilityResult {
	entryIDs, code := s.entryNodesForOrigin(origin, originType, originNodeID)
	if code == "invalid_origin" {
		return serviceabilityResult{Serviceable: false, Reason: "outside_service_coverage"}
	}
	if code != "" {
		return serviceabilityResult{Serviceable: false, Reason: code}
	}
	// any active lab accepting the type?
	anyLab := false
	for _, loc := range s.state.Locations {
		if !loc.Implicit && loc.Active && loc.HasFunction(LocLaboratory) && s.labAccepts(loc, sampleType.ID) {
			anyLab = true
			break
		}
	}
	if !anyLab {
		return serviceabilityResult{Serviceable: false, Reason: "no_accepting_laboratory"}
	}
	structural := s.findRoute(entryIDs, sampleType, false)
	if structural == nil {
		if sampleType.RequiresCooledRoute {
			return serviceabilityResult{Serviceable: false, Reason: "no_route"}
		}
		return serviceabilityResult{Serviceable: false, Reason: "no_route"}
	}
	withCap := s.findRoute(entryIDs, sampleType, true)
	if withCap == nil {
		return serviceabilityResult{Serviceable: false, Reason: "insufficient_capacity"}
	}
	start := requestedAt
	if earliestCollection.After(start) {
		start = earliestCollection
	}
	leg1 := 0
	if originType != "node" {
		entry := s.state.Locations[withCap.EntryID]
		leg1 = int(haversineKm(origin, entry.Coordinate)*2 + 0.5) // ~30km/h
		if leg1 < 1 {
			leg1 = 1
		}
	}
	withCap.Leg1Minutes = leg1
	arrival := start.Add(time.Duration(leg1+withCap.TravelMinutes+withCap.HandlingMinutes) * time.Minute)
	if arrival.After(deadline) {
		return serviceabilityResult{Serviceable: false, Reason: "deadline_unreachable", Plan: withCap}
	}
	return serviceabilityResult{
		Serviceable: true, Reason: "serviceable", TargetLabID: withCap.LabID,
		EstimatedArrival: arrival, Plan: withCap,
	}
}

// ---------------- journey construction ----------------

func (s *Service) getOrCreateOriginLocation(req *Request) *Location {
	if req.OriginLocationID != "" {
		return s.state.Locations[req.OriginLocationID]
	}
	if req.OriginType == "node" {
		return s.state.Locations[req.OriginNodeID]
	}
	loc := &Location{
		ID: newUUID(), Name: fmt.Sprintf("Origin (%s)", req.OriginType),
		Coordinate: req.Origin, CoverageKm: 0.1, HandlingMinutes: 0, Active: true,
		Functions: map[string]bool{}, Implicit: true, CreatedAt: time.Now().UTC(),
	}
	s.state.Locations[loc.ID] = loc
	req.OriginLocationID = loc.ID
	return loc
}

// buildJourney creates stops, legs, assignments and capacity reservations.
// startAt is when the sample can start moving (collection time).
func (s *Service) buildJourney(sample *Sample, req *Request, plan *routePlan, startAt time.Time, withCollection bool) *Journey {
	now := time.Now().UTC()
	originLoc := s.getOrCreateOriginLocation(req)
	sample.OriginLocationID = originLoc.ID
	j := &Journey{
		ID: newUUID(), PlanVersion: 1, Status: JourneyPlanned,
		SampleIDs: []string{sample.ID}, ReplanStatus: ReplanNotRequired,
		TotalCostUnits: plan.Cost, CreatedAt: now,
	}
	t := startAt
	// pickup stop at origin
	pickup := &Stop{
		ID: newUUID(), LocationID: originLoc.ID, StopType: "pickup", Sequence: 1,
		EstimatedAt: t, DwellMinutes: 0, Coordinate: originLoc.Coordinate,
	}
	j.Stops = append(j.Stops, pickup)
	seq := 1
	// leg from origin to entry when origin is not the entry node
	fromLocID := originLoc.ID
	if originLoc.ID != plan.EntryID {
		t = t.Add(time.Duration(plan.Leg1Minutes) * time.Minute)
		seq++
		entryLoc := s.state.Locations[plan.EntryID]
		entryIsLab := plan.EntryID == plan.LabID
		stopType := "handoff"
		dwell := entryLoc.HandlingMinutes
		if entryIsLab {
			stopType = "delivery"
			dwell = 0
		}
		stop := &Stop{
			ID: newUUID(), LocationID: plan.EntryID, StopType: stopType, Sequence: seq,
			EstimatedAt: t, DwellMinutes: dwell, Coordinate: entryLoc.Coordinate,
		}
		j.Stops = append(j.Stops, stop)
		leg := s.newTransportAssignment(j, sample, len(j.LegIDs)+1, fromLocID, plan.EntryID, "")
		j.LegIDs = append(j.LegIDs, leg.ID)
		if !entryIsLab {
			nodeAsg := s.newNodeAssignment(j, sample, plan.EntryID)
			j.NodeAssignmentIDs = append(j.NodeAssignmentIDs, nodeAsg.ID)
			entryLoc.Capacity.Reserve(sampleRequiresCooled(s, sample))
			t = t.Add(time.Duration(entryLoc.HandlingMinutes) * time.Minute)
		}
		fromLocID = plan.EntryID
	}
	// connection legs
	for i, connID := range plan.ConnPath {
		conn := s.state.Connections[connID]
		next := conn.ToLocationID
		if conn.FromLocationID != fromLocID {
			next = conn.FromLocationID
		}
		t = t.Add(time.Duration(conn.TravelMinutes) * time.Minute)
		nextLoc := s.state.Locations[next]
		isLab := next == plan.LabID
		stopType := "handoff"
		if isLab {
			stopType = "delivery"
		}
		dwell := 0
		if !isLab {
			dwell = nextLoc.HandlingMinutes
		}
		seq++
		stop := &Stop{
			ID: newUUID(), LocationID: next, StopType: stopType, Sequence: seq,
			EstimatedAt: t, DwellMinutes: dwell, Coordinate: nextLoc.Coordinate,
		}
		j.Stops = append(j.Stops, stop)
		leg := s.newTransportAssignment(j, sample, len(j.LegIDs)+1, fromLocID, next, connID)
		j.LegIDs = append(j.LegIDs, leg.ID)
		conn.Capacity.Reserve(sampleRequiresCooled(s, sample))
		if !isLab {
			nodeAsg := s.newNodeAssignment(j, sample, next)
			j.NodeAssignmentIDs = append(j.NodeAssignmentIDs, nodeAsg.ID)
			nextLoc.Capacity.Reserve(sampleRequiresCooled(s, sample))
			t = t.Add(time.Duration(nextLoc.HandlingMinutes) * time.Minute)
		}
		fromLocID = next
		_ = i
	}
	// direct case: entry node is the lab
	if plan.EntryID == plan.LabID && originLoc.ID == plan.EntryID {
		seq++
		stop := &Stop{
			ID: newUUID(), LocationID: plan.LabID, StopType: "delivery", Sequence: seq,
			EstimatedAt: t, DwellMinutes: 0, Coordinate: s.state.Locations[plan.LabID].Coordinate,
		}
		j.Stops = append(j.Stops, stop)
	}
	labAsg := s.newLaboratoryAssignment(j, sample, plan.LabID)
	j.LaboratoryAssignmentIDs = append(j.LaboratoryAssignmentIDs, labAsg.ID)
	lab := s.state.Locations[plan.LabID]
	lab.Capacity.Reserve(sampleRequiresCooled(s, sample))
	if withCollection {
		coll := s.newCollectionAssignment(j, sample, originLoc.ID)
		j.CollectionAssignmentIDs = append(j.CollectionAssignmentIDs, coll.ID)
	}
	j.EstimatedDeliveryAt = t
	if len(j.LegIDs) <= 1 {
		j.RouteMode = "direct"
	} else {
		j.RouteMode = "multi_stop"
	}
	s.state.Journeys[j.ID] = j
	sample.ActiveJourneyID = j.ID
	sample.TargetLaboratoryID = plan.LabID
	// offer all assignments
	for _, id := range j.CollectionAssignmentIDs {
		s.offerAssignment(s.state.Assignments[id])
	}
	for _, id := range j.LegIDs {
		s.offerAssignment(s.state.Assignments[id])
	}
	for _, id := range j.NodeAssignmentIDs {
		s.offerAssignment(s.state.Assignments[id])
	}
	for _, id := range j.LaboratoryAssignmentIDs {
		s.offerAssignment(s.state.Assignments[id])
	}
	s.emit("journey.created", "journey", j.ID, map[string]interface{}{
		"journeyId": j.ID, "sampleIds": j.SampleIDs, "routeMode": j.RouteMode,
	})
	return j
}

func sampleRequiresCooled(s *Service, sample *Sample) bool {
	st := s.state.SampleTypes[sample.SampleTypeID]
	return st != nil && st.RequiresCooledRoute
}

func (s *Service) newTransportAssignment(j *Journey, sample *Sample, seq int, from, to, connID string) *Assignment {
	a := &Assignment{
		ID: newUUID(), Kind: KindTransport, JourneyID: j.ID, SampleID: sample.ID,
		Sequence: seq, FromLocationID: from, ToLocationID: to, ConnectionID: connID,
		Status: AsgPending, CreatedAt: time.Now().UTC(),
	}
	s.state.Assignments[a.ID] = a
	return a
}

func (s *Service) newNodeAssignment(j *Journey, sample *Sample, nodeID string) *Assignment {
	a := &Assignment{
		ID: newUUID(), Kind: KindNode, JourneyID: j.ID, SampleID: sample.ID,
		Sequence: 0, NodeID: nodeID, ExpectedSampleTypeID: sample.SampleTypeID,
		Status: AsgPending, CreatedAt: time.Now().UTC(),
	}
	s.state.Assignments[a.ID] = a
	return a
}

func (s *Service) newLaboratoryAssignment(j *Journey, sample *Sample, labID string) *Assignment {
	a := &Assignment{
		ID: newUUID(), Kind: KindLaboratory, JourneyID: j.ID, SampleID: sample.ID,
		Sequence: 0, LaboratoryID: labID, ExpectedSampleTypeID: sample.SampleTypeID,
		Status: AsgPending, CreatedAt: time.Now().UTC(),
	}
	s.state.Assignments[a.ID] = a
	return a
}

func (s *Service) newCollectionAssignment(j *Journey, sample *Sample, atLocationID string) *Assignment {
	a := &Assignment{
		ID: newUUID(), Kind: KindCollection, JourneyID: j.ID, SampleID: sample.ID,
		Sequence: 0, FromLocationID: atLocationID, ToLocationID: atLocationID,
		ExpectedSampleTypeID: sample.SampleTypeID,
		Status:   AsgPending, CreatedAt: time.Now().UTC(),
	}
	s.state.Assignments[a.ID] = a
	return a
}

// cancelUnfinishedAssignments cancels all non-completed assignments of a journey
// and releases their capacity reservations.
func (s *Service) cancelUnfinishedAssignments(j *Journey, reason string) {
	sample := &Sample{}
	if len(j.SampleIDs) > 0 {
		sample = s.state.Samples[j.SampleIDs[0]]
	}
	cooled := false
	if sample != nil && sample.ID != "" {
		cooled = sampleRequiresCooled(s, sample)
	}
	cancelOne := func(a *Assignment) {
		if a == nil || a.Status == AsgCompleted || a.Status == AsgCancelled {
			return
		}
		a.Status = AsgCancelled
		if a.Kind == KindTransport && a.ConnectionID != "" {
			if conn := s.state.Connections[a.ConnectionID]; conn != nil {
				conn.Capacity.Release(cooled)
			}
		}
		if a.Kind == KindNode {
			if loc := s.state.Locations[a.NodeID]; loc != nil {
				loc.Capacity.Release(cooled)
			}
		}
		if a.Kind == KindLaboratory {
			if loc := s.state.Locations[a.LaboratoryID]; loc != nil {
				loc.Capacity.Release(cooled)
			}
		}
		s.audit("", "", "assignment.cancelled", "assignment", a.ID, a.SampleID, true, map[string]interface{}{
			"reason": reason, "kind": a.Kind,
		})
	}
	for _, id := range j.CollectionAssignmentIDs {
		cancelOne(s.state.Assignments[id])
	}
	for _, id := range j.LegIDs {
		cancelOne(s.state.Assignments[id])
	}
	for _, id := range j.NodeAssignmentIDs {
		cancelOne(s.state.Assignments[id])
	}
	for _, id := range j.LaboratoryAssignmentIDs {
		cancelOne(s.state.Assignments[id])
	}
}

// samplePositionNode returns the network node where the sample currently is,
// for replanning purposes.
func (s *Service) samplePositionNode(sample *Sample) string {
	j := s.state.Journeys[sample.ActiveJourneyID]
	if j == nil {
		return sample.OriginLocationID
	}
	var lastCompleted *Stop
	for _, st := range j.Stops {
		if st.CompletedAt != nil {
			if lastCompleted == nil || st.Sequence > lastCompleted.Sequence {
				lastCompleted = st
			}
		}
	}
	if lastCompleted != nil {
		loc := s.state.Locations[lastCompleted.LocationID]
		if loc != nil && !loc.Implicit {
			return loc.ID
		}
	}
	// fall back to first handoff stop (entry node) or origin
	for _, st := range j.Stops {
		if st.StopType == "handoff" {
			return st.LocationID
		}
	}
	if len(j.Stops) > 0 {
		return j.Stops[0].LocationID
	}
	return sample.OriginLocationID
}

// replanSample builds a replacement journey for the unfinished part of a sample.
// Returns (replacementJourney, replanStatus).
func (s *Service) replanSample(sample *Sample, reason string) (*Journey, string) {
	old := s.state.Journeys[sample.ActiveJourneyID]
	if old == nil {
		return nil, ReplanNotRequired
	}
	// cancel any existing active replacement plan first (only one active)
	for _, rid := range sample.ActiveReplacementPlanIDs {
		if rj := s.state.Journeys[rid]; rj != nil && (rj.Status == JourneyPlanned || rj.Status == JourneyInProgress) {
			s.cancelUnfinishedAssignments(rj, "superseded")
			rj.Status = JourneyCancelled
		}
	}
	sample.ActiveReplacementPlanIDs = nil

	plan, req, start, failStatus := s.planSampleRoute(sample, reason)
	if plan == nil {
		return nil, failStatus
	}
	// preserve completed work in old journey; cancel unfinished
	s.cancelUnfinishedAssignments(old, reason)
	old.Status = JourneyReplaced
	old.ReplanStatus = ReplanReplaced

	// build replacement journey from current position
	nj := s.buildJourney(sample, req, plan, start, !sample.Sealed)
	nj.ParentJourneyID = old.ID
	old.ReplacementJourneyID = nj.ID
	sample.ActiveReplacementPlanIDs = []string{nj.ID}
	sample.ActiveJourneyID = nj.ID
	sample.TargetLaboratoryID = plan.LabID
	s.audit("", "", "journey.replanned", "journey", nj.ID, sample.ID, true, map[string]interface{}{
		"parentJourneyId": old.ID, "reason": reason,
	})
	s.emit("journey.replanned", "journey", nj.ID, map[string]interface{}{
		"journeyId": nj.ID, "parentJourneyId": old.ID, "sampleId": sample.ID,
	})
	return nj, ReplanReplaced
}

// planSampleRoute computes a fresh route for a sample. Uncollected samples
// route from their original origin (collection still has to happen there);
// sealed samples route from their current position node. On failure the
// sample is marked exception/expired and a non-empty failStatus is returned.
func (s *Service) planSampleRoute(sample *Sample, reason string) (*routePlan, *Request, time.Time, string) {
	sampleType := s.state.SampleTypes[sample.SampleTypeID]
	if sampleType == nil {
		s.markSampleException(sample, "no_valid_route", "no valid route", reason)
		return nil, nil, time.Time{}, ReplanException
	}
	start := time.Now().UTC()
	if start.Before(sample.EarliestCollectionAt) {
		start = sample.EarliestCollectionAt
	}
	req := &Request{
		ID: sample.RequestID, RequesterID: sample.RequesterID,
		RequestedAt: start, DeliveryDeadline: sample.DeliveryDeadline,
		EarliestCollectionAt: start, LatestCollectionAt: sample.LatestCollectionAt,
		SampleTypeID: sample.SampleTypeID,
	}
	var entryIDs []string
	if !sample.Sealed {
		req.Origin = sample.Origin
		req.OriginType = sample.OriginType
		req.OriginLocationID = sample.OriginLocationID
		ids, code := s.entryNodesForOrigin(sample.Origin, sample.OriginType, "")
		if code != "" {
			s.expireOrExcept(sample, reason)
			return nil, nil, time.Time{}, sample.ReplanStatusFor(reason)
		}
		entryIDs = ids
	} else {
		posLoc := s.state.Locations[s.samplePositionNode(sample)]
		if posLoc == nil {
			s.markSampleException(sample, "no_valid_route", "no valid route", reason)
			return nil, nil, time.Time{}, ReplanException
		}
		req.Origin = posLoc.Coordinate
		req.OriginType = "node"
		req.OriginNodeID = posLoc.ID
		req.OriginLocationID = posLoc.ID
		if !posLoc.Implicit && posLoc.Active {
			entryIDs = []string{posLoc.ID}
		} else {
			ids, code := s.entryNodesForOrigin(sample.Origin, sample.OriginType, "")
			if code != "" {
				s.expireOrExcept(sample, reason)
				return nil, nil, time.Time{}, sample.ReplanStatusFor(reason)
			}
			entryIDs = ids
		}
	}
	plan := s.findRoute(entryIDs, sampleType, true)
	if plan == nil {
		s.expireOrExcept(sample, reason)
		return nil, nil, time.Time{}, sample.ReplanStatusFor(reason)
	}
	arrival := start.Add(time.Duration(plan.TravelMinutes+plan.HandlingMinutes) * time.Minute)
	if arrival.After(sample.DeliveryDeadline) {
		sample.Status = SampleExpired
		sample.Exception = &ExceptionInfo{Code: "deadline_exceeded", Reason: "no valid route can meet the delivery deadline", OccurredAt: time.Now().UTC()}
		s.audit("", "", "sample.expired", "sample", sample.ID, sample.ID, true, map[string]interface{}{"reason": reason})
		s.emit("sample.expired", "sample", sample.ID, map[string]interface{}{"sampleId": sample.ID})
		return nil, nil, time.Time{}, ReplanExpired
	}
	return plan, req, start, ""
}

// buildSplitJourney creates a fresh journey for a sample being split out of a
// shared journey, leaving the parent journey and its other samples untouched.
func (s *Service) buildSplitJourney(sample *Sample, parent *Journey) (*Journey, string) {
	plan, req, start, failStatus := s.planSampleRoute(sample, "split")
	if plan == nil {
		return nil, failStatus
	}
	nj := s.buildJourney(sample, req, plan, start, !sample.Sealed)
	nj.ParentJourneyID = parent.ID
	s.audit("", "", "journey.replanned", "journey", nj.ID, sample.ID, true, map[string]interface{}{
		"parentJourneyId": parent.ID, "reason": "split",
	})
	return nj, ReplanReplaced
}

func (s *Service) expireOrExcept(sample *Sample, reason string) {
	// no route at all: if deadline already tight, expire; otherwise exception
	sample.Status = SampleException
	sample.Exception = &ExceptionInfo{Code: "no_valid_route", Reason: "no valid route available after disruption", OccurredAt: time.Now().UTC(), Details: reason}
	s.audit("", "", "sample.exception", "sample", sample.ID, sample.ID, true, map[string]interface{}{
		"code": "no_valid_route", "reason": reason,
	})
	s.emit("sample.exception", "sample", sample.ID, map[string]interface{}{"sampleId": sample.ID, "code": "no_valid_route"})
}

func (sample *Sample) ReplanStatusFor(reason string) string {
	if sample.Status == SampleExpired {
		return ReplanExpired
	}
	return ReplanException
}

func (s *Service) markSampleException(sample *Sample, code, reason, details string) {
	sample.Status = SampleException
	sample.Exception = &ExceptionInfo{Code: code, Reason: reason, OccurredAt: time.Now().UTC(), Details: details}
	s.audit("", "", "sample.exception", "sample", sample.ID, sample.ID, true, map[string]interface{}{
		"code": code, "reason": reason, "details": details,
	})
	s.emit("sample.exception", "sample", sample.ID, map[string]interface{}{"sampleId": sample.ID, "code": code})
}

// nextAssignmentForHandoff finds the assignment that should receive custody next.
func (s *Service) nextAssignmentForHandoff(sample *Sample, fromAsg *Assignment) *Assignment {
	j := s.state.Journeys[sample.ActiveJourneyID]
	if j == nil {
		return nil
	}
	isActive := func(a *Assignment) bool {
		return a != nil && (a.Status == AsgAccepted || a.Status == AsgInProgress)
	}
	switch fromAsg.Kind {
	case KindCollection:
		// next is first transport leg, or laboratory assignment if no legs
		for _, id := range j.LegIDs {
			if a := s.state.Assignments[id]; isActive(a) {
				return a
			}
		}
		for _, id := range j.LaboratoryAssignmentIDs {
			if a := s.state.Assignments[id]; isActive(a) {
				return a
			}
		}
	case KindTransport:
		// next is node assignment at destination, or laboratory assignment
		for _, id := range j.NodeAssignmentIDs {
			a := s.state.Assignments[id]
			if isActive(a) && a.NodeID == fromAsg.ToLocationID {
				return a
			}
		}
		for _, id := range j.LaboratoryAssignmentIDs {
			a := s.state.Assignments[id]
			if isActive(a) && a.LaboratoryID == fromAsg.ToLocationID {
				return a
			}
		}
	case KindNode:
		// next is the transport leg leaving this node
		for _, id := range j.LegIDs {
			a := s.state.Assignments[id]
			if isActive(a) && a.FromLocationID == fromAsg.NodeID {
				return a
			}
		}
		// or the laboratory assignment if node is the lab
		for _, id := range j.LaboratoryAssignmentIDs {
			a := s.state.Assignments[id]
			if isActive(a) && a.LaboratoryID == fromAsg.NodeID {
				return a
			}
		}
	}
	return nil
}

// ---------------- background sweeper ----------------

func (s *Service) Sweep() {
	s.mu.Lock()
	defer s.mu.Unlock()
	now := time.Now().UTC()
	changed := false
	for _, a := range s.state.Assignments {
		if a.Status == AsgOffered && a.OfferExpiresAt != nil && a.OfferExpiresAt.Before(now) {
			workerID := a.OfferedToWorkerID
			s.recordDecline(a, workerID, "offer_expired")
			s.offerAssignment(a)
			changed = true
		}
		if a.Status == AsgPending {
			before := a.Status
			s.offerAssignment(a)
			if a.Status != before {
				changed = true
			}
		}
	}
	// flag samples whose assignment has no qualified worker at all
	for _, a := range s.state.Assignments {
		if a.Status != AsgPending {
			continue
		}
		if now.Sub(a.CreatedAt) < noQualifiedWorkerGraceSeconds*time.Second {
			continue
		}
		if len(s.eligibleWorkers(a, true)) == 0 {
			sample := s.state.Samples[a.SampleID]
			if sample != nil && sample.NoQualifiedFlaggedAt == nil &&
				sample.Status != SampleReceived && sample.Status != SampleCancelled &&
				sample.Status != SampleExpired {
				t := now
				sample.NoQualifiedFlaggedAt = &t
				s.markSampleException(sample, "no_qualified_worker",
					fmt.Sprintf("no qualified worker available for %s assignment", a.Kind), "")
				changed = true
			}
		}
	}
	if changed {
		if err := s.persist(); err != nil {
			fmt.Println("sweep persist error:", err)
		}
	}
}

